impl PromptKind {
    fn label(self) -> &'static str {
        match self {
            PromptKind::Plan => "plan",
            PromptKind::Design => "design",
            PromptKind::Explain => "explain",
            PromptKind::Review => "review",
            PromptKind::Refactor => "refactor",
            PromptKind::Implement => "implement",
            PromptKind::Intent => "intent",
            PromptKind::EvolveContract => "evolve-contract",
            PromptKind::Prune => "prune",
            PromptKind::Evidence => "evidence",
            PromptKind::Drift => "drift",
        }
    }

    fn prompt_id(self) -> &'static str {
        match self {
            PromptKind::Plan => "rms.plan@v1",
            PromptKind::Design => "rms.design@v1",
            PromptKind::Explain => "rms.explain@v1",
            PromptKind::Review => "rms.review@v1",
            PromptKind::Refactor => "rms.refactor@v1",
            PromptKind::Implement => "rms.implement@v1",
            PromptKind::Intent => "rms.intent@v1",
            PromptKind::EvolveContract => "rms.evolve-contract@v1",
            PromptKind::Prune => "rms.prune@v1",
            PromptKind::Evidence => "rms.evidence@v1",
            PromptKind::Drift => "rms.drift@v1",
        }
    }

    fn default_task(self) -> Option<&'static str> {
        match self {
            PromptKind::Review => Some("review the diff for RMS conformance"),
            PromptKind::Explain => Some("explain how this module works"),
            PromptKind::Design => Some("design RMS module boundaries and semantic scaffold shapes"),
            PromptKind::Drift => {
                Some("identify drift between canonical RMS artifacts and implementation reality")
            }
            _ => None,
        }
    }

    fn includes_diff_by_default(self) -> bool {
        matches!(self, PromptKind::Review)
    }

    fn workflow(self) -> &'static [&'static str] {
        match self {
            PromptKind::Plan => &[
                "Treat RMS as the semantic and architecture gate: meaning changes require an RMS semantic-change object and `rms spec apply`; direct file edits may only fill declared role bodies.",
                "Restate the requested outcome in the owning context's domain language.",
                "Check whether the task reveals a new honest module boundary before assuming the current module is sufficient.",
                "Identify the owning module and smallest affected public semantic or runnable surface.",
                "Classify the change as private implementation, invariant/domain policy, public contract, dependency/effect, state/migration, or workflow.",
                "Name affected invariants, effects, compatibility promises, and recovery paths.",
                "Choose semantic shape before file layout: representation, message envelopes, transition outputs, transition records, ports, adapters, trace roles, and evidence.",
                "Choose representation obligations: closed variants, validated constructors, explicit results, boundary schemas, or lifecycle state when behavior depends on order.",
                "Propose the smallest implementation and verification path.",
            ],
            PromptKind::Design => &[
                "Treat RMS design output as advisory until module manifests, contracts, implementation bindings, semantic-change applications, and focused machine-change applications reflect it.",
                "Start from system purpose, contexts, existing modules, glossary language, and the requested task.",
                "Propose the smallest honest module set; do not create a module for every noun.",
                "Assign each module a semantic shape: domain-engine, boundary-adapter, runtime-monitor, workflow, storage-adapter, integration-adapter, or composite.",
                "Separate pure decisions from external effects, and name required module dependencies.",
                "Define representation obligations: closed variants, validated values, commands, states, events, accepted/rejected outcomes, boundary schemas, and runnable surfaces when outside input reaches the module.",
                "Resolve semantic edge cases before file layout: invalid commands, illegal transitions, terminal states, stale or conflicting state, parser failures, numeric overflow or rounding, and effect failure categories.",
                "Define focused evidence: laws, contract scenarios, boundary parser tests, numeric boundary tests, runtime monitor trigger/non-trigger cases, transition records, replay bundles, first-bad-transition proof, fuzz/property checks, recovery, or reconciliation.",
                "Treat provider output and generated plans as advisory evidence until reflected in canonical artifacts.",
            ],
            PromptKind::Explain => &[
                "Answer from the bounded RMS context first: purpose, ownership, public contracts, invariants, effects, profiles, and verification.",
                "Keep the explanation intelligible, simple, and direct without dumbing down the module semantics.",
                "Use the user's question as the focus when supplied.",
                "Do not invent architecture that is absent from the manifest or contracts.",
                "Name uncertainty or missing artifacts instead of guessing.",
            ],
            PromptKind::Review => &[
                "Review the diff against the module manifest, public contracts, direct dependencies, declared effects, profiles, and verification evidence.",
                "Flag semantic roles, state variants, transitions, effects, runnable surfaces, public entrypoints, parsers, or evidence added by hand instead of through RMS CLI artifacts as architecture-gate bypasses.",
                "Find behavioral regressions, boundary violations, undeclared effects or dependencies, compatibility drift, missing evidence, and stale canonical artifacts.",
                "Prioritize findings by severity and include file or artifact references when possible.",
                "Do not treat generated prose, issue text, or incidental implementation shape as architectural authority.",
            ],
            PromptKind::Refactor => &[
                "Preserve public contracts, invariants, declared effects, compatibility, and verification meaning.",
                "If refactoring reveals new laws, contracts, states, commands, events, effects, runnable surfaces, public entrypoints, semantic roles, or evidence obligations, return an RMS semantic-change object before editing files.",
                "Identify weak representation, duplicated concepts, decision/effect coupling, ownership confusion, boundary leakage, lifecycle clutter, or semantic residue.",
                "Prefer semantic roles over conventional helper names: representation, message envelopes, transition output, transition records, ports, adapters, trace roles, and evidence.",
                "Prefer deletion, inlining, renaming, or representation strengthening before new abstractions.",
                "Escalate to implement-change or evolve-contract if public meaning must change.",
            ],
            PromptKind::Implement => &[
                "RMS owns semantics and architecture, and agents fill declared roles: use `rms spec plan/apply/check` when laws, contracts, machine structure, runnable surfaces, effects, or evidence obligations change, then edit only declared role files.",
                "Restate the requested outcome in the owning context's domain language.",
                "Check whether accepted intent and rationale already exist for this semantic change; if not, stop and run intent capture before coding.",
                "Classify the change as private implementation, invariant or domain policy, public contract, dependency or effect, state or migration, or workflow.",
                "Check whether the task requires scope expansion or a module split before deepening the current module.",
                "Keep the change inside the owning module boundary.",
                "Update public contracts or manifests first when public meaning changes.",
                "Update linked intent, decision, contract, law, and evidence records together when accepted semantics evolve.",
                "Name affected invariants, contracts, effects, compatibility promises, and recovery paths.",
                "Separate domain decisions from external effects where practical.",
                "Keep private helpers pure inside pure role files; model IO as declared effects/effect-results executed only in adapter, port, or effect-executor roles.",
                "Use semantic implementation roles before file-level code: representation, message envelopes, transition output, transition records, ports, adapters, trace roles, and evidence.",
                "Resolve semantic edge cases before implementation: impossible variants, invalid constructors, illegal transitions, malformed boundary input, stale or conflicting state, and terminal-state behavior.",
                "Use the strongest available representation for invalid states, expected failures, boundary input, and lifecycle transitions.",
                "Add the smallest evidence that demonstrates the changed promise.",
                "Return concrete implementation instructions; do not claim edits were made unless the executing agent actually made them.",
            ],
            PromptKind::Intent => &[
                "Think before code: do not propose implementation steps until intent, rationale, contracts, and evidence obligations are understood.",
                "Normalize the human request into atomic stories with actors, state, actions, success results, failure results, and stale or conflicting-state behavior.",
                "Ask only the questions needed to resolve product, domain, ownership, source-of-truth, lifecycle, compatibility, or operational ambiguity.",
                "Synthesize accepted intent into candidate contracts, laws, invariants, glossary terms, ownership, effects, compatibility impact, and proof lanes.",
                "Separate raw conversation notes from accepted rationale; raw prompt output is evidence, not semantic authority.",
                "Name the canonical artifacts that must change before implementation: intent notes, decision records, glossary, module manifest, contracts, laws, runnable surface declarations, and verification evidence.",
                "Stop at an implementation gate when accepted intent is missing or contradictions exist among canonical artifacts.",
            ],
            PromptKind::EvolveContract => &[
                "Identify all published contract versions and known consumers.",
                "Classify compatibility impact across shape, meaning, failures, authorization, idempotency, ordering, consistency, timeout, retry, stored state, and operations.",
                "Preserve the existing version when compatibility can be maintained cleanly.",
                "Introduce a new version for breaking changes and define migration, coexistence, translation, and deprecation behavior.",
            ],
            PromptKind::Prune => &[
                "Build a semantic root set from manifests, contracts, invariants, effects, profiles, compatibility policy, operational recovery, implementation binding, and verification evidence.",
                "Classify candidate artifacts by current semantic role.",
                "Delete, merge, inline, rename, or document residue before introducing replacements.",
                "Do not hide a semantic change as pruning.",
            ],
            PromptKind::Evidence => &[
                "Identify the changed promise and the evidence category it belongs to: law, contract, scenario, boundary, runnable surface, runtime, reconciliation, or migration.",
                "For machine-shaped behavior, request transition records, replay bundles, golden timelines, effect-result handling, and first-bad-transition proof where applicable.",
                "Prefer the smallest evidence that strongly demonstrates the promise.",
                "Include negative evidence for impossible variants, invalid constructors, malformed boundary input, and illegal transitions when applicable.",
                "Name the manifest paths or implementation binding entries that should reference the evidence.",
                "Replace scaffold placeholder, bootstrap, unpinned, and semantic-shape-only evidence before marking implemented modules done.",
            ],
            PromptKind::Drift => &[
                "Compare manifest purpose, ownership, contracts, effects, profiles, compatibility policy, verification evidence, and glossary language against implementation reality.",
                "Identify contradictions among canonical artifacts as architectural drift, not a prompt-precedence problem.",
                "Separate deterministic validation failures from semantic suspicions requiring human review.",
                "Propose the smallest artifact or implementation correction for each drift item.",
            ],
        }
    }

    fn expected_output(self) -> &'static [&'static str] {
        match self {
            PromptKind::Plan => &[
                "Owning module and affected contract surface.",
                "Whether a new module boundary or semantic shape is required.",
                "Change classification and compatibility impact.",
                "Affected invariants, effects, dependencies, profiles, and recovery paths.",
                "Implementation outline inside the owning boundary.",
                "Focused verification plan and commands.",
            ],
            PromptKind::Design => &[
                "Recommended module set and semantic shape for each module.",
                "Recommended module tree, including a composite parent when several semantic modules form one public capability.",
                "Owned concepts, data, decisions, public contracts, dependencies, effects, and profiles.",
                "Semantic structure before code: ADTs or closed variants, validated values, commands, states, events, result and rejection types, and transition boundaries.",
                "Edge-case decisions: invalid commands, illegal transitions, terminal states, boundary parse failures, stale or conflicting state, and not-applicable cases.",
                "Representation obligations for ADTs, validated values, commands, states, events, and result/rejection types.",
                "Trace, law, fuzz/property, contract, boundary, runtime monitor, recovery, or reconciliation evidence.",
                "Scope boundaries and assumptions.",
            ],
            PromptKind::Explain => &[
                "Intelligible plain-language explanation of how the module works.",
                "Important public contracts and owned decisions.",
                "Effects, invariants, and verification evidence that shape behavior.",
                "Any missing or ambiguous canonical artifacts relevant to the question.",
            ],
            PromptKind::Review => &[
                "Findings first, ordered by severity.",
                "Each finding names the violated RMS artifact or missing evidence.",
                "Open questions or assumptions.",
                "Brief change summary only after findings.",
            ],
            PromptKind::Refactor => &[
                "Public semantics preserved.",
                "Internal shape changes proposed.",
                "Boundary, dependency, and effect impact.",
                "Verification needed to prove compatibility.",
            ],
            PromptKind::Implement => &[
                "Requested outcome in owning-context language.",
                "Scope expansion or module split decision.",
                "Change classification and compatibility impact.",
                "Concrete implementation steps.",
                "Contract/manifest updates required before code changes.",
                "Semantic structure before code: representation, command/state/result ADTs, transition model, parser boundaries, and evidence roles.",
                "Resolved edge cases before implementation: invalid commands, illegal transitions, malformed input, terminal states, stale or conflicting state, and expected effect failures.",
                "Representation choices for invalid states, failures, boundary schemas, or lifecycle transitions.",
                "Verification and conformance evidence.",
            ],
            PromptKind::Intent => &[
                "Normalized stories and accepted interpretation.",
                "Questions asked, answers accepted, and unresolved product decisions.",
                "Candidate contracts, laws, invariants, ownership, source of truth, effects, compatibility, and proof lanes.",
                "Rationale and rejected alternatives to preserve in decision records.",
                "Canonical artifacts to update before implementation.",
                "Implementation gate result: ready, blocked on questions, or drift detected.",
            ],
            PromptKind::EvolveContract => &[
                "Compatibility classification.",
                "Versioning decision.",
                "Migration, coexistence, translation, and deprecation plan.",
                "Provider and consumer evidence updates.",
            ],
            PromptKind::Prune => &[
                "Semantic root set.",
                "Artifacts to delete, merge, inline, rename, retain, or defer.",
                "Compatibility and evidence impact.",
                "Removal conditions for retained residue.",
            ],
            PromptKind::Evidence => &[
                "Evidence category and rationale.",
                "Positive and negative cases.",
                "Manifest or implementation binding references to update.",
                "Native command expected to run the evidence.",
                "Placeholder/bootstrap/source-pinning diagnostics resolved for modules claimed as implemented.",
            ],
            PromptKind::Drift => &[
                "Confirmed drift.",
                "Suspected drift requiring review.",
                "Canonical artifact or implementation source of each mismatch.",
                "Smallest correction path.",
            ],
        }
    }

    fn deterministic_checks(self) -> &'static [&'static str] {
        match self {
            PromptKind::Explain
            | PromptKind::Design
            | PromptKind::Plan
            | PromptKind::Intent
            | PromptKind::Evidence
            | PromptKind::Drift => &["rms validate --root <root>", "rms compose --root <root>"],
            PromptKind::Review
            | PromptKind::Refactor
            | PromptKind::Implement
            | PromptKind::Prune => &[
                "rms validate --root <root>",
                "rms spec check <module.yaml|implementation.yaml>",
                "rms machine check <implementation.yaml>",
                "rms verify <implementation.yaml|composite-module.yaml>",
                "rms compose --root <root>",
            ],
            PromptKind::EvolveContract => &[
                "rms check-compat <old-module.yaml> <new-module.yaml>",
                "rms validate --root <root>",
                "rms compose --root <root>",
            ],
        }
    }
}

impl Provider {
    fn label(self) -> &'static str {
        match self {
            Provider::None => "none",
            Provider::Codex => "codex",
        }
    }
}

impl CodexSandbox {
    fn as_str(self) -> &'static str {
        match self {
            CodexSandbox::ReadOnly => "read-only",
            CodexSandbox::WorkspaceWrite => "workspace-write",
        }
    }
}

impl ProviderWriteScope {
    fn as_str(self) -> &'static str {
        match self {
            ProviderWriteScope::Module => "module",
            ProviderWriteScope::Root => "root",
        }
    }
}

fn resolve_prompt_run_options(root: &Path, raw: RawPromptRunOptions) -> Result<PromptRunOptions> {
    if raw.ai && raw.provider.is_some() {
        bail!("use either `--ai` or `--provider`, not both");
    }

    let config = load_workbench_config(root)?;
    let config_value = config.as_ref().map(|loaded| &loaded.value);

    let provider = if raw.ai {
        let configured = config_value
            .and_then(|config| config.ai.default_provider.as_deref())
            .ok_or_else(|| {
                anyhow!(
                    "`--ai` requires `{}` with `ai.default_provider`",
                    root.join(WORKBENCH_CONFIG_PATH).display()
                )
            })?;
        let provider = parse_config_provider(configured, "ai.default_provider")?;
        if provider == Provider::None {
            bail!("`--ai` requires a non-`none` `ai.default_provider`");
        }
        provider
    } else {
        raw.provider.unwrap_or(Provider::None)
    };

    let run_root = raw
        .run_root
        .or_else(|| config_value.and_then(|config| config.runs.directory.clone()))
        .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT));

    let model = raw.model.or_else(|| {
        if provider == Provider::Codex {
            config_value.and_then(|config| config.ai.codex.model.clone())
        } else {
            None
        }
    });

    let sandbox = if let Some(sandbox) = raw.sandbox {
        sandbox
    } else if provider == Provider::Codex {
        config_value
            .and_then(|config| config.ai.codex.sandbox.as_deref())
            .map(|value| parse_config_sandbox(value, "ai.codex.sandbox"))
            .transpose()?
            .unwrap_or(CodexSandbox::ReadOnly)
    } else {
        CodexSandbox::ReadOnly
    };

    let write_scope = if let Some(write_scope) = raw.write_scope {
        write_scope
    } else if provider == Provider::Codex {
        config_value
            .and_then(|config| config.ai.codex.write_scope.as_deref())
            .map(|value| parse_config_write_scope(value, "ai.codex.write_scope"))
            .transpose()?
            .unwrap_or_else(|| {
                if matches!(sandbox, CodexSandbox::WorkspaceWrite) {
                    ProviderWriteScope::Module
                } else {
                    ProviderWriteScope::Root
                }
            })
    } else {
        ProviderWriteScope::Root
    };

    let provider_timeout_seconds = if let Some(timeout_seconds) = raw.provider_timeout_seconds {
        timeout_seconds
    } else if provider == Provider::Codex {
        config_value
            .and_then(|config| config.ai.codex.timeout_seconds)
            .map(|value| parse_config_timeout_seconds(value, "ai.codex.timeout_seconds"))
            .transpose()?
            .unwrap_or(DEFAULT_PROVIDER_TIMEOUT_SECONDS)
    } else {
        DEFAULT_PROVIDER_TIMEOUT_SECONDS
    };

    Ok(PromptRunOptions {
        provider,
        record: raw.record,
        run_root,
        model,
        sandbox,
        write_scope,
        provider_timeout_seconds,
    })
}

fn resolve_run_root(root: &Path, explicit: Option<PathBuf>) -> Result<PathBuf> {
    if let Some(path) = explicit {
        return Ok(path);
    }
    Ok(load_workbench_config(root)?
        .and_then(|loaded| loaded.value.runs.directory)
        .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT)))
}

fn load_workbench_config(root: &Path) -> Result<Option<LoadedWorkbenchConfig>> {
    let path = root.join(WORKBENCH_CONFIG_PATH);
    if !path.exists() {
        return Ok(None);
    }
    let source = fs::read_to_string(&path)
        .with_context(|| format!("failed to read `{}`", path.display()))?;
    let value: WorkbenchConfig = serde_yaml::from_str(&source)
        .with_context(|| format!("failed to parse `{}`", path.display()))?;
    Ok(Some(LoadedWorkbenchConfig { path, value }))
}

fn run_config_init(
    root: &Path,
    provider: Provider,
    model: Option<&str>,
    run_root: &Path,
    force: bool,
) -> Result<()> {
    let path = root.join(WORKBENCH_CONFIG_PATH);
    if path.exists() && !force {
        bail!(
            "workbench config already exists at `{}`; pass `--force` to overwrite",
            path.display()
        );
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("failed to create `{}`", parent.display()))?;
    }
    let rendered = render_workbench_config(provider, model, run_root);
    fs::write(&path, rendered).with_context(|| format!("failed to write `{}`", path.display()))?;
    println!("created {}", path.display());
    Ok(())
}

fn run_agent_diagnose(root: &Path, target: AgentTarget) -> Result<()> {
    let report = build_agent_integration_report(root, target);
    print_agent_integration_report(&report);
    Ok(())
}

fn run_agent_init(root: &Path, target: AgentTarget, force: bool) -> Result<()> {
    fs::create_dir_all(root)
        .with_context(|| format!("failed to create agent root `{}`", root.display()))?;
    write_agent_guidance(root, target, force, true)?;
    println!(
        "initialized {} agent guidance at {}",
        target.label(),
        root.display()
    );
    Ok(())
}

fn run_agent_sync(root: &Path, target: AgentTarget) -> Result<()> {
    fs::create_dir_all(root)
        .with_context(|| format!("failed to create agent root `{}`", root.display()))?;
    write_agent_guidance(root, target, true, false)?;
    println!(
        "synced {} agent guidance at {}",
        target.label(),
        root.display()
    );
    Ok(())
}

fn write_agent_guidance(
    root: &Path,
    target: AgentTarget,
    overwrite_guidance: bool,
    write_config: bool,
) -> Result<()> {
    write_agent_file(&root.join("AGENTS.md"), INIT_AGENTS_MD, overwrite_guidance)?;
    if target == AgentTarget::Claude {
        write_agent_file(&root.join("CLAUDE.md"), INIT_CLAUDE_MD, overwrite_guidance)?;
    }
    sync_agent_skills(root, target, overwrite_guidance)?;
    let config_path = root.join(WORKBENCH_CONFIG_PATH);
    if write_config || !config_path.exists() {
        write_agent_file(
            &config_path,
            &render_workbench_config(Provider::Codex, None, Path::new(DEFAULT_RUN_ROOT)),
            overwrite_guidance,
        )?;
    }
    Ok(())
}

fn write_agent_file(path: &Path, contents: &str, overwrite: bool) -> Result<()> {
    if overwrite {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(path, contents)
            .with_context(|| format!("failed to write `{}`", path.display()))?;
        Ok(())
    } else {
        write_new_file(path, contents)
    }
}

fn sync_agent_skills(root: &Path, target: AgentTarget, overwrite: bool) -> Result<()> {
    let skills_root = target.skill_root(root);
    for (relative_path, contents) in INIT_AGENT_SKILLS {
        write_agent_file(&skills_root.join(relative_path), contents, overwrite)?;
    }
    Ok(())
}

fn build_agent_integration_report(root: &Path, target: AgentTarget) -> AgentIntegrationReport {
    let local_skills = agent_skills_readiness(root, target);
    let config = diagnose_config(root);
    let target_tool = Some(target.target_tool());
    let mut guidance = vec![
        "The RMS CLI is sufficient; plugins and global skills are optional adapters.".to_string(),
        format!(
            "Use `rms agent init --target {} --root .` to create missing project-local guidance.",
            target.label()
        ),
        format!(
            "Use `rms agent sync --target {} --root .` after upgrading RMS to refresh generated guidance.",
            target.label()
        ),
    ];
    if config.status == "missing" {
        guidance.push("Project-local `.rms/config.yaml` is missing; agent init will create safe read-only Codex defaults.".to_string());
    }
    if !local_skills.missing.is_empty() || !local_skills.drifted.is_empty() {
        guidance.push(format!(
            "Local RMS skills are missing or stale; run `rms agent sync --target {} --root .`.",
            target.label()
        ));
    }
    if target == AgentTarget::Claude && !root.join("CLAUDE.md").exists() {
        guidance.push(
            "Claude target expects project-local `CLAUDE.md` that imports `AGENTS.md`.".to_string(),
        );
    }

    AgentIntegrationReport {
        target: target.label().to_string(),
        root: root.display().to_string(),
        agent_instructions: file_readiness("AGENTS.md", &root.join("AGENTS.md")),
        target_instructions: match target {
            AgentTarget::Codex => None,
            AgentTarget::Claude => Some(file_readiness("CLAUDE.md", &root.join("CLAUDE.md"))),
        },
        local_skills,
        config,
        target_tool,
        plugin_required: false,
        guidance,
    }
}

fn agent_skills_readiness(root: &Path, target: AgentTarget) -> AgentSkillsReadiness {
    let skills_root = target.skill_root(root);
    let mut missing = Vec::new();
    let mut drifted = Vec::new();
    let mut expected = BTreeSet::new();

    for (relative_path, contents) in INIT_AGENT_SKILLS {
        expected.insert((*relative_path).to_string());
        let path = skills_root.join(relative_path);
        match fs::read_to_string(&path) {
            Ok(actual) if actual == *contents => {}
            Ok(_) => drifted.push((*relative_path).to_string()),
            Err(_) => missing.push((*relative_path).to_string()),
        }
    }

    let mut extra = Vec::new();
    collect_agent_skill_files(&skills_root, &skills_root, &mut extra).ok();
    extra.retain(|path| !expected.contains(path));

    let status = if !skills_root.exists() {
        "missing"
    } else if missing.is_empty() && drifted.is_empty() {
        "present"
    } else {
        "stale"
    };

    AgentSkillsReadiness {
        directory: skills_root.display().to_string(),
        status: status.to_string(),
        expected: INIT_AGENT_SKILLS.len(),
        missing,
        drifted,
        extra,
    }
}

fn collect_agent_skill_files(root: &Path, path: &Path, output: &mut Vec<String>) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }
    for entry in
        fs::read_dir(path).with_context(|| format!("failed to read `{}`", path.display()))?
    {
        let entry = entry?;
        let entry_path = entry.path();
        if entry_path.is_dir() {
            collect_agent_skill_files(root, &entry_path, output)?;
        } else if entry_path.file_name().and_then(|name| name.to_str()) == Some("SKILL.md") {
            if let Ok(relative) = entry_path.strip_prefix(root) {
                output.push(relative.display().to_string());
            }
        }
    }
    Ok(())
}

fn print_agent_integration_report(report: &AgentIntegrationReport) {
    println!("# RMS Agent Integration");
    println!();
    println!("Target: {}", report.target);
    println!("Root: {}", report.root);
    println!("Plugin required: {}", report.plugin_required);
    println!();

    println!("## Project Guidance");
    println!(
        "{}: {} ({})",
        report.agent_instructions.name,
        report.agent_instructions.status,
        report.agent_instructions.path
    );
    if let Some(target_instructions) = &report.target_instructions {
        println!(
            "{}: {} ({})",
            target_instructions.name, target_instructions.status, target_instructions.path
        );
    }
    println!(
        "local skills: {} ({}, expected {})",
        report.local_skills.status, report.local_skills.directory, report.local_skills.expected
    );
    print_string_list("missing skills", &report.local_skills.missing);
    print_string_list("drifted skills", &report.local_skills.drifted);
    print_string_list("extra skills", &report.local_skills.extra);
    println!();

    println!("## Workbench Config");
    println!("{}: {}", report.config.path, report.config.status);
    if let Some(message) = &report.config.message {
        println!("Message: {message}");
    }
    println!(
        "Default provider: {}",
        report
            .config
            .default_provider
            .as_deref()
            .unwrap_or("<none>")
    );
    println!(
        "Codex sandbox: {}",
        report
            .config
            .codex_sandbox
            .as_deref()
            .unwrap_or("read-only")
    );
    println!(
        "Codex write scope: {}",
        report
            .config
            .codex_write_scope
            .as_deref()
            .unwrap_or("<default>")
    );
    println!("Run directory: {}", report.config.run_directory);
    println!();

    println!("## Target Tool");
    if let Some(readiness) = &report.target_tool {
        print_command_readiness(readiness);
    }
    println!();

    println!("## Guidance");
    for item in &report.guidance {
        println!("- {item}");
    }
}

fn run_agent_plugin_diagnose(target: AgentTarget, marketplace_path: Option<&Path>) -> Result<()> {
    let report = build_agent_plugin_report(target, marketplace_path)?;
    print_agent_plugin_report(&report);
    Ok(())
}

fn run_agent_plugin_install(
    target: AgentTarget,
    marketplace_path: Option<&Path>,
    skip_codex_add: bool,
) -> Result<()> {
    ensure_agent_plugin_supported(target)?;
    let paths = agent_plugin_paths(marketplace_path)?;
    write_codex_plugin_package(&paths, true)?;
    ensure_personal_marketplace_entry(&paths)?;
    if !skip_codex_add {
        run_codex_plugin_add("rms", "personal")?;
    }
    let report = build_agent_plugin_report(target, Some(&paths.marketplace_path))?;
    print_agent_plugin_report(&report);
    Ok(())
}

fn run_agent_plugin_sync(
    target: AgentTarget,
    marketplace_path: Option<&Path>,
    skip_codex_add: bool,
) -> Result<()> {
    ensure_agent_plugin_supported(target)?;
    let paths = agent_plugin_paths(marketplace_path)?;
    write_codex_plugin_package(&paths, true)?;
    ensure_personal_marketplace_entry(&paths)?;
    if !skip_codex_add {
        run_codex_plugin_add("rms", "personal")?;
    }
    let report = build_agent_plugin_report(target, Some(&paths.marketplace_path))?;
    print_agent_plugin_report(&report);
    Ok(())
}

fn ensure_agent_plugin_supported(target: AgentTarget) -> Result<()> {
    match target {
        AgentTarget::Codex => Ok(()),
        AgentTarget::Claude => bail!(
            "Claude plugin installation is not implemented; use `rms agent init --target claude --root .` for project-local scaffolding"
        ),
    }
}

struct AgentPluginPaths {
    marketplace_path: PathBuf,
    plugin_root: PathBuf,
}

fn agent_plugin_paths(marketplace_path: Option<&Path>) -> Result<AgentPluginPaths> {
    let marketplace_path = match marketplace_path {
        Some(path) => expand_tilde(path),
        None => home_dir()?.join(".agents/plugins/marketplace.json"),
    };
    let marketplace_root = marketplace_source_root(&marketplace_path);
    Ok(AgentPluginPaths {
        plugin_root: marketplace_root.join("plugins/rms"),
        marketplace_path,
    })
}

fn marketplace_source_root(marketplace_path: &Path) -> PathBuf {
    let components = marketplace_path
        .components()
        .map(|component| component.as_os_str().to_string_lossy().to_string())
        .collect::<Vec<_>>();
    if components.len() >= 3
        && components[components.len() - 1] == "marketplace.json"
        && components[components.len() - 2] == "plugins"
        && components[components.len() - 3] == ".agents"
    {
        return marketplace_path
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."));
    }
    marketplace_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."))
}

fn expand_tilde(path: &Path) -> PathBuf {
    let raw = path.to_string_lossy();
    if raw == "~" {
        home_dir().unwrap_or_else(|_| PathBuf::from(raw.as_ref()))
    } else if let Some(rest) = raw.strip_prefix("~/") {
        home_dir()
            .map(|home| home.join(rest))
            .unwrap_or_else(|_| PathBuf::from(raw.as_ref()))
    } else {
        path.to_path_buf()
    }
}

fn home_dir() -> Result<PathBuf> {
    std::env::var_os("HOME")
        .map(PathBuf::from)
        .ok_or_else(|| anyhow!("HOME is not set; pass --marketplace-path explicitly"))
}

fn write_codex_plugin_package(paths: &AgentPluginPaths, overwrite: bool) -> Result<()> {
    if paths.plugin_root.exists() && overwrite {
        fs::remove_dir_all(&paths.plugin_root)
            .with_context(|| format!("failed to remove `{}`", paths.plugin_root.display()))?;
    }
    fs::create_dir_all(paths.plugin_root.join(".codex-plugin"))?;
    fs::create_dir_all(paths.plugin_root.join("skills"))?;
    fs::write(
        paths.plugin_root.join(".codex-plugin/plugin.json"),
        render_codex_plugin_manifest(),
    )
    .with_context(|| {
        format!(
            "failed to write `{}`",
            paths
                .plugin_root
                .join(".codex-plugin/plugin.json")
                .display()
        )
    })?;
    fs::write(paths.plugin_root.join("README.md"), CODEX_PLUGIN_README).with_context(|| {
        format!(
            "failed to write `{}`",
            paths.plugin_root.join("README.md").display()
        )
    })?;
    for (relative_path, contents) in INIT_AGENT_SKILLS {
        write_agent_file(
            &paths.plugin_root.join("skills").join(relative_path),
            contents,
            true,
        )?;
    }
    validate_generated_codex_plugin(&paths.plugin_root)?;
    Ok(())
}

fn render_codex_plugin_manifest() -> String {
    let version = format!(
        "{}+codex.{}",
        env!("CARGO_PKG_VERSION")
            .split('+')
            .next()
            .unwrap_or(env!("CARGO_PKG_VERSION")),
        plugin_cachebuster()
    );
    serde_json::to_string_pretty(&json!({
        "name": "rms",
        "version": version,
        "description": "Codex adapter for Reliable Modular Systems skills and workflows.",
        "author": {
            "name": "Reliable Modular Systems",
            "url": "https://github.com/reliable-modular-systems/reliable-modular-systems"
        },
        "homepage": "https://github.com/reliable-modular-systems/reliable-modular-systems",
        "repository": "https://github.com/reliable-modular-systems/reliable-modular-systems",
        "license": "Apache-2.0",
        "keywords": ["architecture", "modularity", "agents", "validation", "reliability"],
        "skills": "./skills/",
        "interface": {
            "displayName": "Reliable Modular Systems",
            "shortDescription": "Build software through explicit module contracts.",
            "longDescription": "RMS gives Codex bounded workflows for inspecting modules, implementing changes, pruning semantic residue, evolving contracts, composing modules, and verifying conformance against canonical manifests.",
            "developerName": "Reliable Modular Systems",
            "category": "Developer Tools",
            "capabilities": ["Code", "Review", "Workflow"],
            "defaultPrompt": [
                "Inspect this RMS module before changing it.",
                "Implement this change within the owning module.",
                "Verify this module against its RMS contracts."
            ],
            "brandColor": "#2563EB"
        }
    }))
    .unwrap_or_else(|_| "{}".to_string())
        + "\n"
}

fn plugin_cachebuster() -> String {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs().to_string())
        .unwrap_or_else(|_| "0".to_string())
}

fn validate_generated_codex_plugin(plugin_root: &Path) -> Result<()> {
    let manifest_path = plugin_root.join(".codex-plugin/plugin.json");
    let manifest_source = fs::read_to_string(&manifest_path)
        .with_context(|| format!("failed to read `{}`", manifest_path.display()))?;
    let manifest: JsonValue = serde_json::from_str(&manifest_source)
        .with_context(|| format!("failed to parse `{}`", manifest_path.display()))?;
    for field in ["name", "version", "description", "skills", "interface"] {
        if manifest.get(field).is_none() {
            bail!("generated Codex plugin manifest missing `{field}`");
        }
    }
    if manifest.get("skills").and_then(JsonValue::as_str) != Some("./skills/") {
        bail!("generated Codex plugin manifest must use skills path `./skills/`");
    }
    for (relative_path, contents) in INIT_AGENT_SKILLS {
        let actual = fs::read_to_string(plugin_root.join("skills").join(relative_path))
            .with_context(|| format!("failed to read generated plugin skill `{relative_path}`"))?;
        if actual != *contents {
            bail!("generated plugin skill `{relative_path}` drifted from embedded RMS skill");
        }
    }
    Ok(())
}

fn ensure_personal_marketplace_entry(paths: &AgentPluginPaths) -> Result<()> {
    if let Some(parent) = paths.marketplace_path.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut marketplace = if paths.marketplace_path.exists() {
        let source = fs::read_to_string(&paths.marketplace_path)
            .with_context(|| format!("failed to read `{}`", paths.marketplace_path.display()))?;
        serde_json::from_str::<JsonValue>(&source)
            .with_context(|| format!("failed to parse `{}`", paths.marketplace_path.display()))?
    } else {
        json!({
            "name": "personal",
            "interface": { "displayName": "Personal" },
            "plugins": []
        })
    };

    if marketplace
        .get("name")
        .and_then(JsonValue::as_str)
        .is_none()
    {
        marketplace["name"] = JsonValue::String("personal".to_string());
    }
    if marketplace
        .get("interface")
        .and_then(JsonValue::as_object)
        .is_none()
    {
        marketplace["interface"] = json!({ "displayName": "Personal" });
    }
    if marketplace
        .get("plugins")
        .and_then(JsonValue::as_array)
        .is_none()
    {
        marketplace["plugins"] = JsonValue::Array(Vec::new());
    }
    let plugins = marketplace
        .get_mut("plugins")
        .and_then(JsonValue::as_array_mut)
        .ok_or_else(|| anyhow!("marketplace plugins must be an array"))?;
    let entry = json!({
        "name": "rms",
        "source": {
            "source": "local",
            "path": "./plugins/rms"
        },
        "policy": {
            "installation": "AVAILABLE",
            "authentication": "ON_INSTALL"
        },
        "category": "Developer Tools"
    });
    if let Some(existing) = plugins
        .iter_mut()
        .find(|plugin| plugin.get("name").and_then(JsonValue::as_str) == Some("rms"))
    {
        *existing = entry;
    } else {
        plugins.push(entry);
    }
    fs::write(
        &paths.marketplace_path,
        serde_json::to_string_pretty(&marketplace)? + "\n",
    )
    .with_context(|| format!("failed to write `{}`", paths.marketplace_path.display()))?;
    Ok(())
}

fn run_codex_plugin_add(plugin_name: &str, marketplace_name: &str) -> Result<()> {
    let status = Command::new("codex")
        .args([
            "plugin",
            "add",
            &format!("{plugin_name}@{marketplace_name}"),
        ])
        .status()
        .with_context(|| "failed to start `codex plugin add`")?;
    if !status.success() {
        bail!("`codex plugin add {plugin_name}@{marketplace_name}` failed");
    }
    Ok(())
}

fn build_agent_plugin_report(
    target: AgentTarget,
    marketplace_path: Option<&Path>,
) -> Result<AgentPluginReport> {
    let paths = agent_plugin_paths(marketplace_path)?;
    let marketplace_status = if marketplace_has_plugin(&paths.marketplace_path, "rms") {
        "present"
    } else if paths.marketplace_path.exists() {
        "missing-entry"
    } else {
        "missing"
    };
    let plugin_status = if validate_generated_codex_plugin(&paths.plugin_root).is_ok() {
        "present"
    } else if paths.plugin_root.exists() {
        "invalid"
    } else {
        "missing"
    };
    let installed_status = codex_plugin_installed_status("rms", "personal");
    let mut guidance = vec![
        "Project-local RMS guidance remains sufficient; plugin installation is optional.".to_string(),
        "Use `rms agent plugin install --target codex` to write the personal plugin and run `codex plugin add rms@personal`.".to_string(),
        "Use `rms agent plugin sync --target codex` after upgrading RMS so Codex sees refreshed skills.".to_string(),
        "Start a new Codex thread after plugin install or sync to load updated skills.".to_string(),
    ];
    if target != AgentTarget::Codex {
        guidance.push("Only Codex plugin packaging is currently implemented.".to_string());
    }
    Ok(AgentPluginReport {
        target: target.label().to_string(),
        plugin_required: false,
        marketplace_path: paths.marketplace_path.display().to_string(),
        marketplace_status: marketplace_status.to_string(),
        plugin_root: paths.plugin_root.display().to_string(),
        plugin_status: plugin_status.to_string(),
        installed_status,
        cache: codex_plugin_cache_readiness(),
        target_tool: target.target_tool(),
        guidance,
    })
}

fn codex_plugin_cache_readiness() -> CodexPluginCacheReadiness {
    let directory = match home_dir() {
        Ok(home) => home.join(".codex/plugins/cache/personal/rms"),
        Err(_) => PathBuf::from("<HOME-unavailable>"),
    };
    let mut matching_versions = Vec::new();
    let mut stale_versions = Vec::new();
    if !directory.is_dir() {
        return CodexPluginCacheReadiness {
            directory: directory.display().to_string(),
            status: "missing".to_string(),
            matching_versions,
            stale_versions,
        };
    }
    let Ok(entries) = fs::read_dir(&directory) else {
        return CodexPluginCacheReadiness {
            directory: directory.display().to_string(),
            status: "unreadable".to_string(),
            matching_versions,
            stale_versions,
        };
    };
    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let version = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("<unknown>")
            .to_string();
        if codex_plugin_cached_skills_match_embedded(&path) {
            matching_versions.push(version);
        } else {
            stale_versions.push(version);
        }
    }
    let status = match (matching_versions.is_empty(), stale_versions.is_empty()) {
        (true, true) => "missing",
        (false, true) => "present",
        (false, false) => "mixed",
        (true, false) => "stale",
    };
    CodexPluginCacheReadiness {
        directory: directory.display().to_string(),
        status: status.to_string(),
        matching_versions,
        stale_versions,
    }
}

fn codex_plugin_cached_skills_match_embedded(cache_version_root: &Path) -> bool {
    INIT_AGENT_SKILLS.iter().all(|(relative_path, contents)| {
        fs::read_to_string(cache_version_root.join("skills").join(relative_path))
            .is_ok_and(|actual| actual == *contents)
    })
}

fn marketplace_has_plugin(marketplace_path: &Path, name: &str) -> bool {
    let Ok(source) = fs::read_to_string(marketplace_path) else {
        return false;
    };
    let Ok(value) = serde_json::from_str::<JsonValue>(&source) else {
        return false;
    };
    value
        .get("plugins")
        .and_then(JsonValue::as_array)
        .map(|plugins| {
            plugins
                .iter()
                .any(|plugin| plugin.get("name").and_then(JsonValue::as_str) == Some(name))
        })
        .unwrap_or(false)
}

fn codex_plugin_installed_status(plugin_name: &str, marketplace_name: &str) -> String {
    let Ok(home) = home_dir() else {
        return "unknown".to_string();
    };
    let config_path = home.join(".codex/config.toml");
    let Ok(config) = load_toml(&config_path) else {
        return "unknown".to_string();
    };
    let key = format!("{plugin_name}@{marketplace_name}");
    let enabled = config
        .get("plugins")
        .and_then(TomlValue::as_table)
        .and_then(|plugins| plugins.get(&key))
        .and_then(TomlValue::as_table)
        .and_then(|plugin| plugin.get("enabled"))
        .and_then(TomlValue::as_bool);
    match enabled {
        Some(true) => "installed-enabled".to_string(),
        Some(false) => "installed-disabled".to_string(),
        None => "not-installed".to_string(),
    }
}

fn print_agent_plugin_report(report: &AgentPluginReport) {
    println!("# RMS Agent Plugin");
    println!();
    println!("Target: {}", report.target);
    println!("Plugin required: {}", report.plugin_required);
    println!();
    println!("## Codex Plugin");
    println!(
        "marketplace: {} ({})",
        report.marketplace_status, report.marketplace_path
    );
    println!(
        "plugin package: {} ({})",
        report.plugin_status, report.plugin_root
    );
    println!("installed: {}", report.installed_status);
    println!(
        "cache: {} ({})",
        report.cache.status, report.cache.directory
    );
    print_string_list("matching cache versions", &report.cache.matching_versions);
    print_string_list("stale cache versions", &report.cache.stale_versions);
    if report.cache.status == "stale" || report.cache.status == "mixed" {
        println!("Fix: run `rms agent plugin sync --target codex`, then start a new Codex thread.");
    }
    print_command_readiness(&report.target_tool);
    println!();
    println!("## Guidance");
    for item in &report.guidance {
        println!("- {item}");
    }
}

fn run_release_check(root: &Path, skip_cargo_package: bool) -> Result<()> {
    println!("# RMS Release Check");
    println!();
    println!("Root: {}", root.display());
    println!();

    let rms_exe = std::env::current_exe().with_context(|| "failed to locate current rms binary")?;

    run_release_metadata_check(root)?;
    run_release_step(
        "cargo fmt",
        command_with_args("cargo", &["fmt", "--all", "--check"], root),
    )?;
    run_release_step(
        "cargo test",
        command_with_args("cargo", &["test", "--workspace", "--locked"], root),
    )?;
    run_release_step(
        "rms validate",
        command_with_args(
            &rms_exe,
            &["validate", "--root", root.to_string_lossy().as_ref()],
            root,
        ),
    )?;
    run_release_step(
        "rms verify rms-cli",
        command_with_args(
            &rms_exe,
            &["verify", "tooling/rust/rms/implementation.yaml"],
            root,
        ),
    )?;
    run_release_step(
        "rms compose examples/minimal",
        command_with_args(&rms_exe, &["compose", "--root", "examples/minimal"], root),
    )?;
    run_release_step(
        "rms compose examples/rust",
        command_with_args(&rms_exe, &["compose", "--root", "examples/rust"], root),
    )?;
    run_release_step(
        "rms compose examples/swift",
        command_with_args(&rms_exe, &["compose", "--root", "examples/swift"], root),
    )?;
    run_release_step(
        "rms compose examples/tic-tac-toe",
        command_with_args(
            &rms_exe,
            &["compose", "--root", "examples/tic-tac-toe"],
            root,
        ),
    )?;
    run_release_step(
        "rms check-compat smoke",
        command_with_args(
            &rms_exe,
            &[
                "check-compat",
                "examples/rust/module.yaml",
                "examples/rust/module.yaml",
            ],
            root,
        ),
    )?;
    run_release_package_smoke(root, &rms_exe)?;
    run_release_scaffold_roundtrip(root, &rms_exe)?;
    run_release_step(
        "example Rust binding tests",
        command_with_args(
            "cargo",
            &[
                "test",
                "--manifest-path",
                "examples/rust/Cargo.toml",
                "--locked",
            ],
            root,
        ),
    )?;
    run_release_binary_smoke(root)?;
    if !skip_cargo_package {
        run_release_step(
            "cargo package",
            command_with_args(
                "cargo",
                &[
                    "package",
                    "--manifest-path",
                    "tooling/rust/rms/Cargo.toml",
                    "--allow-dirty",
                    "--no-verify",
                ],
                root,
            ),
        )?;
    }
    run_release_plugin_check(root, &rms_exe)?;

    println!();
    println!("pass: release check");
    Ok(())
}

fn run_release_metadata_check(root: &Path) -> Result<()> {
    println!("## release metadata");
    validate_release_metadata(root)?;
    println!("pass");
    println!();
    Ok(())
}

fn run_release_scaffold_roundtrip(root: &Path, rms_exe: &Path) -> Result<()> {
    let temp = std::env::temp_dir().join(format!(
        "rms-release-scaffold-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or(0)
    ));
    fs::create_dir_all(&temp).with_context(|| format!("failed to create `{}`", temp.display()))?;
    let app = temp.join("app");
    let app_arg = app.to_string_lossy().to_string();
    let widget = app.join("modules/widget");
    let widget_arg = widget.to_string_lossy().to_string();
    let swift_widget = app.join("modules/swift-widget");
    let swift_widget_arg = swift_widget.to_string_lossy().to_string();
    let widget_manifest = widget.join("Cargo.toml");
    let widget_manifest_arg = widget_manifest.to_string_lossy().to_string();
    let executable_widget = app.join("modules/executable-widget");
    let executable_widget_arg = executable_widget.to_string_lossy().to_string();
    let executable_implementation = executable_widget.join("implementation.yaml");
    let executable_implementation_arg = executable_implementation.to_string_lossy().to_string();

    let result = (|| -> Result<()> {
        run_release_step(
            "rms init scaffold",
            command_with_args(
                rms_exe,
                &[
                    "init",
                    app_arg.as_str(),
                    "--name",
                    "app",
                    "--purpose",
                    "Try RMS",
                    "--context",
                    "core",
                ],
                root,
            ),
        )?;
        run_release_step(
            "rms add-module rust scaffold",
            command_with_args(
                rms_exe,
                &[
                    "add-module",
                    widget_arg.as_str(),
                    "--name",
                    "widget",
                    "--purpose",
                    "Own widgets",
                    "--kind",
                    "library",
                    "--binding",
                    "rust",
                ],
                root,
            ),
        )?;
        run_release_step(
            "rms add-module swift scaffold",
            command_with_args(
                rms_exe,
                &[
                    "add-module",
                    swift_widget_arg.as_str(),
                    "--name",
                    "swift-widget",
                    "--purpose",
                    "Own Swift widgets",
                    "--kind",
                    "library",
                    "--binding",
                    "swift",
                ],
                root,
            ),
        )?;
        run_release_step(
            "rms add-module executable scaffold",
            command_with_args(
                rms_exe,
                &[
                    "add-module",
                    executable_widget_arg.as_str(),
                    "--name",
                    "executable-widget",
                    "--purpose",
                    "Own executable widgets",
                    "--kind",
                    "adapter",
                    "--profile",
                    "boundary",
                    "--binding",
                    "executable",
                ],
                root,
            ),
        )?;
        run_release_step(
            "rms validate scaffold",
            command_with_args(rms_exe, &["validate", "--root", app_arg.as_str()], root),
        )?;
        run_release_step(
            "rms compose scaffold",
            command_with_args(rms_exe, &["compose", "--root", app_arg.as_str()], root),
        )?;
        run_release_step(
            "cargo generate-lockfile scaffold",
            command_with_args(
                "cargo",
                &[
                    "generate-lockfile",
                    "--manifest-path",
                    widget_manifest_arg.as_str(),
                ],
                root,
            ),
        )?;
        run_release_step(
            "cargo test scaffold rust binding",
            command_with_args(
                "cargo",
                &[
                    "test",
                    "--manifest-path",
                    widget_manifest_arg.as_str(),
                    "--locked",
                ],
                root,
            ),
        )?;
        run_release_step(
            "rms verify scaffold executable binding",
            command_with_args(
                rms_exe,
                &["verify", executable_implementation_arg.as_str()],
                root,
            ),
        )?;
        Ok(())
    })();

    let _ = fs::remove_dir_all(&temp);
    result
}

fn run_release_package_smoke(root: &Path, rms_exe: &Path) -> Result<()> {
    let temp = std::env::temp_dir().join(format!(
        "rms-release-package-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or(0)
    ));
    fs::create_dir_all(&temp).with_context(|| format!("failed to create `{}`", temp.display()))?;
    let output = temp.join("rust-example.rms");
    let output_arg = output.to_string_lossy().to_string();
    let result = run_release_step(
        "rms package smoke",
        command_with_args(
            rms_exe,
            &[
                "package",
                "examples/rust/module.yaml",
                "--output",
                output_arg.as_str(),
            ],
            root,
        ),
    )
    .and_then(|()| {
        for required in ["PACKAGE.json", "conformance-report.json"] {
            let path = output.join(required);
            if !path.exists() {
                bail!("package smoke missing `{}`", path.display());
            }
        }
        Ok(())
    })
    .and_then(|()| {
        run_release_step(
            "rms verify-package smoke",
            command_with_args(rms_exe, &["verify-package", output_arg.as_str()], root),
        )
    });
    let _ = fs::remove_dir_all(&temp);
    result
}

fn run_release_plugin_check(root: &Path, rms_exe: &Path) -> Result<()> {
    println!("## codex plugin wrapper");
    validate_codex_plugin_sync(root)?;
    validate_embedded_skill_assets(root)?;
    run_release_agent_distribution_smoke(rms_exe)?;
    println!("pass");
    println!();
    Ok(())
}

fn run_release_binary_smoke(root: &Path) -> Result<()> {
    run_release_step(
        "release binary build",
        command_with_args(
            "cargo",
            &["build", "--release", "-p", "rms", "--locked"],
            root,
        ),
    )?;

    let binary = release_binary_path(root);
    if !binary.exists() {
        bail!("release binary smoke missing `{}`", binary.display());
    }

    run_release_step(
        "release binary diagnose",
        command_with_args(&binary, &["diagnose", "--root", ".", "--json"], root),
    )?;
    run_release_step(
        "release binary validate minimal",
        command_with_args(&binary, &["validate", "--root", "examples/minimal"], root),
    )?;
    run_release_install_smoke(root, &binary)?;
    run_release_clean_room_dogfood(root, &binary)?;
    Ok(())
}

fn release_binary_path(root: &Path) -> PathBuf {
    root.join("target")
        .join("release")
        .join(format!("rms{}", std::env::consts::EXE_SUFFIX))
}

fn run_release_install_smoke(root: &Path, binary: &Path) -> Result<()> {
    let temp = std::env::temp_dir().join(format!(
        "rms-release-install-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or(0)
    ));
    let bin_dir = temp.join("bin");
    fs::create_dir_all(&bin_dir)
        .with_context(|| format!("failed to create `{}`", bin_dir.display()))?;
    let installed_binary = bin_dir.join(format!("rms{}", std::env::consts::EXE_SUFFIX));
    fs::copy(binary, &installed_binary).with_context(|| {
        format!(
            "failed to copy `{}` to `{}`",
            binary.display(),
            installed_binary.display()
        )
    })?;
    make_executable(&installed_binary)?;

    let result = (|| -> Result<()> {
        run_release_step(
            "clean-room installed binary diagnose",
            command_with_path(
                "rms",
                &["diagnose", "--root", ".", "--json"],
                root,
                &bin_dir,
            )?,
        )?;
        run_release_step(
            "clean-room installed binary validate minimal",
            command_with_path(
                "rms",
                &["validate", "--root", "examples/minimal"],
                root,
                &bin_dir,
            )?,
        )?;
        Ok(())
    })();

    let _ = fs::remove_dir_all(&temp);
    result
}

fn run_release_clean_room_dogfood(root: &Path, binary: &Path) -> Result<()> {
    let temp = std::env::temp_dir().join(format!(
        "rms-release-dogfood-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or(0)
    ));
    let bin_dir = temp.join("bin");
    let work_dir = temp.join("work");
    fs::create_dir_all(&bin_dir)
        .with_context(|| format!("failed to create `{}`", bin_dir.display()))?;
    fs::create_dir_all(&work_dir)
        .with_context(|| format!("failed to create `{}`", work_dir.display()))?;
    let installed_binary = bin_dir.join(format!("rms{}", std::env::consts::EXE_SUFFIX));
    fs::copy(binary, &installed_binary).with_context(|| {
        format!(
            "failed to copy `{}` to `{}`",
            binary.display(),
            installed_binary.display()
        )
    })?;
    make_executable(&installed_binary)?;

    let app = work_dir.join("tic-tac-toe");
    let app_arg = app.to_string_lossy().to_string();
    let capability = app.join("modules/play-tic-tac-toe");
    let capability_arg = capability.to_string_lossy().to_string();
    let parent_module = "modules/play-tic-tac-toe/module.yaml";
    let rules_module = "modules/play-tic-tac-toe-domain/module.yaml";
    let verify_parent = app.join(parent_module);
    let verify_parent_arg = verify_parent.to_string_lossy().to_string();

    let result = (|| -> Result<()> {
        run_release_step(
            "clean-room dogfood init",
            command_with_path(
                "rms",
                &[
                    "init",
                    app_arg.as_str(),
                    "--name",
                    "dogfood-tic-tac-toe",
                    "--purpose",
                    "Clean-room RMS dogfood for recursive semantic scaffolding",
                    "--context",
                    "game",
                ],
                root,
                &bin_dir,
            )?,
        )?;
        run_release_step(
            "clean-room dogfood codex guidance",
            command_with_path(
                "rms",
                &[
                    "agent",
                    "init",
                    "--root",
                    app_arg.as_str(),
                    "--target",
                    "codex",
                    "--force",
                ],
                root,
                &bin_dir,
            )?,
        )?;
        run_release_step(
            "clean-room dogfood claude guidance",
            command_with_path(
                "rms",
                &[
                    "agent",
                    "init",
                    "--root",
                    app_arg.as_str(),
                    "--target",
                    "claude",
                    "--force",
                ],
                root,
                &bin_dir,
            )?,
        )?;
        run_release_step(
            "clean-room dogfood design",
            command_with_path(
                "rms",
                &[
                    "design",
                    "--root",
                    app_arg.as_str(),
                    "--task",
                    "browser-playable Tic Tac Toe game",
                ],
                root,
                &bin_dir,
            )?,
        )?;
        run_release_step(
            "clean-room dogfood add-capability",
            command_with_path(
                "rms",
                &[
                    "add-capability",
                    capability_arg.as_str(),
                    "--name",
                    "play-tic-tac-toe",
                    "--purpose",
                    "Expose a playable Tic Tac Toe capability",
                    "--public-command",
                    "play-tic-tac-toe",
                    "--domain-command",
                    "apply-move",
                    "--domain-binding",
                    "rust",
                    "--boundary-binding",
                    "js",
                ],
                root,
                &bin_dir,
            )?,
        )?;
        assert_clean_room_dogfood_artifacts(&app)?;
        run_release_step(
            "clean-room dogfood validate",
            command_with_path("rms", &["validate", "--root", "."], &app, &bin_dir)?,
        )?;
        run_release_step(
            "clean-room dogfood compose",
            command_with_path("rms", &["compose", "--root", "."], &app, &bin_dir)?,
        )?;
        let rules_route = run_release_step_capture(
            "clean-room dogfood route rules",
            command_with_path(
                "rms",
                &[
                    "route",
                    parent_module,
                    "--root",
                    ".",
                    "--task",
                    "change win detection and invalid move rules",
                ],
                &app,
                &bin_dir,
            )?,
        )?;
        ensure_output_contains(
            "clean-room dogfood route rules",
            &rules_route,
            "Recommended module: play-tic-tac-toe-domain",
        )?;
        let boundary_route = run_release_step_capture(
            "clean-room dogfood route boundary",
            command_with_path(
                "rms",
                &[
                    "route",
                    parent_module,
                    "--root",
                    ".",
                    "--task",
                    "change CLI input parsing and malformed move errors",
                ],
                &app,
                &bin_dir,
            )?,
        )?;
        ensure_output_contains(
            "clean-room dogfood route boundary",
            &boundary_route,
            "Recommended module: play-tic-tac-toe-boundary",
        )?;
        run_release_step(
            "clean-room dogfood context",
            command_with_path(
                "rms",
                &[
                    "context",
                    rules_module,
                    "--root",
                    ".",
                    "--task",
                    "change win detection and invalid move rules",
                ],
                &app,
                &bin_dir,
            )?,
        )?;
        run_release_step(
            "clean-room dogfood verify",
            command_with_path(
                "rms",
                &["verify", verify_parent_arg.as_str()],
                root,
                &bin_dir,
            )?,
        )?;
        run_release_step(
            "clean-room dogfood git init",
            command_with_path("git", &["init"], &app, &bin_dir)?,
        )?;
        run_release_step(
            "clean-room dogfood gate",
            command_with_path("rms", &["gate", "--root", "."], &app, &bin_dir)?,
        )?;
        Ok(())
    })();

    let _ = fs::remove_dir_all(&temp);
    result
}

fn command_with_path(
    program: &str,
    args: &[&str],
    root: &Path,
    first_path: &Path,
) -> Result<Command> {
    let mut paths = vec![first_path.to_path_buf()];
    if let Some(existing) = std::env::var_os("PATH") {
        paths.extend(std::env::split_paths(&existing));
    }
    let path_value = std::env::join_paths(paths).with_context(|| "failed to build PATH")?;
    let mut command = command_with_args(program, args, root);
    command.env("PATH", path_value);
    Ok(command)
}

#[cfg(unix)]
fn make_executable(path: &Path) -> Result<()> {
    use std::os::unix::fs::PermissionsExt;

    let mut permissions = fs::metadata(path)
        .with_context(|| format!("failed to read metadata for `{}`", path.display()))?
        .permissions();
    permissions.set_mode(0o755);
    fs::set_permissions(path, permissions).with_context(|| {
        format!(
            "failed to set executable permissions on `{}`",
            path.display()
        )
    })
}

#[cfg(not(unix))]
fn make_executable(_path: &Path) -> Result<()> {
    Ok(())
}

fn validate_release_metadata(root: &Path) -> Result<()> {
    let cargo_path = root.join("tooling/rust/rms/Cargo.toml");
    let cargo = load_toml(&cargo_path)?;
    let cargo_package = cargo
        .get("package")
        .and_then(TomlValue::as_table)
        .ok_or_else(|| anyhow!("`{}` missing [package]", cargo_path.display()))?;
    let cargo_name = cargo_package
        .get("name")
        .and_then(TomlValue::as_str)
        .ok_or_else(|| anyhow!("`{}` missing package.name", cargo_path.display()))?;
    let cargo_version = cargo_package
        .get("version")
        .and_then(TomlValue::as_str)
        .ok_or_else(|| anyhow!("`{}` missing package.version", cargo_path.display()))?;
    if cargo_name != "rms" {
        bail!("release metadata expected Cargo package name `rms`, found `{cargo_name}`");
    }

    let module_path = root.join("tooling/rust/rms/module.yaml");
    let module = load_manifest(&module_path)?;
    let module_version = get_str(&module.value, &["module", "version"])
        .ok_or_else(|| anyhow!("`{}` missing module.version", module_path.display()))?;
    if module_version != cargo_version {
        bail!(
            "release metadata version drift: Cargo package is `{cargo_version}` but rms-cli module is `{module_version}`"
        );
    }

    let plugin_path = root
        .join(CODEX_PLUGIN_PATH)
        .join(".codex-plugin/plugin.json");
    let plugin_source = fs::read_to_string(&plugin_path)
        .with_context(|| format!("failed to read `{}`", plugin_path.display()))?;
    let plugin: JsonValue = serde_json::from_str(&plugin_source)
        .with_context(|| format!("failed to parse `{}`", plugin_path.display()))?;
    let plugin_version = plugin
        .get("version")
        .and_then(JsonValue::as_str)
        .ok_or_else(|| anyhow!("`{}` missing version", plugin_path.display()))?;
    if plugin_version != cargo_version {
        bail!(
            "release metadata version drift: Cargo package is `{cargo_version}` but Codex plugin is `{plugin_version}`"
        );
    }

    Ok(())
}

fn command_with_args(program: impl AsRef<Path>, args: &[&str], root: &Path) -> Command {
    let mut command = Command::new(program.as_ref());
    command.args(args).current_dir(root);
    command
}

fn run_release_step(label: &str, mut command: Command) -> Result<()> {
    println!("## {label}");
    let status = command
        .status()
        .with_context(|| format!("failed to start release check step `{label}`"))?;
    if !status.success() {
        bail!(
            "release check step `{label}` failed with status {}",
            status
                .code()
                .map(|code| code.to_string())
                .unwrap_or_else(|| "signal".to_string())
        );
    }
    println!("pass");
    println!();
    Ok(())
}

fn run_release_step_capture(label: &str, mut command: Command) -> Result<String> {
    println!("## {label}");
    let output = command
        .output()
        .with_context(|| format!("failed to start release check step `{label}`"))?;
    if !output.status.success() {
        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);
        bail!(
            "release check step `{label}` failed with status {}\nstdout:\n{}\nstderr:\n{}",
            output
                .status
                .code()
                .map(|code| code.to_string())
                .unwrap_or_else(|| "signal".to_string()),
            stdout,
            stderr,
        );
    }
    println!("pass");
    println!();
    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
}

fn ensure_output_contains(label: &str, output: &str, needle: &str) -> Result<()> {
    if !output.contains(needle) {
        bail!("release check step `{label}` output did not contain `{needle}`");
    }
    Ok(())
}

