struct ValidateRequest {
    root: PathBuf,
    module: Vec<PathBuf>,
    system: Vec<PathBuf>,
    context_map: Vec<PathBuf>,
    contract: Vec<PathBuf>,
    implementation: Vec<PathBuf>,
    conformance: Vec<PathBuf>,
    json: bool,
}

fn run_validate(request: ValidateRequest) -> Result<()> {
    let diagnostics = collect_validation_diagnostics(
        &request.root,
        request.module,
        request.system,
        request.context_map,
        request.contract,
        request.implementation,
        request.conformance,
    )?;

    if request.json {
        println!("{}", serde_json::to_string_pretty(&diagnostics)?);
    } else if diagnostics.is_empty() {
        println!("pass: no RMS validation diagnostics");
    } else {
        for diagnostic in &diagnostics {
            println!(
                "{} [{}] {}: {}",
                severity_label(diagnostic.severity),
                diagnostic.check,
                diagnostic.path,
                diagnostic.message
            );
        }
    }

    if diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Error)
    {
        bail!("RMS validation failed");
    }

    Ok(())
}

fn collect_validation_diagnostics(
    root: &Path,
    modules: Vec<PathBuf>,
    systems: Vec<PathBuf>,
    context_maps: Vec<PathBuf>,
    contracts: Vec<PathBuf>,
    implementations: Vec<PathBuf>,
    conformance_reports: Vec<PathBuf>,
) -> Result<Vec<Diagnostic>> {
    let targets = discover_targets(
        root,
        modules,
        systems,
        context_maps,
        contracts,
        implementations,
        conformance_reports,
    )?;
    let mut diagnostics = Vec::new();

    for path in targets {
        match load_manifest(&path) {
            Ok(manifest) => validate_loaded_manifest(&manifest, &mut diagnostics),
            Err(error) => diagnostics.push(Diagnostic {
                severity: Severity::Error,
                check: "manifest.parse".to_string(),
                path: path.display().to_string(),
                message: error.to_string(),
            }),
        }
    }

    Ok(diagnostics)
}

fn run_diagnose(root: &Path, json_output: bool) -> Result<()> {
    let report = build_diagnose_report(root)?;
    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
        return Ok(());
    }
    print_diagnose_report(&report);
    Ok(())
}

fn build_diagnose_report(root: &Path) -> Result<DiagnoseReport> {
    let targets = discover_targets(
        root,
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
    )?;
    let mut counts: BTreeMap<String, usize> = BTreeMap::new();
    for target in &targets {
        let spec = load_manifest(target)
            .ok()
            .and_then(|manifest| get_str(&manifest.value, &["spec"]).map(str::to_string))
            .unwrap_or_else(|| "<unreadable>".to_string());
        *counts.entry(spec).or_default() += 1;
    }

    let diagnostics = collect_validation_diagnostics(
        root,
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
    )?;
    let errors = diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.severity == Severity::Error)
        .count();
    let warnings = diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.severity == Severity::Warning)
        .count();

    let config = diagnose_config(root);
    let run_records = diagnose_run_records(root, &config.run_directory);

    let source_revision = source_revision(root);
    let mut guidance = vec![
        "Use `rms explain <module>` before asking broad questions about a module.".to_string(),
        "Use `rms config init` when you want checked-in or local workbench provider defaults.".to_string(),
        "Use `rms explain --ai` or `--provider codex` only when provider execution is intended.".to_string(),
        "Use `rms implement`, `rms evolve-contract`, and `rms evidence` for bounded agent guidance.".to_string(),
        "Use `rms context <module> --task ...` before implementation work.".to_string(),
        format!("Use `rms validate --root {}` before completion.", root.display()),
        format!(
            "Use `rms gate --root {}` to run git-impact-selected RMS checks.",
            root.display()
        ),
        format!(
            "Use `rms audit --root {}` and `--strict` before claiming production-ready RMS software.",
            root.display()
        ),
        "Use `rms spec plan|apply|check <module.yaml|implementation.yaml>` when product meaning needs new laws, contracts, states, transitions, runnable surfaces, effects, or evidence obligations.".to_string(),
        "Use `rms machine plan|apply|check <implementation.yaml>` only for focused inner-machine edits after laws, contracts, and evidence obligations are already correct.".to_string(),
        "Use `rms surface apply|check <implementation.yaml>` when app, UI, CLI, browser, HTTP, batch, mobile, desktop, or executable entrypoints are added or changed.".to_string(),
        "Use `rms structure <implementation.yaml>` to inspect declared machine, role, and evidence structure.".to_string(),
        "Use `rms trace check|replay|diagnose <trace-bundle>` to inspect local transition evidence without a runtime.".to_string(),
        "Use `rms verify <implementation.yaml>` when an implementation binding declares verification, or `rms verify <composite-module.yaml>` for composite rollups.".to_string(),
    ];
    if source_revision.is_none() {
        guidance.push(
            "Strict audit cannot pass until the project has a git source revision; run `git init` if needed, then `git add . && git commit -m \"Initial RMS project\"` before the production audit.".to_string(),
        );
    }

    Ok(DiagnoseReport {
        validator: VALIDATOR_NAME,
        version: VALIDATOR_VERSION,
        root: root.display().to_string(),
        repository: vec![
            file_readiness("system.yaml", &root.join("system.yaml")),
            file_readiness("context-map.yaml", &root.join("context-map.yaml")),
            file_readiness("AGENTS.md", &root.join("AGENTS.md")),
            file_readiness(WORKBENCH_CONFIG_PATH, &root.join(WORKBENCH_CONFIG_PATH)),
            ReadinessItem {
                name: "git source revision".to_string(),
                path: root.display().to_string(),
                status: source_revision.unwrap_or_else(|| "missing".to_string()),
            },
        ],
        config,
        codex_plugin_cache: codex_plugin_cache_readiness(),
        manifest_counts: counts,
        validation: ValidationReadiness {
            status: if diagnostics.is_empty() {
                "pass".to_string()
            } else {
                "review-required".to_string()
            },
            errors,
            warnings,
            diagnostics,
        },
        native_tools: vec![
            command_readiness("git", &["--version"]),
            command_readiness("cargo", &["--version"]),
            command_readiness("swift", &["--version"]),
        ],
        ai_providers: vec![
            command_readiness("codex", &["--version"]),
            command_readiness("claude", &["--version"]),
        ],
        run_records,
        guidance,
    })
}

fn print_diagnose_report(report: &DiagnoseReport) {
    println!("# RMS Diagnose");
    println!();
    println!("RMS CLI: {} {}", report.validator, report.version);
    println!("Root: {}", report.root);
    println!();

    println!("## Repository");
    for item in &report.repository {
        println!("{}: {}", item.name, item.status);
    }
    let total_manifests: usize = report.manifest_counts.values().sum();
    println!(
        "RMS manifests: {}",
        if total_manifests == 0 {
            "<none>".to_string()
        } else {
            total_manifests.to_string()
        }
    );
    for (spec, count) in &report.manifest_counts {
        println!("- {spec}: {count}");
    }
    println!();

    println!("## Config");
    println!("{}: {}", report.config.path, report.config.status);
    if let Some(message) = &report.config.message {
        println!("Message: {message}");
    }
    println!(
        "Default provider: {}",
        report
            .config
            .default_provider
            .as_deref()
            .unwrap_or("<none>")
    );
    println!(
        "Codex model: {}",
        report
            .config
            .codex_model
            .as_deref()
            .unwrap_or("<provider-default>")
    );
    println!(
        "Codex sandbox: {}",
        report
            .config
            .codex_sandbox
            .as_deref()
            .unwrap_or("read-only")
    );
    println!(
        "Codex write scope: {}",
        report
            .config
            .codex_write_scope
            .as_deref()
            .unwrap_or("<default>")
    );
    println!(
        "Codex timeout seconds: {}",
        report
            .config
            .codex_timeout_seconds
            .map(|value| value.to_string())
            .unwrap_or_else(|| DEFAULT_PROVIDER_TIMEOUT_SECONDS.to_string())
    );
    println!("Run directory: {}", report.config.run_directory);
    println!();

    println!("## Codex Plugin Cache");
    println!(
        "{}: {}",
        report.codex_plugin_cache.directory, report.codex_plugin_cache.status
    );
    print_string_list(
        "matching versions",
        &report.codex_plugin_cache.matching_versions,
    );
    print_string_list("stale versions", &report.codex_plugin_cache.stale_versions);
    if report.codex_plugin_cache.status == "stale" || report.codex_plugin_cache.status == "mixed" {
        println!("Fix: run `rms agent plugin sync --target codex`, then start a new Codex thread.");
    }
    println!();

    println!("## Validation");
    println!("Status: {}", report.validation.status);
    if !report.validation.diagnostics.is_empty() {
        println!("Errors: {}", report.validation.errors);
        println!("Warnings: {}", report.validation.warnings);
        for diagnostic in report.validation.diagnostics.iter().take(12) {
            println!(
                "- {} [{}] {}: {}",
                severity_label(diagnostic.severity),
                diagnostic.check,
                diagnostic.path,
                diagnostic.message
            );
        }
        if report.validation.diagnostics.len() > 12 {
            println!(
                "- ... {} more diagnostics",
                report.validation.diagnostics.len() - 12
            );
        }
    }
    println!();

    println!("## Native Tools");
    for command in &report.native_tools {
        print_command_readiness(command);
    }
    println!();

    println!("## AI Providers");
    for command in &report.ai_providers {
        print_command_readiness(command);
    }
    println!();

    println!("## Run Records");
    println!(
        "{}: {}",
        report.run_records.directory, report.run_records.status
    );
    if let Some(message) = &report.run_records.message {
        println!("Message: {message}");
    }
    println!();

    println!("## Agent Guidance");
    for item in &report.guidance {
        println!("- {item}");
    }
}

fn file_readiness(label: &str, path: &Path) -> ReadinessItem {
    ReadinessItem {
        name: label.to_string(),
        path: path.display().to_string(),
        status: if path.exists() {
            "present".to_string()
        } else {
            "missing".to_string()
        },
    }
}

fn diagnose_config(root: &Path) -> ConfigReadiness {
    let path = root.join(WORKBENCH_CONFIG_PATH);
    match load_workbench_config(root) {
        Ok(Some(loaded)) => {
            let default_provider = match loaded.value.ai.default_provider.as_deref() {
                Some(value) => match parse_config_provider(value, "ai.default_provider") {
                    Ok(provider) => Some(provider.label().to_string()),
                    Err(error) => {
                        return ConfigReadiness {
                            path: loaded.path.display().to_string(),
                            status: "invalid".to_string(),
                            default_provider: Some(value.to_string()),
                            codex_model: loaded.value.ai.codex.model,
                            codex_sandbox: loaded.value.ai.codex.sandbox,
                            codex_write_scope: loaded.value.ai.codex.write_scope,
                            codex_timeout_seconds: loaded.value.ai.codex.timeout_seconds,
                            run_directory: loaded
                                .value
                                .runs
                                .directory
                                .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT))
                                .display()
                                .to_string(),
                            message: Some(error.to_string()),
                        };
                    }
                },
                None => None,
            };
            if let Some(value) = loaded.value.ai.codex.sandbox.as_deref() {
                if let Err(error) = parse_config_sandbox(value, "ai.codex.sandbox") {
                    return ConfigReadiness {
                        path: loaded.path.display().to_string(),
                        status: "invalid".to_string(),
                        default_provider,
                        codex_model: loaded.value.ai.codex.model,
                        codex_sandbox: Some(value.to_string()),
                        codex_write_scope: loaded.value.ai.codex.write_scope,
                        codex_timeout_seconds: loaded.value.ai.codex.timeout_seconds,
                        run_directory: loaded
                            .value
                            .runs
                            .directory
                            .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT))
                            .display()
                            .to_string(),
                        message: Some(error.to_string()),
                    };
                }
            }
            if let Some(value) = loaded.value.ai.codex.write_scope.as_deref() {
                if let Err(error) = parse_config_write_scope(value, "ai.codex.write_scope") {
                    return ConfigReadiness {
                        path: loaded.path.display().to_string(),
                        status: "invalid".to_string(),
                        default_provider,
                        codex_model: loaded.value.ai.codex.model,
                        codex_sandbox: loaded.value.ai.codex.sandbox,
                        codex_write_scope: Some(value.to_string()),
                        codex_timeout_seconds: loaded.value.ai.codex.timeout_seconds,
                        run_directory: loaded
                            .value
                            .runs
                            .directory
                            .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT))
                            .display()
                            .to_string(),
                        message: Some(error.to_string()),
                    };
                }
            }
            if let Some(value) = loaded.value.ai.codex.timeout_seconds {
                if let Err(error) = parse_config_timeout_seconds(value, "ai.codex.timeout_seconds")
                {
                    return ConfigReadiness {
                        path: loaded.path.display().to_string(),
                        status: "invalid".to_string(),
                        default_provider,
                        codex_model: loaded.value.ai.codex.model,
                        codex_sandbox: loaded.value.ai.codex.sandbox,
                        codex_write_scope: loaded.value.ai.codex.write_scope,
                        codex_timeout_seconds: Some(value),
                        run_directory: loaded
                            .value
                            .runs
                            .directory
                            .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT))
                            .display()
                            .to_string(),
                        message: Some(error.to_string()),
                    };
                }
            }
            ConfigReadiness {
                path: loaded.path.display().to_string(),
                status: "present".to_string(),
                default_provider,
                codex_model: loaded.value.ai.codex.model,
                codex_sandbox: loaded.value.ai.codex.sandbox,
                codex_write_scope: loaded.value.ai.codex.write_scope,
                codex_timeout_seconds: loaded.value.ai.codex.timeout_seconds,
                run_directory: loaded
                    .value
                    .runs
                    .directory
                    .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT))
                    .display()
                    .to_string(),
                message: None,
            }
        }
        Ok(None) => ConfigReadiness {
            path: path.display().to_string(),
            status: "missing".to_string(),
            default_provider: None,
            codex_model: None,
            codex_sandbox: None,
            codex_write_scope: None,
            codex_timeout_seconds: None,
            run_directory: DEFAULT_RUN_ROOT.to_string(),
            message: Some("optional config is not present".to_string()),
        },
        Err(error) => ConfigReadiness {
            path: path.display().to_string(),
            status: "invalid".to_string(),
            default_provider: None,
            codex_model: None,
            codex_sandbox: None,
            codex_write_scope: None,
            codex_timeout_seconds: None,
            run_directory: DEFAULT_RUN_ROOT.to_string(),
            message: Some(error.to_string()),
        },
    }
}

fn diagnose_run_records(root: &Path, configured_run_directory: &str) -> RunRecordReadiness {
    let directory = root.join(configured_run_directory);
    if directory.is_dir() {
        return RunRecordReadiness {
            directory: directory.display().to_string(),
            status: "present".to_string(),
            message: None,
        };
    }
    if directory.exists() {
        return RunRecordReadiness {
            directory: directory.display().to_string(),
            status: "not-directory".to_string(),
            message: Some("configured run record path exists but is not a directory".to_string()),
        };
    }
    let parent = directory.parent().unwrap_or(root);
    RunRecordReadiness {
        directory: directory.display().to_string(),
        status: if parent.exists() {
            "missing-will-be-created".to_string()
        } else {
            "parent-missing".to_string()
        },
        message: Some("run records are created when `--record` or a provider is used".to_string()),
    }
}

fn run_explain(
    subject: &[String],
    explicit_module: Option<&Path>,
    root: &Path,
    options: &PromptRunOptions,
) -> Result<()> {
    let (module, question) = resolve_explain_subject(subject, explicit_module, root)?;
    if options.provider == Provider::None && !options.record {
        let manifest = load_manifest(&module)?;
        return print_module_explanation(&manifest, root, question.as_deref());
    }

    run_prompt(
        PromptKind::Explain,
        &module,
        root,
        question.as_deref(),
        None,
        false,
        options,
    )
}

fn resolve_explain_subject(
    subject: &[String],
    explicit_module: Option<&Path>,
    root: &Path,
) -> Result<(PathBuf, Option<String>)> {
    if let Some(module) = explicit_module {
        return Ok((module.to_path_buf(), join_question(subject)));
    }

    if let Some(first) = subject.first() {
        let candidate = Path::new(first);
        if candidate.exists() && is_module_yaml_manifest(candidate) {
            return Ok((candidate.to_path_buf(), join_question(&subject[1..])));
        }
    }

    let module = infer_single_module(root)?;
    Ok((module, join_question(subject)))
}

fn join_question(parts: &[String]) -> Option<String> {
    if parts.is_empty() {
        None
    } else {
        Some(parts.join(" "))
    }
}

fn infer_single_module(root: &Path) -> Result<PathBuf> {
    let direct = root.join("module.yaml");
    if direct.exists() && is_module_yaml_manifest(&direct) {
        return Ok(direct);
    }

    let mut modules = Vec::new();
    for entry in WalkDir::new(root)
        .max_depth(3)
        .follow_links(false)
        .into_iter()
        .filter_map(Result::ok)
        .filter(|entry| entry.file_type().is_file())
    {
        let path = entry.path();
        let Some(file_name) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        if (file_name == "module.yaml" || file_name.ends_with(".module.yaml"))
            && is_module_yaml_manifest(path)
        {
            modules.push(path.to_path_buf());
        }
    }

    match modules.len() {
        0 => bail!(
            "could not infer module from `{}`; pass `--module <module.yaml>` or run from a module directory",
            root.display()
        ),
        1 => Ok(modules.remove(0)),
        _ => bail!(
            "found multiple modules under `{}`; pass `--module <module.yaml>`",
            root.display()
        ),
    }
}

fn is_module_yaml_manifest(path: &Path) -> bool {
    if path.extension().and_then(|ext| ext.to_str()) != Some("yaml") {
        return false;
    }
    let Ok(source) = fs::read_to_string(path) else {
        return false;
    };
    source
        .lines()
        .take(5)
        .any(|line| line.trim() == "spec: rms/module/v0.1")
}

fn run_prompt(
    kind: PromptKind,
    module: &Path,
    root: &Path,
    task: Option<&str>,
    diff: Option<&str>,
    impact: bool,
    options: &PromptRunOptions,
) -> Result<()> {
    let manifest = load_manifest(module)?;
    let mut rendered = render_workbench_prompt(&manifest, root, kind, task, diff, impact)?;
    if options.provider != Provider::None {
        rendered.push_str(&render_provider_execution_scope(&manifest, root, options));
    }

    let run_dir = if options.record || options.provider != Provider::None {
        Some(write_prompt_run_record(
            &manifest, root, kind, task, diff, impact, &rendered, options,
        )?)
    } else {
        None
    };

    match options.provider {
        Provider::None => {
            println!("{rendered}");
            if let Some(run_dir) = run_dir {
                eprintln!("run record: {}", run_dir.display());
            }
        }
        Provider::Codex => {
            let run_dir =
                run_dir.ok_or_else(|| anyhow!("provider execution requires run record"))?;
            execute_codex_provider(root, &manifest, &rendered, &run_dir, options)?;
            println!("run record: {}", run_dir.display());
            println!("response: {}", run_dir.join("response.md").display());
        }
    }

    Ok(())
}

fn run_design(root: &Path, task: &str, options: &PromptRunOptions) -> Result<()> {
    let manifest = synthetic_workbench_manifest(root, "rms-design", "system design advisory");
    let mut rendered = render_design_prompt(root, task)?;
    if options.provider != Provider::None {
        rendered.push_str(&render_provider_execution_scope(&manifest, root, options));
    }

    let run_dir = if options.record || options.provider != Provider::None {
        Some(write_prompt_run_record(
            &manifest,
            root,
            PromptKind::Design,
            Some(task),
            None,
            false,
            &rendered,
            options,
        )?)
    } else {
        None
    };

    match options.provider {
        Provider::None => {
            println!("{rendered}");
            if let Some(run_dir) = run_dir {
                eprintln!("run record: {}", run_dir.display());
            }
        }
        Provider::Codex => {
            let run_dir =
                run_dir.ok_or_else(|| anyhow!("provider execution requires run record"))?;
            execute_codex_provider(root, &manifest, &rendered, &run_dir, options)?;
            println!("run record: {}", run_dir.display());
            println!("response: {}", run_dir.join("response.md").display());
        }
    }

    Ok(())
}

fn render_design_prompt(root: &Path, task: &str) -> Result<String> {
    let modules = discover_module_manifests(root)?;
    let mut out = String::new();
    writeln!(out, "# RMS Workbench Prompt")?;
    writeln!(out)?;
    writeln!(out, "Prompt: {}", PromptKind::Design.prompt_id())?;
    writeln!(
        out,
        "Mode: advisory; no edits are performed by this command"
    )?;
    writeln!(out, "Root: {}", root.display())?;
    writeln!(out, "Task: {task}")?;
    writeln!(out)?;
    writeln!(out, "## Operating Rule")?;
    writeln!(out, "Use RMS canonical artifacts as the source of architectural truth. Use design output as advisory evidence until reflected in system, context, module, contract, implementation, and verification artifacts.")?;
    writeln!(out, "Product intent is enough input from the user: ask clarifying questions only when needed, surface semantic edge cases, name what must never happen, and propose laws, contracts, machines, effects, rejections, and evidence before code.")?;
    writeln!(out, "For external truth, decide what happens when outcomes are unknown, duplicate, stale, partial, conflicting, delayed, or later corrected; use reconciliation or recovery evidence when those cases matter.")?;
    writeln!(out)?;
    append_design_context(&mut out, root, &modules)?;
    append_design_recommendations(&mut out, task, &modules)?;
    writeln!(out)?;
    append_semantic_structure_checklist(&mut out, PromptKind::Design)?;
    writeln!(out, "## Workflow")?;
    for item in PromptKind::Design.workflow() {
        writeln!(out, "- {item}")?;
    }
    writeln!(out)?;
    writeln!(out, "## Expected Output")?;
    for item in PromptKind::Design.expected_output() {
        writeln!(out, "- {item}")?;
    }
    writeln!(out)?;
    writeln!(out, "## Deterministic Checks")?;
    for item in PromptKind::Design.deterministic_checks() {
        writeln!(out, "- {item}")?;
    }
    Ok(out)
}

fn append_design_context(out: &mut String, root: &Path, modules: &[LoadedManifest]) -> Result<()> {
    writeln!(out, "## Repository Context")?;
    for file_name in ["system.yaml", "context-map.yaml", "GLOSSARY.md"] {
        let path = root.join(file_name);
        if path.exists() {
            writeln!(out, "- {}", path.display())?;
        }
    }
    if modules.is_empty() {
        writeln!(out, "- Modules: <none discovered>")?;
    } else {
        writeln!(out, "- Modules:")?;
        for module in modules {
            let name = get_str(&module.value, &["module", "name"]).unwrap_or("<unknown>");
            let kind = get_str(&module.value, &["module", "kind"]).unwrap_or("<missing>");
            let purpose = get_str(&module.value, &["module", "purpose"]).unwrap_or("<missing>");
            let profiles = get_string_array(&module.value, &["profiles"]).join(", ");
            writeln!(
                out,
                "  - {} [{}] profiles={} path={} purpose={}",
                name,
                kind,
                if profiles.is_empty() {
                    "<none>"
                } else {
                    &profiles
                },
                module.path.display(),
                purpose
            )?;
            for advisory in shape_advisories(module) {
                writeln!(out, "    - advisory: {advisory}")?;
            }
        }
    }
    Ok(())
}

fn append_design_recommendations(
    out: &mut String,
    task: &str,
    modules: &[LoadedManifest],
) -> Result<()> {
    writeln!(out)?;
    writeln!(out, "## Deterministic Design Hints")?;
    let lower = task.to_lowercase();
    let boundary_terms = [
        "browser",
        "web",
        "ui",
        "cli",
        "command-line",
        "input",
        "output",
        "network",
        "storage",
        "external",
        "integration",
        "file",
        "time",
        "random",
    ];
    let decision_terms = [
        "rule",
        "rules",
        "engine",
        "decision",
        "transition",
        "state",
        "invariant",
        "workflow",
        "game",
        "resolver",
        "validation",
    ];
    let monitor_terms = [
        "monitor",
        "runtime",
        "observe",
        "observed",
        "derived",
        "stream",
        "trigger",
        "alarm",
        "envelope",
        "supervisory",
        "guard",
        "fallback",
    ];
    let mentions_boundary = boundary_terms.iter().any(|term| lower.contains(term));
    let mentions_decision = decision_terms.iter().any(|term| lower.contains(term));
    let mentions_monitor = monitor_terms.iter().any(|term| lower.contains(term));
    let mentions_runnable_surface = [
        "browser",
        "web",
        "ui",
        "app",
        "tool",
        "cli",
        "command-line",
        "command line",
        "mobile",
        "desktop",
        "http",
        "batch",
        "executable",
        "local-first reference app",
        "local-first",
        "runnable",
        "status",
        "write local file",
        "write local",
        "smoke",
    ]
    .iter()
    .any(|term| lower.contains(term));
    if mentions_boundary && mentions_decision {
        writeln!(out, "- Candidate split: invariant-bearing decisions in a `domain-engine` plus untrusted input/output and effects in a `boundary-adapter`.")?;
        writeln!(out)?;
        writeln!(out, "### Recommended Module Tree")?;
        writeln!(
            out,
            "- `<capability>` [composite]: public product/capability surface; exports child-backed commands, queries, events, or capabilities."
        )?;
        writeln!(
            out,
            "  - `<semantic-domain-child>` [domain-engine, internal]: pure invariant-bearing decisions, closed variants, validated values, accepted/rejected transition records, laws, and replay bundles."
        )?;
        writeln!(
            out,
            "  - `<semantic-boundary-child>` [boundary-adapter, internal]: untrusted input/output, UI/CLI/web/process/network/storage/time/randomness effects, parsers, ports, and boundary evidence."
        )?;
        writeln!(
            out,
            "  - Name children in product/domain language; `rules`, `engine`, `adapter`, `cli`, `web`, and similar role words are implementation hints, not canonical semantics."
        )?;
        writeln!(
            out,
            "  - When scaffolding with `rms add-capability`, omit `--domain-child` and `--boundary-child` unless the user supplied semantic child names; the defaults use neutral `-domain` and `-boundary` paths."
        )?;
        writeln!(
            out,
            "  - Do not name inner machines from role or surface words such as `RulesMachine`, `AdapterMachine`, `CliMachine`, or `WebMachine`; prefer capability language such as `<Capability>Machine` or `<Capability>BoundaryMachine`."
        )?;
        writeln!(
            out,
            "- Add more adapter children only when there are distinct external surfaces; keep the parent export explicit rather than inferred from children."
        )?;
        writeln!(out)?;
        writeln!(out, "- Keep rendering, input, storage, timers, time, randomness, process, network, and external-service effects outside the pure transition module.")?;
    }
    if mentions_runnable_surface {
        writeln!(out, "- Because the intent names an app/tool/runnable surface, include a boundary adapter with a declared runnable surface via `rms surface apply` or `rms spec apply`, plus smoke evidence; do not leave the result as library-only unless the user explicitly requested a library.")?;
        writeln!(out, "- Preferred scaffold for a runnable product app is a composite capability with at least one boundary child and one domain/workflow child. A single-module app is acceptable only when `module.yaml` or `implementation.yaml` records the semantic single-module justification.")?;
    }
    writeln!(out, "- Choose `domain-engine` when the module owns pure decisions, invariants, transitions, or traceable rules.")?;
    writeln!(out, "- Choose `boundary-adapter` when untrusted input, UI, CLI, network, storage, time, randomness, or external effects enter or leave.")?;
    writeln!(out, "- Choose `runtime-monitor` when the module observes runtime inputs over time, computes derived facts or streams, and emits findings, alarms, events, or declared supervisory commands.")?;
    if mentions_monitor {
        writeln!(out, "- Monitor authority must be explicit: observe-only, advisory, enforcing, or fail-safe. Supervisory outputs must cross public contracts and must not mutate controlled module state directly.")?;
    }
    if modules
        .iter()
        .any(|module| !shape_advisories(module).is_empty())
    {
        writeln!(out, "- Existing modules show shape or boundary pressure; align scaffold shape, module kind, profiles, and pure/effectful responsibilities before implementation.")?;
    }
    writeln!(out, "- Representation belongs in an explicit role/unit: closed variants, validated values, commands, states, events, and accepted/rejected result types.")?;
    writeln!(out, "- Transition behavior should be replayable from command traces and suitable for law/property/fuzz evidence where risk justifies it.")?;
    Ok(())
}

fn discover_module_manifests(root: &Path) -> Result<Vec<LoadedManifest>> {
    let mut modules = Vec::new();
    for path in discover_targets(
        root,
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
    )? {
        let manifest = load_manifest(&path)?;
        if get_str(&manifest.value, &["spec"]) == Some("rms/module/v0.1") {
            modules.push(manifest);
        }
    }
    Ok(modules)
}

fn shape_advisories(manifest: &LoadedManifest) -> Vec<String> {
    let profiles = get_string_array(&manifest.value, &["profiles"]);
    let decisions = get_string_array(&manifest.value, &["owns", "decisions"]);
    let concepts = get_string_array(&manifest.value, &["owns", "concepts"]);
    let effects = get_path(&manifest.value, &["effects"])
        .and_then(YamlValue::as_sequence)
        .map(Vec::len)
        .unwrap_or(0);
    let kind = get_str(&manifest.value, &["module", "kind"]).unwrap_or("");
    let has_boundary = profiles.iter().any(|profile| profile == "boundary") || kind == "adapter";
    let has_domain_decisions = decisions.iter().chain(concepts.iter()).any(|decision| {
        is_domain_rule_decision(decision) && !is_boundary_adapter_decision(decision)
    });
    let has_effects = effects > 0;
    let mut advisories = shape_consistency_advisories(manifest);
    if has_boundary && has_domain_decisions && has_effects {
        advisories.push("module mixes boundary effects with owned domain decisions; consider a domain-engine plus boundary-adapter split".to_string());
    }
    let lifecycle_words = [
        "state",
        "status",
        "transition",
        "lifecycle",
        "step",
        "phase",
    ];
    let owns_lifecycle = concepts.iter().chain(decisions.iter()).any(|term| {
        lifecycle_words
            .iter()
            .any(|word| term.to_lowercase().contains(word))
    });
    if owns_lifecycle && get_path(&manifest.value, &["state"]).is_none() {
        advisories.push("owned lifecycle/order terms are present without a state or transition model; consider explicit accepted/rejected transitions".to_string());
    }
    advisories
}

fn shape_consistency_advisories(manifest: &LoadedManifest) -> Vec<String> {
    let profiles = get_string_array(&manifest.value, &["profiles"]);
    let effects = get_path(&manifest.value, &["effects"])
        .and_then(YamlValue::as_sequence)
        .map(Vec::len)
        .unwrap_or(0);
    let kind = get_str(&manifest.value, &["module", "kind"]).unwrap_or("");
    let scaffold_shape = get_str(&manifest.value, &["x-scaffold", "shape"]).unwrap_or("");
    let has_boundary_profile = profiles.iter().any(|profile| profile == "boundary");
    let has_monitor_profile = profiles.iter().any(|profile| profile == "monitor");
    let mut advisories = Vec::new();
    if scaffold_shape == "boundary-adapter" && kind != "adapter" {
        advisories.push(
            "boundary-adapter scaffold is not declared as module.kind `adapter`; align kind with semantic responsibility or explain the exception".to_string(),
        );
    }
    if scaffold_shape == "boundary-adapter" && !has_boundary_profile {
        advisories.push(
            "boundary-adapter scaffold lacks the `boundary` profile; declare boundary obligations for untrusted input/output and effects".to_string(),
        );
    }
    if scaffold_shape == "domain-engine" && effects > 0 {
        advisories.push(
            "domain-engine scaffold declares effects; keep pure decisions separate from adapters unless the manifest intentionally owns an effectful boundary".to_string(),
        );
    }
    if scaffold_shape == "runtime-monitor" && !has_monitor_profile {
        advisories.push(
            "runtime-monitor scaffold lacks the `monitor` profile; declare runtime observation, trigger, authority, and failure-mode obligations".to_string(),
        );
    }
    if has_monitor_profile && get_path(&manifest.value, &["monitor"]).is_none() {
        advisories.push(
            "monitor profile is declared without a `monitor` section for inputs, derived facts, triggers, authority, and failure mode".to_string(),
        );
    }
    advisories
}

fn is_boundary_adapter_decision(decision: &str) -> bool {
    let lower = decision.to_lowercase();
    let adapter_terms = [
        "adapt",
        "adapter",
        "authentication",
        "authorization",
        "boundary",
        "cli",
        "decode",
        "delegate",
        "delegation",
        "deserialize",
        "dom",
        "effect",
        "encode",
        "format",
        "formatting",
        "http",
        "input",
        "io",
        "map",
        "malformed",
        "normalize",
        "output",
        "parse",
        "parser",
        "port",
        "render",
        "request",
        "response",
        "route",
        "routing",
        "schema",
        "serialize",
        "transport",
        "ui",
        "validate",
        "validation",
    ];
    adapter_terms.iter().any(|term| lower.contains(term))
}

fn is_domain_rule_decision(decision: &str) -> bool {
    let lower = decision.to_lowercase();
    if lower.contains("delegate") || lower.contains("delegation") {
        return false;
    }
    let domain_terms = [
        "collision",
        "draw",
        "game over",
        "invariant",
        "law",
        "legal move",
        "lifecycle",
        "order",
        "outcome",
        "rule",
        "score",
        "state",
        "status",
        "terminal",
        "transition",
        "turn",
        "win",
    ];
    domain_terms.iter().any(|term| lower.contains(term))
}

fn synthetic_workbench_manifest(root: &Path, name: &str, purpose: &str) -> LoadedManifest {
    LoadedManifest {
        path: root.join(format!("{}.workbench.yaml", sanitize_run_segment(name))),
        value: serde_yaml::from_str(&render_module_yaml(
            name,
            purpose,
            "workbench",
            &[String::from("core")],
            None,
        ))
        .unwrap_or(YamlValue::Null),
    }
}

fn write_prompt_run_record(
    manifest: &LoadedManifest,
    root: &Path,
    kind: PromptKind,
    task: Option<&str>,
    diff: Option<&str>,
    impact: bool,
    prompt: &str,
    options: &PromptRunOptions,
) -> Result<PathBuf> {
    let run_id = run_id(kind, manifest);
    let run_dir = root.join(&options.run_root).join(&run_id);
    fs::create_dir_all(&run_dir)
        .with_context(|| format!("failed to create run record `{}`", run_dir.display()))?;

    fs::write(run_dir.join("prompt.md"), prompt)
        .with_context(|| format!("failed to write `{}`", run_dir.join("prompt.md").display()))?;

    let request =
        render_run_request_yaml(manifest, root, kind, task, diff, impact, options, &run_id);
    fs::write(run_dir.join("request.yaml"), request).with_context(|| {
        format!(
            "failed to write `{}`",
            run_dir.join("request.yaml").display()
        )
    })?;

    let diagnostics = collect_validation_diagnostics(
        root,
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
    )?;
    let checks = json!({
        "validator": VALIDATOR_NAME,
        "validator_version": VALIDATOR_VERSION,
        "validation": diagnostics,
    });
    fs::write(
        run_dir.join("checks.json"),
        serde_json::to_string_pretty(&checks)?,
    )
    .with_context(|| {
        format!(
            "failed to write `{}`",
            run_dir.join("checks.json").display()
        )
    })?;

    Ok(run_dir)
}

fn execute_codex_provider(
    root: &Path,
    manifest: &LoadedManifest,
    prompt: &str,
    run_dir: &Path,
    options: &PromptRunOptions,
) -> Result<()> {
    let response_path = run_dir.join("response.md");
    let provider_response_path = provider_response_path(run_dir)?;
    let stdout_path = run_dir.join("provider.stdout.log");
    let stderr_path = run_dir.join("provider.stderr.log");
    let execution_root = provider_execution_root(root, manifest, options);
    let timeout = Duration::from_secs(options.provider_timeout_seconds);

    let mut command = Command::new("codex");
    command
        .arg("exec")
        .arg("--cd")
        .arg(&execution_root)
        .arg("--sandbox")
        .arg(options.sandbox.as_str())
        .arg("--output-last-message")
        .arg(&provider_response_path);

    if let Some(model) = &options.model {
        command.arg("--model").arg(model);
    }
    command.arg("-");

    let mut child = command
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .with_context(|| "failed to start `codex exec` provider")?;

    let stdout = child
        .stdout
        .take()
        .ok_or_else(|| anyhow!("failed to capture `codex exec` stdout"))?;
    let stderr = child
        .stderr
        .take()
        .ok_or_else(|| anyhow!("failed to capture `codex exec` stderr"))?;
    let stdout_reader = spawn_pipe_reader(stdout);
    let stderr_reader = spawn_pipe_reader(stderr);

    if let Some(mut stdin) = child.stdin.take() {
        stdin
            .write_all(prompt.as_bytes())
            .with_context(|| "failed to write prompt to `codex exec` stdin")?;
    }

    let outcome = wait_child_with_timeout(&mut child, timeout)
        .with_context(|| "failed to wait for `codex exec` provider")?;
    let stdout = join_pipe_reader(stdout_reader, "stdout")?;
    let stderr = join_pipe_reader(stderr_reader, "stderr")?;

    fs::write(&stdout_path, &stdout)
        .with_context(|| format!("failed to write `{}`", stdout_path.display()))?;
    fs::write(&stderr_path, &stderr)
        .with_context(|| format!("failed to write `{}`", stderr_path.display()))?;

    match outcome {
        ProviderProcessOutcome::Exited(status) if !status.success() => {
            bail!(
                "`codex exec` failed with status {}; see `{}` and `{}`",
                exit_status_label(status),
                stdout_path.display(),
                stderr_path.display()
            );
        }
        ProviderProcessOutcome::TimedOut { status } => {
            bail!(
                "`codex exec` timed out after {} second(s) and was terminated with status {}; see `{}` and `{}`{}",
                options.provider_timeout_seconds,
                exit_status_label(status),
                stdout_path.display(),
                stderr_path.display(),
                if response_path.exists() {
                    "; partial response was preserved"
                } else {
                    ""
                }
            );
        }
        ProviderProcessOutcome::Exited(_) => {}
    }

    if !response_path.exists() {
        fs::write(&response_path, String::from_utf8_lossy(&stdout).as_ref())
            .with_context(|| format!("failed to write `{}`", response_path.display()))?;
    }

    Ok(())
}

enum ProviderProcessOutcome {
    Exited(ExitStatus),
    TimedOut { status: ExitStatus },
}

fn wait_child_with_timeout(child: &mut Child, timeout: Duration) -> Result<ProviderProcessOutcome> {
    let started = Instant::now();
    loop {
        if let Some(status) = child.try_wait()? {
            return Ok(ProviderProcessOutcome::Exited(status));
        }
        if started.elapsed() >= timeout {
            if let Err(error) = child.kill() {
                if let Some(status) = child.try_wait()? {
                    return Ok(ProviderProcessOutcome::Exited(status));
                }
                return Err(error)
                    .with_context(|| "failed to terminate timed-out provider process");
            }
            let status = child
                .wait()
                .with_context(|| "failed to collect timed-out provider process")?;
            return Ok(ProviderProcessOutcome::TimedOut { status });
        }
        thread::sleep(Duration::from_millis(100));
    }
}

fn spawn_pipe_reader<R>(mut reader: R) -> thread::JoinHandle<Result<Vec<u8>>>
where
    R: IoRead + Send + 'static,
{
    thread::spawn(move || {
        let mut bytes = Vec::new();
        reader.read_to_end(&mut bytes)?;
        Ok(bytes)
    })
}

fn join_pipe_reader(handle: thread::JoinHandle<Result<Vec<u8>>>, label: &str) -> Result<Vec<u8>> {
    handle
        .join()
        .map_err(|_| anyhow!("provider {label} reader panicked"))?
}

fn render_provider_execution_scope(
    manifest: &LoadedManifest,
    root: &Path,
    options: &PromptRunOptions,
) -> String {
    let execution_root = provider_execution_root(root, manifest, options);
    let module_root = module_execution_root(root, manifest);
    let mut out = String::new();
    out.push_str("\n## Provider Execution Scope\n");
    let _ = writeln!(out, "- Provider: {}", options.provider.label());
    let _ = writeln!(out, "- Sandbox: {}", options.sandbox.as_str());
    let _ = writeln!(out, "- Write scope: {}", options.write_scope.as_str());
    let _ = writeln!(
        out,
        "- Timeout: {} second(s)",
        options.provider_timeout_seconds
    );
    let _ = writeln!(out, "- Execution root: {}", execution_root.display());
    match (options.sandbox, options.write_scope) {
        (CodexSandbox::ReadOnly, _) => {
            out.push_str("- Filesystem writes are not permitted in this provider run.\n");
        }
        (CodexSandbox::WorkspaceWrite, ProviderWriteScope::Module) => {
            let _ = writeln!(
                out,
                "- Edit only files under the owning module directory `{}`. If the task requires changing system, context, glossary, or another module, stop and report the required scope expansion.",
                module_root.display()
            );
        }
        (CodexSandbox::WorkspaceWrite, ProviderWriteScope::Root) => {
            out.push_str("- Repository-root writes are permitted. Still preserve RMS module ownership and update canonical artifacts before implementation when public meaning changes.\n");
        }
    }
    out
}

fn provider_execution_root(
    root: &Path,
    manifest: &LoadedManifest,
    options: &PromptRunOptions,
) -> PathBuf {
    if matches!(
        (options.sandbox, options.write_scope),
        (CodexSandbox::WorkspaceWrite, ProviderWriteScope::Module)
    ) {
        module_execution_root(root, manifest)
    } else {
        root.to_path_buf()
    }
}

fn module_execution_root(root: &Path, manifest: &LoadedManifest) -> PathBuf {
    let module_dir = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    if module_dir.is_absolute() {
        module_dir.to_path_buf()
    } else {
        root.join(module_dir)
    }
}

fn provider_response_path(run_dir: &Path) -> Result<PathBuf> {
    absolute_path(&run_dir.join("response.md"))
}

fn absolute_path(path: &Path) -> Result<PathBuf> {
    if path.is_absolute() {
        Ok(path.to_path_buf())
    } else {
        Ok(std::env::current_dir()
            .with_context(|| "failed to resolve current directory")?
            .join(path))
    }
}

fn run_list_runs(root: &Path, run_root: &Path) -> Result<()> {
    let directory = root.join(run_root);
    println!("# RMS Run Records");
    println!();
    println!("Path: {}", directory.display());
    println!();

    if !directory.exists() {
        println!("<no run records>");
        return Ok(());
    }

    let runs = collect_run_dirs(&directory)?;

    if runs.is_empty() {
        println!("<no run records>");
        return Ok(());
    }

    for run in runs {
        print_run_list_item(&run)?;
    }

    Ok(())
}

fn run_inspect_run(run: &Path, root: &Path, run_root: &Path) -> Result<()> {
    let run_dir = resolve_run_dir(run, root, run_root);
    if !run_dir.exists() {
        bail!("run record does not exist: `{}`", run_dir.display());
    }

    print_run_record(&run_dir)
}

fn run_latest_run(root: &Path, run_root: &Path) -> Result<()> {
    let directory = root.join(run_root);
    let Some(run_dir) = latest_run_dir(&directory)? else {
        bail!("no run records found in `{}`", directory.display());
    };
    print_run_record(&run_dir)
}

fn run_trace_check(bundle: &Path, json_output: bool) -> Result<()> {
    let report = build_trace_report(bundle)?;
    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_trace_check_report(&report);
    }
    if trace_has_errors(&report) {
        bail!("RMS trace check failed");
    }
    Ok(())
}

fn run_trace_replay(bundle: &Path, json_output: bool) -> Result<()> {
    let report = build_trace_report(bundle)?;
    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_trace_replay_report(&report);
    }
    if trace_has_errors(&report) {
        bail!("RMS trace replay failed");
    }
    Ok(())
}

fn run_trace_diagnose(bundle: &Path, json_output: bool) -> Result<()> {
    let report = build_trace_report(bundle)?;
    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_trace_diagnose_report(&report);
    }
    Ok(())
}

fn build_trace_report(bundle: &Path) -> Result<TraceReport> {
    let value = load_trace_bundle(bundle)?;
    let mut diagnostics = Vec::new();
    let spec = get_str(&value, &["spec"]).map(ToString::to_string);
    if spec.as_deref() != Some("rms/trace-bundle/v0.1") {
        push_trace_diagnostic(
            &mut diagnostics,
            Severity::Warning,
            "trace.spec-missing",
            bundle,
            None,
            "trace bundle should declare `spec: rms/trace-bundle/v0.1`",
        );
    }

    let machine = get_str(&value, &["machine"])
        .or_else(|| get_str(&value, &["target_machine"]))
        .or_else(|| get_str(&value, &["source_machine"]))
        .map(ToString::to_string);

    let mut records = Vec::new();
    let Some((record_key, record_values)) = trace_record_values(&value) else {
        push_trace_diagnostic(
            &mut diagnostics,
            Severity::Error,
            "trace.records-missing",
            bundle,
            None,
            "trace bundle should contain a `records`, `transitions`, or `journal` array",
        );
        return Ok(trace_report(
            bundle,
            spec,
            machine,
            records,
            diagnostics,
            None,
        ));
    };

    if record_values.is_empty() {
        push_trace_diagnostic(
            &mut diagnostics,
            Severity::Warning,
            "trace.records-empty",
            bundle,
            None,
            format!("trace `{record_key}` array is empty"),
        );
    }

    let mut previous_after: Option<&YamlValue> = None;
    for (index, record) in record_values.iter().enumerate() {
        inspect_trace_record(bundle, index, record, previous_after, &mut diagnostics);
        records.push(trace_record_summary(index, record));
        previous_after = trace_record_state_after(record);
    }
    let declared_first_bad =
        declared_first_bad_trace_transition(bundle, &value, &records, &mut diagnostics);

    Ok(trace_report(
        bundle,
        spec,
        machine,
        records,
        diagnostics,
        declared_first_bad,
    ))
}

fn trace_report(
    bundle: &Path,
    spec: Option<String>,
    machine: Option<String>,
    records: Vec<TraceRecordSummary>,
    diagnostics: Vec<TraceDiagnostic>,
    declared_first_bad: Option<TraceFirstBadTransition>,
) -> TraceReport {
    let first_bad_transition =
        first_bad_trace_transition(&diagnostics, &records).or(declared_first_bad);
    TraceReport {
        result: trace_result(&diagnostics).to_string(),
        bundle: bundle.display().to_string(),
        spec,
        machine,
        records,
        first_bad_transition,
        diagnostics,
    }
}

fn declared_first_bad_trace_transition(
    bundle: &Path,
    value: &YamlValue,
    records: &[TraceRecordSummary],
    diagnostics: &mut Vec<TraceDiagnostic>,
) -> Option<TraceFirstBadTransition> {
    let Some(declared) = get_path(value, &["first_bad_transition"]) else {
        return None;
    };
    let Some(index) = get_path(declared, &["index"]).and_then(yaml_usize) else {
        push_trace_diagnostic(
            diagnostics,
            Severity::Error,
            "trace.first-bad-transition-invalid",
            bundle,
            None,
            "`first_bad_transition.index` should be a zero-based record index",
        );
        return None;
    };
    let Some(record) = records.iter().find(|record| record.index == index) else {
        push_trace_diagnostic(
            diagnostics,
            Severity::Error,
            "trace.first-bad-transition-out-of-range",
            bundle,
            None,
            "`first_bad_transition.index` does not refer to a transition record",
        );
        return None;
    };

    Some(TraceFirstBadTransition {
        index,
        reason: "declared by trace bundle metadata".to_string(),
        source: record.source.clone(),
    })
}

fn load_trace_bundle(path: &Path) -> Result<YamlValue> {
    let source = fs::read_to_string(path)
        .with_context(|| format!("failed to read trace bundle `{}`", path.display()))?;
    serde_yaml::from_str(&source)
        .with_context(|| format!("failed to parse trace bundle `{}`", path.display()))
}

fn trace_record_values(value: &YamlValue) -> Option<(&'static str, &[YamlValue])> {
    for key in ["records", "transitions", "journal"] {
        if let Some(records) = get_path(value, &[key]).and_then(YamlValue::as_sequence) {
            return Some((key, records));
        }
    }
    None
}

fn inspect_trace_record(
    bundle: &Path,
    index: usize,
    record: &YamlValue,
    previous_after: Option<&YamlValue>,
    diagnostics: &mut Vec<TraceDiagnostic>,
) {
    if record.as_mapping().is_none() {
        push_trace_diagnostic(
            diagnostics,
            Severity::Error,
            "trace.record-not-object",
            bundle,
            Some(index),
            "transition record should be a mapping/object",
        );
        return;
    }

    let input = trace_record_input(record);
    if input.is_none() {
        push_trace_diagnostic(
            diagnostics,
            Severity::Warning,
            "trace.input-missing",
            bundle,
            Some(index),
            "transition record should include an input command/event/effect result",
        );
    }
    if let Some(input) = input {
        validate_trace_envelope(
            bundle,
            index,
            "trace.command-envelope-incomplete",
            "command",
            input,
            &[
                "command_id",
                "target_machine",
                "correlation_id",
                "causation_id",
            ],
            diagnostics,
        );
    }

    let Some(output) = get_path(record, &["output"]) else {
        push_trace_diagnostic(
            diagnostics,
            Severity::Error,
            "trace.output-missing",
            bundle,
            Some(index),
            "transition record should include an `output` object",
        );
        inspect_explicit_trace_diagnostics(bundle, index, record, diagnostics);
        return;
    };
    if output.as_mapping().is_none() {
        push_trace_diagnostic(
            diagnostics,
            Severity::Error,
            "trace.output-not-object",
            bundle,
            Some(index),
            "`output` should be a mapping/object",
        );
    }

    for field in ["next_state", "events", "commands", "effects", "reply"] {
        if yaml_mapping_get(output, field).is_none() {
            push_trace_diagnostic(
                diagnostics,
                Severity::Warning,
                format!("trace.output-{field}-missing"),
                bundle,
                Some(index),
                format!("transition output should include `{field}`"),
            );
        }
    }

    let state_before = trace_record_state_before(record);
    if state_before.is_none() {
        push_trace_diagnostic(
            diagnostics,
            Severity::Warning,
            "trace.state-before-missing",
            bundle,
            Some(index),
            "transition record should include `state_before`",
        );
    }

    let state_after = trace_record_state_after(record);
    let output_next = get_path(record, &["output", "next_state"]);
    if state_after.is_none() {
        push_trace_diagnostic(
            diagnostics,
            Severity::Warning,
            "trace.state-after-missing",
            bundle,
            Some(index),
            "transition record should include `state_after` or `output.next_state`",
        );
    }
    if let (Some(state_after), Some(output_next)) =
        (yaml_mapping_get(record, "state_after"), output_next)
    {
        if state_after != output_next {
            push_trace_diagnostic(
                diagnostics,
                Severity::Error,
                "trace.state-after-mismatch",
                bundle,
                Some(index),
                "record `state_after` does not match `output.next_state`",
            );
        }
    }
    if let (Some(previous_after), Some(state_before)) = (previous_after, state_before) {
        if previous_after != state_before {
            push_trace_diagnostic(
                diagnostics,
                Severity::Error,
                "trace.timeline-discontinuity",
                bundle,
                Some(index),
                "record `state_before` does not match the previous record's resulting state",
            );
        }
    }

    validate_trace_output_envelopes(bundle, index, output, diagnostics);
    inspect_trace_scaffold_reply(bundle, index, output, diagnostics);
    inspect_explicit_trace_diagnostics(bundle, index, record, diagnostics);
}

fn inspect_trace_scaffold_reply(
    bundle: &Path,
    index: usize,
    output: &YamlValue,
    diagnostics: &mut Vec<TraceDiagnostic>,
) {
    let reply_tag = get_str(output, &["reply", "tag"]).or_else(|| get_str(output, &["reply"]));
    if reply_tag == Some("NoReplyDeclared") {
        push_trace_diagnostic(
            diagnostics,
            Severity::Warning,
            "trace.no-reply-declared",
            bundle,
            Some(index),
            "trace output uses scaffold `NoReplyDeclared`; declare a reply, rejection, or explicit no-reply justification through RMS",
        );
    }
}

fn validate_trace_output_envelopes(
    bundle: &Path,
    index: usize,
    output: &YamlValue,
    diagnostics: &mut Vec<TraceDiagnostic>,
) {
    for command in yaml_sequence_items(output, "commands") {
        validate_trace_envelope(
            bundle,
            index,
            "trace.command-envelope-incomplete",
            "command",
            command,
            &[
                "command_id",
                "target_machine",
                "correlation_id",
                "causation_id",
            ],
            diagnostics,
        );
    }
    for event in yaml_sequence_items(output, "events") {
        validate_trace_envelope(
            bundle,
            index,
            "trace.event-envelope-incomplete",
            "event",
            event,
            &[
                "event_id",
                "source_machine",
                "correlation_id",
                "causation_id",
                "sequence",
                "schema_version",
                "occurred_at",
            ],
            diagnostics,
        );
    }
    for effect in yaml_sequence_items(output, "effects") {
        validate_trace_envelope(
            bundle,
            index,
            "trace.effect-envelope-incomplete",
            "effect",
            effect,
            &["effect_id", "requester", "correlation_id", "causation_id"],
            diagnostics,
        );
    }
    for result in yaml_sequence_items(output, "effect_results") {
        validate_trace_envelope(
            bundle,
            index,
            "trace.effect-result-envelope-incomplete",
            "effect result",
            result,
            &[
                "effect_id",
                "requester",
                "correlation_id",
                "causation_id",
                "status",
            ],
            diagnostics,
        );
    }
}

fn validate_trace_envelope(
    bundle: &Path,
    index: usize,
    check: impl Into<String>,
    label: &str,
    value: &YamlValue,
    required: &[&str],
    diagnostics: &mut Vec<TraceDiagnostic>,
) {
    if value.as_mapping().is_none()
        || !required
            .iter()
            .any(|field| yaml_mapping_get(value, field).is_some())
    {
        return;
    }
    let missing = required
        .iter()
        .filter(|field| yaml_mapping_get(value, field).is_none())
        .copied()
        .collect::<Vec<_>>();
    if missing.is_empty() {
        return;
    }
    push_trace_diagnostic(
        diagnostics,
        Severity::Warning,
        check,
        bundle,
        Some(index),
        format!("{label} envelope is missing {}", missing.join(", ")),
    );
}

fn inspect_explicit_trace_diagnostics(
    bundle: &Path,
    index: usize,
    record: &YamlValue,
    diagnostics: &mut Vec<TraceDiagnostic>,
) {
    let Some(items) = get_path(record, &["diagnostics"]).and_then(YamlValue::as_sequence) else {
        return;
    };
    for item in items {
        let severity = get_str(item, &["severity"])
            .and_then(parse_trace_severity)
            .unwrap_or(Severity::Warning);
        let check = get_str(item, &["check"]).unwrap_or("trace.record-diagnostic");
        let message = get_str(item, &["message"]).unwrap_or("record diagnostic");
        push_trace_diagnostic(diagnostics, severity, check, bundle, Some(index), message);
    }
}

fn parse_trace_severity(value: &str) -> Option<Severity> {
    match value {
        "error" | "Error" => Some(Severity::Error),
        "warning" | "Warning" => Some(Severity::Warning),
        "info" | "Info" => Some(Severity::Info),
        _ => None,
    }
}

fn trace_record_summary(index: usize, record: &YamlValue) -> TraceRecordSummary {
    let output = get_path(record, &["output"]);
    TraceRecordSummary {
        index,
        id: trace_record_id(record),
        state_before: trace_record_state_before(record).map(trace_value_summary),
        state_after: trace_record_state_after(record).map(trace_value_summary),
        input: trace_record_input(record).map(trace_value_summary),
        reply: output
            .and_then(|value| yaml_mapping_get(value, "reply"))
            .or_else(|| output.and_then(|value| yaml_mapping_get(value, "rejection")))
            .map(trace_value_summary),
        events: output
            .map(|value| yaml_sequence_len(value, "events"))
            .unwrap_or(0),
        commands: output
            .map(|value| yaml_sequence_len(value, "commands"))
            .unwrap_or(0),
        effects: output
            .map(|value| yaml_sequence_len(value, "effects"))
            .unwrap_or(0),
        source: trace_record_source(record),
    }
}

fn trace_record_id(record: &YamlValue) -> Option<String> {
    yaml_mapping_get(record, "id")
        .or_else(|| yaml_mapping_get(record, "transition_id"))
        .and_then(yaml_scalar_string)
}

fn trace_record_input(record: &YamlValue) -> Option<&YamlValue> {
    yaml_mapping_get(record, "input")
        .or_else(|| yaml_mapping_get(record, "command"))
        .or_else(|| yaml_mapping_get(record, "event"))
        .or_else(|| yaml_mapping_get(record, "effect_result"))
}

fn trace_record_state_before(record: &YamlValue) -> Option<&YamlValue> {
    yaml_mapping_get(record, "state_before")
}

fn trace_record_state_after(record: &YamlValue) -> Option<&YamlValue> {
    yaml_mapping_get(record, "state_after").or_else(|| get_path(record, &["output", "next_state"]))
}

fn trace_record_source(record: &YamlValue) -> Option<String> {
    let source = yaml_mapping_get(record, "source")?;
    if let Some(value) = source.as_str() {
        return Some(value.to_string());
    }
    let mut parts = Vec::new();
    for key in ["machine", "file", "function", "branch"] {
        if let Some(value) = get_str(source, &[key]) {
            parts.push(format!("{key}={value}"));
        }
    }
    if parts.is_empty() {
        None
    } else {
        Some(parts.join(" "))
    }
}

fn first_bad_trace_transition(
    diagnostics: &[TraceDiagnostic],
    records: &[TraceRecordSummary],
) -> Option<TraceFirstBadTransition> {
    let selected = diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.record_index.is_some())
        .find(|diagnostic| diagnostic.severity == Severity::Error)
        .or_else(|| {
            diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.record_index.is_some())
                .find(|diagnostic| diagnostic.severity == Severity::Warning)
        })?;
    let index = selected.record_index?;
    Some(TraceFirstBadTransition {
        index,
        reason: format!("{}: {}", selected.check, selected.message),
        source: records
            .iter()
            .find(|record| record.index == index)
            .and_then(|record| record.source.clone()),
    })
}

fn trace_result(diagnostics: &[TraceDiagnostic]) -> &'static str {
    if diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Error)
    {
        "fail"
    } else if diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Warning)
    {
        "review-required"
    } else {
        "pass"
    }
}

fn trace_has_errors(report: &TraceReport) -> bool {
    report
        .diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Error)
}

fn push_trace_diagnostic(
    diagnostics: &mut Vec<TraceDiagnostic>,
    severity: Severity,
    check: impl Into<String>,
    bundle: &Path,
    record_index: Option<usize>,
    message: impl Into<String>,
) {
    diagnostics.push(TraceDiagnostic {
        severity,
        check: check.into(),
        path: bundle.display().to_string(),
        message: message.into(),
        record_index,
    });
}

fn print_trace_check_report(report: &TraceReport) {
    println!("RMS trace check: {}", report.result);
    print_trace_header(report);
    print_trace_findings(&report.diagnostics);
}

fn print_trace_replay_report(report: &TraceReport) {
    println!("RMS trace replay: {}", report.result);
    print_trace_header(report);
    println!("timeline:");
    if report.records.is_empty() {
        println!("  <no records>");
    }
    for record in &report.records {
        println!(
            "  {}. {} -> {} | input={} | reply={} | events={} commands={} effects={}{}",
            record.index + 1,
            record.state_before.as_deref().unwrap_or("<missing>"),
            record.state_after.as_deref().unwrap_or("<missing>"),
            record.input.as_deref().unwrap_or("<missing>"),
            record.reply.as_deref().unwrap_or("<missing>"),
            record.events,
            record.commands,
            record.effects,
            record
                .source
                .as_ref()
                .map(|source| format!(" | source={source}"))
                .unwrap_or_default()
        );
    }
    if let Some(last) = report.records.last() {
        println!(
            "final_state: {}",
            last.state_after.as_deref().unwrap_or("<missing>")
        );
    }
    print_trace_findings(&report.diagnostics);
}

fn print_trace_diagnose_report(report: &TraceReport) {
    println!("RMS trace diagnose: {}", report.result);
    print_trace_header(report);
    match &report.first_bad_transition {
        Some(first_bad) => {
            println!(
                "first_bad_transition: #{} {}",
                first_bad.index + 1,
                first_bad.reason
            );
            if let Some(source) = &first_bad.source {
                println!("source: {source}");
            }
        }
        None => println!("first_bad_transition: <none>"),
    }
    print_trace_findings(&report.diagnostics);
}

fn print_trace_header(report: &TraceReport) {
    println!("bundle: {}", report.bundle);
    println!("spec: {}", report.spec.as_deref().unwrap_or("<missing>"));
    println!(
        "machine: {}",
        report.machine.as_deref().unwrap_or("<missing>")
    );
    println!("records: {}", report.records.len());
}

fn print_trace_findings(diagnostics: &[TraceDiagnostic]) {
    if diagnostics.is_empty() {
        println!("findings: <none>");
        return;
    }
    println!("findings:");
    for diagnostic in diagnostics {
        let record = diagnostic
            .record_index
            .map(|index| format!(" record={}", index + 1))
            .unwrap_or_default();
        println!(
            "  {} [{}]{} {}",
            severity_label(diagnostic.severity),
            diagnostic.check,
            record,
            diagnostic.message
        );
    }
}

fn yaml_mapping_get<'a>(value: &'a YamlValue, key: &str) -> Option<&'a YamlValue> {
    value.as_mapping()?.get(YamlValue::String(key.to_string()))
}

fn yaml_sequence_items<'a>(value: &'a YamlValue, key: &str) -> &'a [YamlValue] {
    yaml_mapping_get(value, key)
        .and_then(YamlValue::as_sequence)
        .map(Vec::as_slice)
        .unwrap_or(&[])
}

fn yaml_sequence_len(value: &YamlValue, key: &str) -> usize {
    yaml_sequence_items(value, key).len()
}

fn yaml_scalar_string(value: &YamlValue) -> Option<String> {
    if let Some(value) = value.as_str() {
        return Some(value.to_string());
    }
    if let Some(value) = value.as_bool() {
        return Some(value.to_string());
    }
    if let Some(value) = value.as_i64() {
        return Some(value.to_string());
    }
    if let Some(value) = value.as_u64() {
        return Some(value.to_string());
    }
    if let Some(value) = value.as_f64() {
        return Some(value.to_string());
    }
    None
}

fn yaml_usize(value: &YamlValue) -> Option<usize> {
    if let Some(value) = value.as_u64() {
        return usize::try_from(value).ok();
    }
    if let Some(value) = value.as_i64() {
        return usize::try_from(value).ok();
    }
    None
}

fn trace_value_summary(value: &YamlValue) -> String {
    yaml_scalar_string(value).unwrap_or_else(|| atlas_yaml_inline(value, 120))
}

fn latest_run_dir(directory: &Path) -> Result<Option<PathBuf>> {
    let runs = collect_run_dirs(directory)?;
    Ok(runs.into_iter().next())
}

fn collect_run_dirs(directory: &Path) -> Result<Vec<PathBuf>> {
    if !directory.exists() {
        return Ok(Vec::new());
    }
    let mut runs = Vec::new();
    for entry in fs::read_dir(directory)
        .with_context(|| format!("failed to read run directory `{}`", directory.display()))?
        .filter_map(Result::ok)
    {
        let path = entry.path();
        if path.is_dir() {
            runs.push(path);
        }
    }
    runs.sort_by(|left, right| right.file_name().cmp(&left.file_name()));
    Ok(runs)
}

fn print_run_record(run_dir: &Path) -> Result<()> {
    println!("# RMS Run Record");
    println!();
    println!("Path: {}", run_dir.display());
    println!();

    print_run_request(&run_dir)?;
    print_run_files(&run_dir)?;
    print_run_checks(&run_dir)?;
    print_run_response(&run_dir)?;

    Ok(())
}

fn print_run_list_item(run_dir: &Path) -> Result<()> {
    let request = load_optional_yaml(&run_dir.join("request.yaml"))?;
    let run_id = request
        .as_ref()
        .and_then(|value| get_str(value, &["run_id"]))
        .or_else(|| run_dir.file_name().and_then(|name| name.to_str()))
        .unwrap_or("<unknown>");
    let prompt = request
        .as_ref()
        .and_then(|value| get_str(value, &["prompt"]))
        .unwrap_or("<unknown>");
    let provider = request
        .as_ref()
        .and_then(|value| get_str(value, &["provider"]))
        .unwrap_or("<unknown>");
    let task = request
        .as_ref()
        .and_then(|value| get_str(value, &["task"]))
        .unwrap_or("<none>");
    let response = if run_dir.join("response.md").exists() {
        "response"
    } else {
        "no-response"
    };
    println!("- {run_id}: {prompt} provider={provider} {response}");
    println!("  task: {task}");
    println!("  path: {}", run_dir.display());
    Ok(())
}

fn print_run_request(run_dir: &Path) -> Result<()> {
    println!("## Request");
    let Some(request) = load_optional_yaml(&run_dir.join("request.yaml"))? else {
        println!("- <missing request.yaml>");
        println!();
        return Ok(());
    };
    for field in [
        "run_id",
        "prompt",
        "provider",
        "module",
        "root",
        "task",
        "diff",
        "model",
        "sandbox",
        "source_revision",
    ] {
        if let Some(value) = get_str(&request, &[field]) {
            println!("- {field}: {value}");
        }
    }
    println!();
    Ok(())
}

fn print_run_files(run_dir: &Path) -> Result<()> {
    println!("## Files");
    for name in [
        "request.yaml",
        "prompt.md",
        "checks.json",
        "response.md",
        "provider.stdout.log",
        "provider.stderr.log",
    ] {
        let path = run_dir.join(name);
        if path.exists() {
            let size = fs::metadata(&path)
                .map(|metadata| metadata.len())
                .unwrap_or(0);
            println!("- {name}: {} bytes ({})", size, path.display());
        }
    }
    println!();
    Ok(())
}

fn print_run_checks(run_dir: &Path) -> Result<()> {
    println!("## Checks");
    let path = run_dir.join("checks.json");
    if !path.exists() {
        println!("- <missing checks.json>");
        println!();
        return Ok(());
    }
    let source = fs::read_to_string(&path)
        .with_context(|| format!("failed to read `{}`", path.display()))?;
    let value: JsonValue = serde_json::from_str(&source)
        .with_context(|| format!("failed to parse `{}`", path.display()))?;
    let diagnostics = value
        .get("validation")
        .and_then(JsonValue::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    println!(
        "- validator: {} {}",
        value
            .get("validator")
            .and_then(JsonValue::as_str)
            .unwrap_or("<unknown>"),
        value
            .get("validator_version")
            .and_then(JsonValue::as_str)
            .unwrap_or("")
    );
    println!("- validation diagnostics: {diagnostics}");
    println!();
    Ok(())
}

fn print_run_response(run_dir: &Path) -> Result<()> {
    let path = run_dir.join("response.md");
    if !path.exists() {
        return Ok(());
    }
    println!("## Response");
    let response = fs::read_to_string(&path)
        .with_context(|| format!("failed to read `{}`", path.display()))?;
    print!("{}", truncate_for_prompt(&response, 12_000));
    if !response.ends_with('\n') {
        println!();
    }
    Ok(())
}

fn resolve_run_dir(run: &Path, root: &Path, run_root: &Path) -> PathBuf {
    if run.exists() || run.components().count() > 1 {
        run.to_path_buf()
    } else {
        root.join(run_root).join(run)
    }
}

fn load_optional_yaml(path: &Path) -> Result<Option<YamlValue>> {
    if !path.exists() {
        return Ok(None);
    }
    let source =
        fs::read_to_string(path).with_context(|| format!("failed to read `{}`", path.display()))?;
    let value = serde_yaml::from_str(&source)
        .with_context(|| format!("failed to parse YAML `{}`", path.display()))?;
    Ok(Some(value))
}

fn run_id(kind: PromptKind, manifest: &LoadedManifest) -> String {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or(0);
    let module = get_str(&manifest.value, &["module", "name"]).unwrap_or("module");
    format!(
        "{}-{}-{}",
        timestamp,
        kind.label(),
        sanitize_run_segment(module)
    )
}

fn sanitize_run_segment(value: &str) -> String {
    let sanitized = value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || character == '-' || character == '_' {
                character
            } else {
                '-'
            }
        })
        .collect::<String>();
    let trimmed = sanitized.trim_matches('-');
    if trimmed.is_empty() {
        "run".to_string()
    } else {
        trimmed.to_string()
    }
}

fn render_run_request_yaml(
    manifest: &LoadedManifest,
    root: &Path,
    kind: PromptKind,
    task: Option<&str>,
    diff: Option<&str>,
    impact: bool,
    options: &PromptRunOptions,
    run_id: &str,
) -> String {
    let mut out = String::new();
    let task = task.or_else(|| kind.default_task()).unwrap_or("");
    let _ = writeln!(out, "run_id: {}", yaml_quote(run_id));
    let _ = writeln!(out, "prompt: {}", yaml_quote(kind.prompt_id()));
    let _ = writeln!(out, "provider: {}", yaml_quote(options.provider.label()));
    let _ = writeln!(
        out,
        "module: {}",
        yaml_quote(&manifest.path.display().to_string())
    );
    let _ = writeln!(out, "root: {}", yaml_quote(&root.display().to_string()));
    let _ = writeln!(out, "task: {}", yaml_quote(task));
    if let Some(diff) = diff {
        let _ = writeln!(out, "diff: {}", yaml_quote(diff));
    }
    if impact {
        let _ = writeln!(out, "impact: true");
    }
    if let Some(model) = &options.model {
        let _ = writeln!(out, "model: {}", yaml_quote(model));
    }
    let _ = writeln!(out, "sandbox: {}", yaml_quote(options.sandbox.as_str()));
    let _ = writeln!(
        out,
        "write_scope: {}",
        yaml_quote(options.write_scope.as_str())
    );
    let _ = writeln!(
        out,
        "provider_timeout_seconds: {}",
        options.provider_timeout_seconds
    );
    let _ = writeln!(
        out,
        "execution_root: {}",
        yaml_quote(
            &provider_execution_root(root, manifest, options)
                .display()
                .to_string()
        )
    );
    if let Some(revision) = source_revision(root) {
        let _ = writeln!(out, "source_revision: {}", yaml_quote(&revision));
    }
    out
}

fn render_workbench_prompt(
    manifest: &LoadedManifest,
    root: &Path,
    kind: PromptKind,
    task: Option<&str>,
    diff: Option<&str>,
    impact: bool,
) -> Result<String> {
    if impact && kind != PromptKind::Review {
        bail!("`--impact` is only supported for review prompts");
    }
    let effective_task = task
        .or_else(|| kind.default_task())
        .ok_or_else(|| anyhow!("{} prompts require `--task`", kind.label()))?;
    let include_diff = kind.includes_diff_by_default() || diff.is_some();
    let impact_report = if impact {
        let changed_paths = read_git_changed_paths(root, diff)?;
        Some(build_impact_report(root, diff, &changed_paths)?)
    } else {
        None
    };
    let diff_text = if include_diff {
        Some(read_git_diff(root, diff)?)
    } else {
        None
    };

    let mut out = String::new();
    writeln!(out, "# RMS Workbench Prompt")?;
    writeln!(out)?;
    writeln!(out, "Prompt: {}", kind.prompt_id())?;
    writeln!(
        out,
        "Mode: advisory; no edits are performed by this command"
    )?;
    writeln!(out, "Module: {}", manifest.path.display())?;
    writeln!(out, "Task: {effective_task}")?;
    writeln!(out)?;

    writeln!(out, "## Operating Rule")?;
    writeln!(out, "Use RMS canonical artifacts as the source of architectural truth. Do not infer ownership, effects, contracts, compatibility, or verification obligations from incidental code shape when the manifest or contracts say otherwise.")?;
    writeln!(out)?;

    append_route_recommendation_prompt(&mut out, manifest, root, effective_task, kind)?;
    if kind == PromptKind::Evidence {
        append_evidence_guidance_prompt(&mut out, manifest, root, effective_task)?;
    }

    append_prompt_context(&mut out, manifest, root)?;
    writeln!(out)?;

    append_semantic_structure_checklist(&mut out, kind)?;

    writeln!(out, "## Workflow")?;
    for item in kind.workflow() {
        writeln!(out, "- {item}")?;
    }
    writeln!(out)?;

    writeln!(out, "## Expected Output")?;
    for item in kind.expected_output() {
        writeln!(out, "- {item}")?;
    }
    writeln!(out)?;

    writeln!(out, "## Deterministic Checks")?;
    for item in kind.deterministic_checks() {
        writeln!(out, "- {item}")?;
    }

    if let Some(report) = &impact_report {
        append_impact_prompt(&mut out, report)?;
    }

    if let Some(diff_text) = diff_text {
        writeln!(out)?;
        writeln!(out, "## Diff")?;
        if diff_text.trim().is_empty() {
            writeln!(out, "<no diff content detected>")?;
        } else {
            writeln!(out, "```diff")?;
            writeln!(out, "{diff_text}")?;
            writeln!(out, "```")?;
        }
    }

    Ok(out)
}

fn append_semantic_structure_checklist(out: &mut String, kind: PromptKind) -> Result<()> {
    if !matches!(
        kind,
        PromptKind::Design | PromptKind::Plan | PromptKind::Implement
    ) {
        return Ok(());
    }

    writeln!(out, "## Semantic Structure Before Code")?;
    writeln!(
        out,
        "- Intent: restate the behavior, the owning context language, and what must never happen."
    )?;
    writeln!(out, "- ADTs and values: name closed variants, validated values, commands, states, events, and accepted/rejected result types.")?;
    writeln!(out, "- Role names: use domain-named suffixes where the language allows it, such as `<Domain>Machine`, `<Domain>State`, `<Domain>Command`, `<Domain>Event`, `<Domain>Effect`, `<Domain>EffectResult`, `<Domain>Reply`, and `<Domain>Rejection`. Do not derive these names from role or surface suffixes like rules, engine, adapter, cli, web, rust, swift, or js.")?;
    writeln!(out, "- Traceable machine rule: workflows orchestrate, machines execute, commands ask, events report, effects touch the world, projections observe, the journal explains, replay reproduces, and the first bad transition points to the fix.")?;
    writeln!(out, "- Messages: commands, events, effects, and effect results should use explicit envelopes with target/source, correlation, causation, schema/version, sequence, and idempotency metadata where applicable.")?;
    writeln!(out, "- Transitions: name accepted transitions, rejected transitions, terminal states, transition outputs, transition records, replay bundles, and first-bad-transition evidence when behavior depends on order or lifecycle.")?;
    writeln!(out, "- Boundaries: parse untrusted input into domain commands before pure decisions, and keep external effects behind ports or adapters.")?;
    writeln!(out, "- Numeric safety: if validated values represent counts, money, quantities, rates, sizes, scores, or other numeric facts, choose checked, saturating, bounded, or explicitly proven arithmetic before implementation.")?;
    writeln!(out, "- Edge cases first: invalid commands, impossible variants, invalid constructors, malformed inputs, illegal transitions, stale or conflicting state, duplicate or out-of-order external facts, numeric overflow or rounding, and not-applicable cases.")?;
    writeln!(out, "- Implementation comes after the structure is clear enough to encode in manifests, contracts, representation, transitions, adapters, tests, and evidence.")?;
    writeln!(out)?;
    Ok(())
}

fn append_impact_prompt(out: &mut String, report: &ImpactReport) -> Result<()> {
    const MAX_IMPACT_ITEMS: usize = 40;

    writeln!(out)?;
    writeln!(out, "## Impact")?;
    writeln!(out, "Derived from git changed paths and RMS artifacts. Treat this as review evidence, not architectural authority.")?;
    writeln!(out, "- Result: {}", impact_result_label(report.result))?;
    if let Some(revision) = &report.source_revision {
        writeln!(out, "- Source revision: {revision}")?;
    }
    if let Some(diff) = &report.diff {
        writeln!(out, "- Diff: {diff}")?;
    } else {
        writeln!(out, "- Diff: working tree")?;
    }
    writeln!(
        out,
        "- Affected modules: {}",
        if report.affected_modules.is_empty() {
            "<none>".to_string()
        } else {
            report
                .affected_modules
                .iter()
                .map(|module| module.name.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        }
    )?;

    writeln!(out)?;
    writeln!(out, "### Impact Paths")?;
    if report.changed_paths.is_empty() {
        writeln!(out, "- <none>")?;
    } else {
        for path in report.changed_paths.iter().take(MAX_IMPACT_ITEMS) {
            writeln!(
                out,
                "- {} [{}] {}{}",
                path.status,
                impact_category_label(path.category),
                path.path,
                path.module
                    .as_ref()
                    .map(|module| format!(" ({module})"))
                    .unwrap_or_default()
            )?;
        }
        append_impact_truncation_note(out, report.changed_paths.len(), MAX_IMPACT_ITEMS)?;
    }

    writeln!(out)?;
    writeln!(out, "### Impact Findings")?;
    if report.findings.is_empty() {
        writeln!(out, "- <none>")?;
    } else {
        for finding in report.findings.iter().take(MAX_IMPACT_ITEMS) {
            writeln!(
                out,
                "- {} [{}] {}{}: {}",
                impact_result_label(finding.severity),
                finding.check,
                finding.path.as_deref().unwrap_or("<none>"),
                finding
                    .module
                    .as_ref()
                    .map(|module| format!(" ({module})"))
                    .unwrap_or_default(),
                finding.message
            )?;
        }
        append_impact_truncation_note(out, report.findings.len(), MAX_IMPACT_ITEMS)?;
    }

    writeln!(out)?;
    writeln!(out, "### Impact Checks")?;
    if report.recommended_checks.is_empty() {
        writeln!(out, "- <none>")?;
    } else {
        for check in &report.recommended_checks {
            writeln!(out, "- {check}")?;
        }
    }

    Ok(())
}

fn append_impact_truncation_note(out: &mut String, total: usize, limit: usize) -> Result<()> {
    if total > limit {
        writeln!(out, "- [{} additional items omitted]", total - limit)?;
    }
    Ok(())
}

fn append_route_recommendation_prompt(
    out: &mut String,
    manifest: &LoadedManifest,
    root: &Path,
    task: &str,
    kind: PromptKind,
) -> Result<()> {
    let report = build_route_report(&manifest.path, root, task)?;
    if report.result == RouteResult::TargetOnly {
        return Ok(());
    }

    append_route_recommendation_section(out, &report)?;
    if kind == PromptKind::Implement {
        writeln!(out)?;
        writeln!(out, "### Implementation Routing Rule")?;
        match report.result {
            RouteResult::Routed => {
                let recommendation = report
                    .recommendation
                    .as_ref()
                    .map(|module| module.name.as_str())
                    .unwrap_or("<unknown>");
                writeln!(
                    out,
                    "- Implement in `{recommendation}` unless the task explicitly changes parent composition, exports, parent contracts, or parent evidence."
                )?;
                writeln!(
                    out,
                    "- Do not add private implementation behavior to composite parent `{}` as a convenience.",
                    report.target.name
                )?;
            }
            RouteResult::Ambiguous => {
                writeln!(
                    out,
                    "- Do not edit yet. Inspect the route candidates and choose the owning module before implementation."
                )?;
            }
            RouteResult::TargetOnly => {}
        }
    }
    writeln!(out)?;
    Ok(())
}

fn append_route_recommendation_section(out: &mut String, report: &RouteReport) -> Result<()> {
    writeln!(out, "## Route Recommendation")?;
    writeln!(
        out,
        "Derived from canonical composition, exports, semantic shapes, public surfaces, and task language. Treat this as routing evidence, not architectural authority."
    )?;
    writeln!(out, "- Result: {}", route_result_label(report.result))?;
    writeln!(
        out,
        "- Target: {} ({}, shape: {})",
        report.target.name, report.target.kind, report.target.shape
    )?;
    if let Some(recommendation) = &report.recommendation {
        writeln!(
            out,
            "- Recommended owner: {} ({}, shape: {})",
            recommendation.name, recommendation.kind, recommendation.shape
        )?;
        writeln!(out, "- Recommended path: {}", recommendation.path)?;
    } else {
        writeln!(out, "- Recommended owner: <ambiguous>")?;
    }

    writeln!(out)?;
    writeln!(out, "### Route Candidates")?;
    for candidate in &report.candidates {
        let visibility = candidate.module.visibility.as_deref().unwrap_or("<target>");
        writeln!(
            out,
            "- {} score={} visibility={} shape={} path={}",
            candidate.module.name,
            candidate.score,
            visibility,
            candidate.module.shape,
            candidate.module.path
        )?;
        for reason in &candidate.reasons {
            writeln!(out, "  - {reason}")?;
        }
    }

    if !report.warnings.is_empty() {
        writeln!(out)?;
        writeln!(out, "### Route Warnings")?;
        for warning in &report.warnings {
            writeln!(out, "- {warning}")?;
        }
    }

    writeln!(out)?;
    writeln!(out, "### Route Follow-up")?;
    for command in &report.next_commands {
        writeln!(out, "- {command}")?;
    }
    Ok(())
}

fn append_evidence_guidance_prompt(
    out: &mut String,
    manifest: &LoadedManifest,
    root: &Path,
    task: &str,
) -> Result<()> {
    let report = build_route_report(&manifest.path, root, task)?;
    let owner = report.recommendation.as_ref().unwrap_or(&report.target);

    writeln!(out, "## Evidence Guidance")?;
    writeln!(
        out,
        "Derived from the routed owner shape. Use the smallest evidence that proves the changed promise; do not add proof for behavior absent from canonical artifacts."
    )?;
    writeln!(
        out,
        "- Evidence owner: {} ({}, shape: {})",
        owner.name, owner.kind, owner.shape
    )?;
    writeln!(out, "- Evidence owner path: {}", owner.path)?;
    if report.result == RouteResult::Ambiguous {
        writeln!(
            out,
            "- Routing is ambiguous; choose the owning module before writing evidence."
        )?;
    }
    writeln!(out)?;
    writeln!(out, "### Recommended Evidence")?;
    for item in evidence_guidance_items(&owner.shape) {
        writeln!(out, "- {item}")?;
    }
    if task_mentions_public_surface_change(task) || report.target.shape == "composite" {
        writeln!(
            out,
            "- If public behavior changes, add parent/export contract evidence such as `verification/contracts/parent_export.md` and keep exported child contract evidence aligned."
        )?;
    }
    writeln!(out)?;
    writeln!(out, "### Evidence Completion Gate")?;
    writeln!(
        out,
        "- Replace or remove scaffold placeholder evidence before declaring the module done."
    )?;
    writeln!(
        out,
        "- `rms validate --root <root>` should not report `evidence.placeholder`, `evidence.bootstrap-active`, `evidence.source-unpinned`, or `evidence.semantic-shape-only` for modules claimed as implemented."
    )?;
    writeln!(
        out,
        "- `rms audit --root <root> --strict` should pass before claiming production-ready RMS software."
    )?;
    writeln!(
        out,
        "- Every active evidence file should name the promise proved, positive and negative cases when applicable, the command/tool used, and the source revision or working-tree status."
    )?;
    writeln!(
        out,
        "- Stateful or workflow evidence should include transition records or golden timeline tests, replay input, and the source transition used for first-bad-transition debugging when applicable."
    )?;
    writeln!(out)?;
    Ok(())
}

fn evidence_guidance_items(shape: &str) -> &'static [&'static str] {
    match shape {
        "domain-engine" => &[
            "law/property evidence for invariant-bearing decisions",
            "invalid constructor or impossible variant rejection cases",
            "accepted and rejected transition records in `verification/scenarios/accepted_rejected.md`",
            "transition records and replay bundles showing state before, state after, emitted outputs, and source branch",
            "first-bad-transition evidence or fuzz/property coverage when the transition space is broad",
            "semantic-function evidence for representation constructors and transition functions",
        ],
        "boundary-adapter" => &[
            "malformed input and parser rejection evidence in `verification/boundaries/malformed_input.md`",
            "parser-to-domain-command evidence showing boundary input becomes a domain command before core decisions",
            "command envelope evidence showing target, correlation, causation, and idempotency metadata where applicable",
            "adapter failure evidence for declared effects, including timeout, retry, rejection, or fallback behavior when applicable",
            "contract smoke evidence through the public command or parent export when externally visible behavior changes",
        ],
        "runtime-monitor" => &[
            "runtime evidence for trigger and non-trigger cases over declared observations",
            "derived fact or stream evidence showing monitor decisions are computed from accepted inputs",
            "passive projection evidence proving projections observe and do not emit workflow commands",
            "authority evidence proving observe-only, advisory, enforcing, or fail-safe outputs cross declared contracts",
            "stale, duplicate, or out-of-order observation evidence when ordering affects monitor decisions",
            "failure-mode evidence for fail-open, fail-closed, or degraded behavior",
        ],
        "workflow" => &[
            "accepted and rejected command/event transition evidence",
            "golden timeline evidence showing workflow state, emitted commands, requested effects, and terminal outcome",
            "deadline, compensation, terminal-state, and recovery scenarios when declared",
            "transition-record replay bundle and first-bad-transition evidence for lifecycle order and illegal transitions",
        ],
        "storage-adapter" => &[
            "persistence port contract evidence for success and expected storage failures",
            "migration, recovery, and corrupted/unavailable store evidence when declared",
            "idempotency or replay evidence for write paths when applicable",
        ],
        "integration-adapter" => &[
            "external contract boundary evidence using recorded or simulated provider responses",
            "retry, timeout, idempotency, duplicate, and reconciliation evidence when declared",
            "malformed or incompatible provider payload rejection evidence",
        ],
        "composite" => &[
            "parent export evidence proving the published surface is backed by the declared child",
            "composition scenario evidence such as `verification/scenarios/composed_capability.md`",
            "child verification rollup evidence when contained modules have implementation bindings",
        ],
        _ => &[
            "law, contract, scenario, or boundary evidence matching the declared module promises",
            "positive and negative cases tied to public contracts, invariants, effects, and compatibility",
        ],
    }
}

fn append_prompt_context(out: &mut String, manifest: &LoadedManifest, root: &Path) -> Result<()> {
    writeln!(out, "## Bounded RMS Context")?;
    writeln!(
        out,
        "- Name: {} {}",
        get_str(&manifest.value, &["module", "name"]).unwrap_or("<unknown>"),
        get_str(&manifest.value, &["module", "version"]).unwrap_or("")
    )?;
    writeln!(
        out,
        "- Kind: {}",
        get_str(&manifest.value, &["module", "kind"]).unwrap_or("<missing>")
    )?;
    writeln!(
        out,
        "- Purpose: {}",
        get_str(&manifest.value, &["module", "purpose"]).unwrap_or("<missing>")
    )?;
    append_prompt_string_list(
        out,
        "Profiles",
        &get_string_array(&manifest.value, &["profiles"]),
    )?;
    append_prompt_owned_terms(out, &manifest.value)?;
    append_prompt_contract_groups(out, "Provides", get_path(&manifest.value, &["provides"]))?;
    append_prompt_contract_groups(out, "Requires", get_path(&manifest.value, &["requires"]))?;
    append_prompt_invariants(out, &manifest.value)?;
    append_prompt_effects(out, &manifest.value)?;
    append_prompt_shape_advisories(out, manifest)?;
    writeln!(
        out,
        "- Compatibility: {}",
        get_str(&manifest.value, &["compatibility", "policy"]).unwrap_or("<missing>")
    )?;
    append_prompt_verification(out, &manifest.value)?;
    append_prompt_change_protocols(out, &manifest.value)?;

    writeln!(out)?;
    writeln!(out, "### Canonical Files")?;
    for file_name in ["system.yaml", "context-map.yaml", "GLOSSARY.md"] {
        let path = root.join(file_name);
        if path.exists() {
            writeln!(out, "- {}", path.display())?;
        }
    }
    for reference in referenced_paths(&manifest.value) {
        let path = manifest
            .path
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .join(&reference);
        writeln!(out, "- {}", path.display())?;
    }

    Ok(())
}

fn append_prompt_shape_advisories(out: &mut String, manifest: &LoadedManifest) -> Result<()> {
    let advisories = shape_advisories(manifest);
    if advisories.is_empty() {
        return Ok(());
    }
    writeln!(out, "- Shape advisories:")?;
    for advisory in advisories {
        writeln!(out, "  - {advisory}")?;
    }
    Ok(())
}

fn append_prompt_string_list(out: &mut String, label: &str, items: &[String]) -> Result<()> {
    writeln!(
        out,
        "- {label}: {}",
        if items.is_empty() {
            "<none>".to_string()
        } else {
            items.join(", ")
        }
    )?;
    Ok(())
}

fn append_prompt_owned_terms(out: &mut String, value: &YamlValue) -> Result<()> {
    writeln!(out, "- Ownership:")?;
    if let Some(owns) = get_path(value, &["owns"]).and_then(YamlValue::as_mapping) {
        for (key, values) in owns {
            let label = key.as_str().unwrap_or("<unknown>");
            let items = values
                .as_sequence()
                .map(|items| {
                    items
                        .iter()
                        .filter_map(YamlValue::as_str)
                        .collect::<Vec<_>>()
                        .join(", ")
                })
                .unwrap_or_default();
            writeln!(
                out,
                "  - {label}: {}",
                if items.is_empty() { "<none>" } else { &items }
            )?;
        }
    } else {
        writeln!(out, "  - <missing>")?;
    }
    Ok(())
}

fn append_prompt_contract_groups(
    out: &mut String,
    label: &str,
    value: Option<&YamlValue>,
) -> Result<()> {
    writeln!(out, "- {label}:")?;
    let Some(groups) = value.and_then(YamlValue::as_mapping) else {
        writeln!(out, "  - <missing>")?;
        return Ok(());
    };
    for (group, items) in groups {
        let group = group.as_str().unwrap_or("<unknown>");
        writeln!(out, "  - {group}:")?;
        if let Some(items) = items.as_sequence() {
            for item in items {
                match item {
                    YamlValue::String(name) => writeln!(out, "    - {name}")?,
                    YamlValue::Mapping(mapping) => {
                        let name = mapping
                            .get(YamlValue::String("name".to_string()))
                            .and_then(YamlValue::as_str)
                            .unwrap_or("<unnamed>");
                        let contract = mapping
                            .get(YamlValue::String("contract".to_string()))
                            .and_then(YamlValue::as_str)
                            .unwrap_or("<no contract>");
                        writeln!(out, "    - {name} ({contract})")?;
                    }
                    _ => writeln!(out, "    - <unsupported reference>")?,
                }
            }
        }
    }
    Ok(())
}

fn append_prompt_invariants(out: &mut String, value: &YamlValue) -> Result<()> {
    writeln!(out, "- Invariants:")?;
    let Some(invariants) = get_path(value, &["invariants"]).and_then(YamlValue::as_sequence) else {
        writeln!(out, "  - <missing>")?;
        return Ok(());
    };
    if invariants.is_empty() {
        writeln!(out, "  - <none declared>")?;
        return Ok(());
    }
    for invariant in invariants {
        writeln!(
            out,
            "  - {}: {}",
            get_str(invariant, &["id"]).unwrap_or("<missing-id>"),
            get_str(invariant, &["statement"]).unwrap_or("<missing statement>")
        )?;
    }
    Ok(())
}

fn append_prompt_effects(out: &mut String, value: &YamlValue) -> Result<()> {
    writeln!(out, "- Effects:")?;
    let Some(effects) = get_path(value, &["effects"]).and_then(YamlValue::as_sequence) else {
        writeln!(out, "  - <missing>")?;
        return Ok(());
    };
    if effects.is_empty() {
        writeln!(out, "  - <none declared>")?;
        return Ok(());
    }
    for effect in effects {
        writeln!(
            out,
            "  - {} ({})",
            get_str(effect, &["name"]).unwrap_or("<unnamed>"),
            get_str(effect, &["kind"]).unwrap_or("<unknown-kind>")
        )?;
    }
    Ok(())
}

fn append_prompt_verification(out: &mut String, value: &YamlValue) -> Result<()> {
    writeln!(out, "- Verification:")?;
    for category in verification_reference_categories() {
        let items = get_string_array(value, &["verification", category]);
        writeln!(
            out,
            "  - {category}: {}",
            if items.is_empty() {
                "<none>".to_string()
            } else {
                items.join(", ")
            }
        )?;
    }
    Ok(())
}

fn append_prompt_change_protocols(out: &mut String, value: &YamlValue) -> Result<()> {
    let Some(protocols) = change_protocol_items(value) else {
        return Ok(());
    };
    if protocols.is_empty() {
        return Ok(());
    }

    writeln!(out, "- Change Protocols:")?;
    for protocol in protocols {
        let id = get_str(protocol, &["id"]).unwrap_or("<missing-id>");
        let applies_when = get_str(protocol, &["applies_when"]).unwrap_or("<missing applies_when>");
        writeln!(out, "  - {id}: {applies_when}")?;
        if let Some(classification) = get_str(protocol, &["classification"]) {
            writeln!(out, "    classification: {classification}")?;
        }
        let required_updates = get_string_array(protocol, &["required_updates"]);
        if !required_updates.is_empty() {
            writeln!(out, "    required updates:")?;
            for update in required_updates {
                writeln!(out, "      - {update}")?;
            }
        }
        let verify = get_string_array(protocol, &["verify"]);
        if !verify.is_empty() {
            writeln!(out, "    verify:")?;
            for command in verify {
                writeln!(out, "      - {command}")?;
            }
        }
    }
    Ok(())
}

fn read_git_diff(root: &Path, diff: Option<&str>) -> Result<String> {
    let mut command = Command::new("git");
    command.current_dir(root).arg("diff");
    if let Some(diff) = diff {
        command.arg(diff);
    }
    let output = match command.output() {
        Ok(output) => output,
        Err(error) => return Ok(format!("diff unavailable: {error}")),
    };
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Ok(format!(
            "diff unavailable: git exited with status {}{}",
            output
                .status
                .code()
                .map(|code| code.to_string())
                .unwrap_or_else(|| "signal".to_string()),
            if stderr.trim().is_empty() {
                String::new()
            } else {
                format!(": {}", stderr.trim())
            }
        ));
    }
    Ok(truncate_for_prompt(
        String::from_utf8_lossy(&output.stdout).as_ref(),
        16_000,
    ))
}

fn truncate_for_prompt(value: &str, limit: usize) -> String {
    if value.len() <= limit {
        return value.to_string();
    }
    let mut end = 0;
    for (index, character) in value.char_indices() {
        let next = index + character.len_utf8();
        if next > limit {
            break;
        }
        end = next;
    }
    let mut truncated = value[..end].to_string();
    truncated.push_str("\n[truncated for prompt]\n");
    truncated
}

fn run_impact(root: &Path, diff: Option<&str>, json_output: bool) -> Result<()> {
    let changed_paths = read_git_changed_paths(root, diff)?;
    let report = build_impact_report(root, diff, &changed_paths)?;

    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_impact_report(&report);
    }

    Ok(())
}

fn run_gate(root: &Path, diff: Option<&str>, dry_run: bool, json_output: bool) -> Result<()> {
    let mut plan = match read_git_changed_paths(root, diff) {
        Ok(changed_paths) => {
            let impact = build_impact_report(root, diff, &changed_paths)?;
            build_gate_plan(root, diff, &impact)
        }
        Err(error) if diff.is_none() && is_missing_git_repository_error(&error) => {
            build_nongit_gate_plan(root)?
        }
        Err(error) => return Err(error),
    };

    if !dry_run {
        for index in 0..plan.actions.len() {
            match run_gate_action(root, &plan.actions[index]) {
                Ok(message) => {
                    plan.report.executable_checks[index].status = GateCheckStatus::Pass;
                    plan.report.executable_checks[index].message = Some(message);
                }
                Err(error) => {
                    plan.report.executable_checks[index].status = GateCheckStatus::Fail;
                    plan.report.executable_checks[index].message = Some(error.to_string());
                }
            }
        }
        plan.report.result = if plan
            .report
            .executable_checks
            .iter()
            .any(|check| check.status == GateCheckStatus::Fail)
        {
            GateResult::Fail
        } else {
            GateResult::Pass
        };
    }

    if json_output {
        println!("{}", serde_json::to_string_pretty(&plan.report)?);
    } else {
        print_gate_report(&plan.report);
    }

    if plan.report.result == GateResult::Fail {
        bail!("RMS gate failed");
    }

    Ok(())
}

fn is_missing_git_repository_error(error: &anyhow::Error) -> bool {
    let message = error.to_string();
    message.contains("git repository required") || message.contains("not a git repository")
}

fn build_nongit_gate_plan(root: &Path) -> Result<GatePlan> {
    let mut executable_checks = Vec::new();
    let mut actions = Vec::new();
    let mut seen_executable = BTreeSet::new();
    let mut manual_checks = BTreeSet::new();

    push_gate_check(
        &mut executable_checks,
        &mut actions,
        &mut seen_executable,
        format!("rms validate --root {}", root.display()),
        GateCheckAction::ValidateRoot,
    );
    push_gate_check(
        &mut executable_checks,
        &mut actions,
        &mut seen_executable,
        format!("rms compose --root {}", root.display()),
        GateCheckAction::ComposeRoot,
    );

    let modules = load_module_index(root)?;
    let mut affected_modules = Vec::new();
    for module in modules.values() {
        affected_modules.push(module.name.clone());
        let Some(target) = module_verification_target_for_entry(root, module) else {
            manual_checks.insert(format!(
                "Add or identify a deterministic verification target before verifying {}",
                module.name
            ));
            continue;
        };
        push_gate_check(
            &mut executable_checks,
            &mut actions,
            &mut seen_executable,
            format!("rms verify {}", target.display()),
            GateCheckAction::VerifyTarget(target),
        );
    }

    affected_modules.sort();
    affected_modules.dedup();
    manual_checks.insert(
        "No git repository was detected; gate ran deterministic full-project checks without changed-path impact evidence, and strict audit cannot pass until the project is committed.".to_string(),
    );

    Ok(GatePlan {
        report: GateReport {
            result: GateResult::Pending,
            root: root.display().to_string(),
            diff: None,
            source_revision: source_revision(root),
            impact_result: ImpactResult::ReviewRequired,
            affected_modules,
            executable_checks,
            manual_checks: manual_checks.into_iter().collect(),
        },
        actions,
    })
}

fn module_verification_target_for_entry(root: &Path, module: &ModuleIndexEntry) -> Option<PathBuf> {
    let module_dir = module.path.parent().unwrap_or_else(|| Path::new("."));
    let implementation = module_dir.join("implementation.yaml");
    if implementation.exists() {
        return Some(PathBuf::from(display_relative(root, &implementation)));
    }
    if is_composite_module(&module.value) {
        return Some(PathBuf::from(display_relative(root, &module.path)));
    }
    None
}

fn build_gate_plan(root: &Path, diff: Option<&str>, impact: &ImpactReport) -> GatePlan {
    let mut executable_checks = Vec::new();
    let mut actions = Vec::new();
    let mut seen_executable = BTreeSet::new();
    let mut manual_checks = BTreeSet::new();

    if impact.result != ImpactResult::NoRmsImpact && !impact.changed_paths.is_empty() {
        push_gate_check(
            &mut executable_checks,
            &mut actions,
            &mut seen_executable,
            format!("rms validate --root {}", root.display()),
            GateCheckAction::ValidateRoot,
        );

        if impact.changed_paths.iter().any(|path| {
            matches!(
                path.category,
                ImpactCategory::SystemManifest
                    | ImpactCategory::ContextMap
                    | ImpactCategory::ModuleManifest
                    | ImpactCategory::Contract
                    | ImpactCategory::Operations
                    | ImpactCategory::Glossary
            )
        }) {
            push_gate_check(
                &mut executable_checks,
                &mut actions,
                &mut seen_executable,
                format!("rms compose --root {}", root.display()),
                GateCheckAction::ComposeRoot,
            );
        }

        let diff_arg = diff
            .map(|diff| format!(" --diff {diff}"))
            .unwrap_or_default();
        for module in &impact.affected_modules {
            if module
                .categories
                .iter()
                .any(|category| gate_category_requires_verification(*category))
            {
                if let Some(target) = module_verification_target(root, module) {
                    push_gate_check(
                        &mut executable_checks,
                        &mut actions,
                        &mut seen_executable,
                        format!("rms verify {target}"),
                        GateCheckAction::VerifyTarget(PathBuf::from(target)),
                    );
                } else {
                    manual_checks.insert(format!(
                        "Add or identify a deterministic verification target before verifying {}",
                        module.name
                    ));
                }
            }

            if module
                .categories
                .iter()
                .any(|category| gate_category_requires_review(*category))
            {
                manual_checks.insert(format!(
                    "rms review {} --impact{}",
                    module.manifest, diff_arg
                ));
            }

            if module.categories.iter().any(|category| {
                matches!(
                    category,
                    ImpactCategory::ModuleManifest | ImpactCategory::Contract
                )
            }) {
                manual_checks.insert(format!(
                    "rms check-compat <previous {}> {}",
                    module.manifest, module.manifest
                ));
            }
        }

        for path in &impact.changed_paths {
            if path.module.is_none() && gate_category_requires_review(path.category) {
                manual_checks.insert(format!(
                    "Review {} [{}] for RMS conformance",
                    path.path,
                    impact_category_label(path.category)
                ));
            }
        }
    }

    let result = if executable_checks.is_empty() {
        GateResult::Pass
    } else {
        GateResult::Pending
    };
    if impact.source_revision.is_none() && git_worktree_exists(root) {
        manual_checks.insert(
            "Strict audit cannot pass until the project has a git source revision; commit the production candidate before running `rms audit --root . --strict`.".to_string(),
        );
    }

    GatePlan {
        report: GateReport {
            result,
            root: root.display().to_string(),
            diff: diff.map(ToString::to_string),
            source_revision: impact.source_revision.clone(),
            impact_result: impact.result,
            affected_modules: impact
                .affected_modules
                .iter()
                .map(|module| module.name.clone())
                .collect(),
            executable_checks,
            manual_checks: manual_checks.into_iter().collect(),
        },
        actions,
    }
}

fn push_gate_check(
    checks: &mut Vec<GateCheck>,
    actions: &mut Vec<GateCheckAction>,
    seen: &mut BTreeSet<String>,
    command: String,
    action: GateCheckAction,
) {
    if seen.insert(command.clone()) {
        checks.push(GateCheck {
            command,
            status: GateCheckStatus::Pending,
            message: None,
        });
        actions.push(action);
    }
}

fn gate_category_requires_verification(category: ImpactCategory) -> bool {
    matches!(
        category,
        ImpactCategory::Source
            | ImpactCategory::ImplementationBinding
            | ImpactCategory::VerificationEvidence
    )
}

fn gate_category_requires_review(category: ImpactCategory) -> bool {
    matches!(
        category,
        ImpactCategory::SystemManifest
            | ImpactCategory::ContextMap
            | ImpactCategory::ModuleManifest
            | ImpactCategory::Contract
            | ImpactCategory::ImplementationBinding
            | ImpactCategory::Operations
            | ImpactCategory::Glossary
    )
}

fn module_verification_target(root: &Path, module: &ImpactModuleImpact) -> Option<String> {
    if let Some(implementation) = &module.implementation {
        return Some(implementation.clone());
    }

    let manifest = load_manifest(&root.join(&module.manifest)).ok()?;
    if is_composite_module(&manifest.value) {
        Some(module.manifest.clone())
    } else {
        None
    }
}

fn run_gate_action(root: &Path, action: &GateCheckAction) -> Result<String> {
    match action {
        GateCheckAction::ValidateRoot => {
            let diagnostics = collect_validation_diagnostics(
                root,
                vec![],
                vec![],
                vec![],
                vec![],
                vec![],
                vec![],
            )?;
            let errors = diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.severity == Severity::Error)
                .count();
            let warnings = diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.severity == Severity::Warning)
                .count();
            if errors > 0 {
                bail!("{errors} RMS validation error(s)");
            }
            Ok(format!("{warnings} warning(s), no validation errors"))
        }
        GateCheckAction::ComposeRoot => {
            let report = compose_system(root)?;
            if report.result == ComposeResult::Fail {
                bail!(
                    "composition failed with {} finding(s)",
                    report.findings.len()
                );
            }
            Ok(format!(
                "composition {}",
                compose_result_label(report.result)
            ))
        }
        GateCheckAction::VerifyTarget(target) => run_verify_target_captured(&root.join(target)),
    }
}

fn run_verify_target_captured(target: &Path) -> Result<String> {
    let manifest = load_manifest(target)?;
    match get_str(&manifest.value, &["spec"]) {
        Some("rms/implementation/v0.1") => run_verify_implementation_captured(target),
        Some("rms/module/v0.1") if is_composite_module(&manifest.value) => {
            run_verify_composite_module_captured(target, &manifest)
        }
        Some("rms/module/v0.1") => bail!(
            "module `{}` is not a composite module; verify its implementation binding instead",
            get_str(&manifest.value, &["module", "name"]).unwrap_or("<unknown>")
        ),
        Some(other) => bail!("`{}` is not a verifiable RMS target", other),
        None => bail!("target is missing RMS `spec`"),
    }
}

fn run_verify_implementation_captured(implementation: &Path) -> Result<String> {
    let manifest = load_manifest(implementation)?;
    ensure_implementation_manifest_valid_for_verify(&manifest)?;
    let command = get_str(&manifest.value, &["commands", "verify"])
        .ok_or_else(|| anyhow!("implementation binding does not declare `commands.verify`"))?;
    let root = implementation.parent().unwrap_or_else(|| Path::new("."));
    let output = Command::new("sh")
        .arg("-c")
        .arg(command)
        .current_dir(root)
        .output()
        .with_context(|| format!("failed to run verify command `{command}`"))?;

    if !output.status.success() {
        bail!(
            "verify command failed with status {}{}",
            exit_status_label(output.status),
            command_output_excerpt(&output)
        );
    }

    let trace_reports = verify_declared_trace_bundles(&manifest, root)?;
    Ok(format!(
        "verify command passed: {command}{}",
        trace_verify_suffix(&trace_reports)
    ))
}

fn ensure_implementation_manifest_valid_for_verify(manifest: &LoadedManifest) -> Result<()> {
    let mut diagnostics = Vec::new();
    validate_loaded_manifest(manifest, &mut diagnostics);
    if let Some(diagnostic) = diagnostics
        .iter()
        .find(|diagnostic| diagnostic.severity == Severity::Error)
    {
        bail!(
            "implementation validation failed: [{}] {}",
            diagnostic.check,
            diagnostic.message
        );
    }
    Ok(())
}

fn verify_declared_trace_bundles(
    manifest: &LoadedManifest,
    module_root: &Path,
) -> Result<Vec<TraceReport>> {
    let mut reports = Vec::new();
    for bundle in implementation_trace_bundle_paths(manifest, module_root) {
        let report = build_trace_report(&bundle)?;
        if trace_has_errors(&report) {
            bail!(
                "trace bundle `{}` failed RMS trace check{}",
                bundle.display(),
                trace_error_suffix(&report)
            );
        }
        reports.push(report);
    }
    Ok(reports)
}

fn implementation_trace_bundle_paths(
    manifest: &LoadedManifest,
    module_root: &Path,
) -> Vec<PathBuf> {
    let mut paths = BTreeSet::new();
    for role in [
        "replay_bundle",
        "trace_evidence",
        "journal",
        "timeline_projection",
    ] {
        for reference in structure_role_paths(manifest, role) {
            push_trace_bundle_candidate(module_root, &reference, &mut paths);
        }
    }
    if let Some(functions) =
        get_path(&manifest.value, &["semantic_functions"]).and_then(YamlValue::as_sequence)
    {
        for function in functions {
            for reference in get_string_array(function, &["evidence", "traces"]) {
                push_trace_bundle_candidate(module_root, &reference, &mut paths);
            }
        }
    }
    let trace_dir = module_root.join("verification").join("traces");
    if trace_dir.is_dir() {
        for entry in WalkDir::new(&trace_dir)
            .follow_links(false)
            .into_iter()
            .filter_map(Result::ok)
            .filter(|entry| entry.file_type().is_file())
        {
            if is_trace_bundle_file(entry.path()) {
                paths.insert(entry.path().to_path_buf());
            }
        }
    }
    paths.into_iter().collect()
}

fn push_trace_bundle_candidate(root: &Path, reference: &str, paths: &mut BTreeSet<PathBuf>) {
    if reference.starts_with("http://")
        || reference.starts_with("https://")
        || reference.starts_with("urn:")
    {
        return;
    }
    let path = root.join(reference);
    if is_trace_bundle_file(&path) {
        paths.insert(path);
    }
}

fn is_trace_bundle_file(path: &Path) -> bool {
    matches!(
        path.extension().and_then(|extension| extension.to_str()),
        Some("yaml" | "yml" | "json")
    )
}

fn trace_verify_suffix(reports: &[TraceReport]) -> String {
    if reports.is_empty() {
        return String::new();
    }
    let warnings = reports
        .iter()
        .flat_map(|report| &report.diagnostics)
        .filter(|diagnostic| diagnostic.severity == Severity::Warning)
        .count();
    if warnings == 0 {
        format!("; {} trace bundle(s) checked", reports.len())
    } else {
        format!(
            "; {} trace bundle(s) checked with {} warning(s)",
            reports.len(),
            warnings
        )
    }
}

fn trace_error_suffix(report: &TraceReport) -> String {
    report
        .diagnostics
        .iter()
        .find(|diagnostic| diagnostic.severity == Severity::Error)
        .map(|diagnostic| format!(": [{}] {}", diagnostic.check, diagnostic.message))
        .unwrap_or_default()
}

fn run_verify_composite_module_captured(
    module_path: &Path,
    manifest: &LoadedManifest,
) -> Result<String> {
    let module_name = get_str(&manifest.value, &["module", "name"]).unwrap_or("<unknown>");
    let root = rms_root_for(module_path);

    let mut diagnostics = Vec::new();
    validate_loaded_manifest(manifest, &mut diagnostics);
    if diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Error)
    {
        bail!("composite module manifest validation failed");
    }

    let compose_report = compose_system(&root)?;
    if compose_report.result == ComposeResult::Fail {
        bail!("composite module composition failed");
    }

    ensure_composite_scenario_evidence(manifest, module_path)?;

    let modules = load_module_index(&root)?;
    let mut verified_children = 0usize;
    for child in composition_children_for(module_name, &manifest.value) {
        let Some(child_module) = modules.get(&child.name) else {
            bail!("contained child module `{}` was not found", child.name);
        };
        let implementation = child_module
            .path
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .join("implementation.yaml");
        if implementation.exists() {
            run_verify_implementation_captured(&implementation).with_context(|| {
                format!(
                    "contained child `{}` failed implementation verification",
                    child.name
                )
            })?;
            verified_children += 1;
        }
    }

    Ok(format!(
        "composite verification passed: {module_name}; verified {verified_children} child implementation(s)"
    ))
}

fn exit_status_label(status: std::process::ExitStatus) -> String {
    status
        .code()
        .map(|code| code.to_string())
        .unwrap_or_else(|| "signal".to_string())
}

fn command_output_excerpt(output: &std::process::Output) -> String {
    let mut details = Vec::new();
    let stdout = String::from_utf8_lossy(&output.stdout);
    if !stdout.trim().is_empty() {
        details.push(format!(
            "stdout: {}",
            truncate_for_prompt(stdout.trim(), 1_000).trim()
        ));
    }
    let stderr = String::from_utf8_lossy(&output.stderr);
    if !stderr.trim().is_empty() {
        details.push(format!(
            "stderr: {}",
            truncate_for_prompt(stderr.trim(), 1_000).trim()
        ));
    }
    if details.is_empty() {
        String::new()
    } else {
        format!(" ({})", details.join("; "))
    }
}

fn print_gate_report(report: &GateReport) {
    println!("RMS gate: {}", gate_result_label(report.result));
    println!("RMS impact: {}", impact_result_label(report.impact_result));
    println!("Root: {}", report.root);
    if let Some(diff) = &report.diff {
        println!("Diff: {diff}");
    } else {
        println!("Diff: working tree");
    }
    if let Some(revision) = &report.source_revision {
        println!("Source revision: {revision}");
    }
    print_string_list("Affected modules", &report.affected_modules);

    if report.executable_checks.is_empty() && report.manual_checks.is_empty() {
        println!("No RMS gate checks required.");
        return;
    }

    if !report.executable_checks.is_empty() {
        println!();
        println!("## Executable Checks");
        for check in &report.executable_checks {
            println!(
                "- {}: {}{}",
                gate_check_status_label(check.status),
                check.command,
                check
                    .message
                    .as_ref()
                    .map(|message| format!(" ({message})"))
                    .unwrap_or_default()
            );
        }
    }

    if !report.manual_checks.is_empty() {
        println!();
        print_string_list("Manual obligations", &report.manual_checks);
    }
}

fn gate_result_label(result: GateResult) -> &'static str {
    match result {
        GateResult::Pending => "pending",
        GateResult::Pass => "pass",
        GateResult::Fail => "fail",
    }
}

fn gate_check_status_label(status: GateCheckStatus) -> &'static str {
    match status {
        GateCheckStatus::Pending => "pending",
        GateCheckStatus::Pass => "pass",
        GateCheckStatus::Fail => "fail",
    }
}

#[derive(Clone, Debug)]
struct ChangedPath {
    status: String,
    path: String,
}

#[derive(Clone, Debug)]
struct ImpactModuleMetadata {
    name: String,
    manifest: PathBuf,
    implementation: Option<PathBuf>,
    base: PathBuf,
    source_root: Option<PathBuf>,
    contract_refs: BTreeSet<PathBuf>,
    evidence_refs: BTreeSet<PathBuf>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd, Serialize)]
#[serde(rename_all = "kebab-case")]
enum ImpactResult {
    NoRmsImpact,
    ImplementationOnly,
    EvidenceReview,
    ReviewRequired,
}

#[derive(Clone, Debug, Serialize)]
struct ImpactPath {
    path: String,
    status: String,
    category: ImpactCategory,
    module: Option<String>,
    module_manifest: Option<String>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd, Serialize)]
#[serde(rename_all = "kebab-case")]
enum ImpactCategory {
    SystemManifest,
    ContextMap,
    ModuleManifest,
    Contract,
    ImplementationBinding,
    Source,
    VerificationEvidence,
    Operations,
    Glossary,
    ConformanceReport,
    WorkbenchConfig,
    Other,
}

#[derive(Clone, Debug, Serialize)]
struct ImpactFinding {
    severity: ImpactResult,
    check: String,
    path: Option<String>,
    module: Option<String>,
    message: String,
}

fn read_git_changed_paths(root: &Path, diff: Option<&str>) -> Result<Vec<ChangedPath>> {
    let mut paths = BTreeMap::<String, ChangedPath>::new();

    if let Some(diff) = diff {
        collect_git_name_status(
            root,
            &["diff", "--relative", "--name-status", diff],
            &mut paths,
        )?;
    } else {
        collect_git_name_status(root, &["diff", "--relative", "--name-status"], &mut paths)?;
        collect_git_name_status(
            root,
            &["diff", "--relative", "--cached", "--name-status"],
            &mut paths,
        )?;
        collect_git_untracked_paths(root, &mut paths)?;
    }

    Ok(paths.into_values().collect())
}

fn collect_git_name_status(
    root: &Path,
    args: &[&str],
    paths: &mut BTreeMap<String, ChangedPath>,
) -> Result<()> {
    let output = Command::new("git")
        .current_dir(root)
        .args(args)
        .output()
        .with_context(|| "failed to start git while reading changed paths")?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        if stderr.contains("Not a git repository") || stderr.contains("not a git repository") {
            bail!(
                "git repository required to read changed paths; run `git init` or run deterministic checks directly (`rms validate --root {}`, `rms compose --root {}`, and `rms verify <implementation.yaml|composite-module.yaml>`)",
                root.display(),
                root.display()
            );
        }
        bail!(
            "git changed-path query failed with status {}{}",
            output
                .status
                .code()
                .map(|code| code.to_string())
                .unwrap_or_else(|| "signal".to_string()),
            if stderr.trim().is_empty() {
                String::new()
            } else {
                format!(": {}", stderr.trim())
            }
        );
    }

    for line in String::from_utf8_lossy(&output.stdout).lines() {
        let fields = line.split('\t').collect::<Vec<_>>();
        if fields.len() < 2 {
            continue;
        }
        let status = fields[0];
        let path = if status.starts_with('R') || status.starts_with('C') {
            fields.last().copied().unwrap_or(fields[1])
        } else {
            fields[1]
        };
        insert_changed_path(root, paths, status, path);
    }

    Ok(())
}

fn collect_git_untracked_paths(
    root: &Path,
    paths: &mut BTreeMap<String, ChangedPath>,
) -> Result<()> {
    let output = Command::new("git")
        .current_dir(root)
        .args([
            "ls-files",
            "--others",
            "--exclude-standard",
            "-z",
            "--",
            ".",
        ])
        .output()
        .with_context(|| "failed to start git while reading untracked paths")?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        bail!(
            "git untracked-path query failed with status {}{}",
            output
                .status
                .code()
                .map(|code| code.to_string())
                .unwrap_or_else(|| "signal".to_string()),
            if stderr.trim().is_empty() {
                String::new()
            } else {
                format!(": {}", stderr.trim())
            }
        );
    }

    for path in String::from_utf8_lossy(&output.stdout)
        .split('\0')
        .filter(|path| !path.is_empty())
    {
        insert_changed_path(root, paths, "??", path);
    }

    Ok(())
}

fn insert_changed_path(
    root: &Path,
    paths: &mut BTreeMap<String, ChangedPath>,
    status: &str,
    path: &str,
) {
    let path = display_path(&root_relative_path(root, Path::new(path)));
    paths
        .entry(path.clone())
        .and_modify(|existing| {
            if !existing.status.split('/').any(|item| item == status) {
                existing.status.push('/');
                existing.status.push_str(status);
            }
        })
        .or_insert_with(|| ChangedPath {
            status: status.to_string(),
            path,
        });
}

fn build_impact_report(
    root: &Path,
    diff: Option<&str>,
    changed_paths: &[ChangedPath],
) -> Result<ImpactReport> {
    let modules = discover_impact_modules(root)?;
    Ok(build_impact_report_from_modules(
        root,
        diff,
        changed_paths,
        &modules,
    ))
}

fn build_impact_report_from_modules(
    root: &Path,
    diff: Option<&str>,
    changed_paths: &[ChangedPath],
    modules: &[ImpactModuleMetadata],
) -> ImpactReport {
    let mut report_paths = Vec::new();
    let mut findings = Vec::new();
    let mut module_paths = BTreeMap::<String, BTreeSet<String>>::new();
    let mut module_categories = BTreeMap::<String, BTreeSet<ImpactCategory>>::new();
    let mut overall = ImpactResult::NoRmsImpact;

    for changed_path in changed_paths {
        let normalized_path = normalize_relative_path(Path::new(&changed_path.path));
        let (category, module) = classify_impact_path(&normalized_path, modules);
        let module_name = module.map(|module| module.name.clone());
        let module_manifest = module.map(|module| display_path(&module.manifest));
        let severity = impact_for_category(category, module.is_some());
        overall = overall.max(severity);

        let path_display = display_path(&normalized_path);
        if let Some(module_name) = &module_name {
            module_paths
                .entry(module_name.clone())
                .or_default()
                .insert(path_display.clone());
            module_categories
                .entry(module_name.clone())
                .or_default()
                .insert(category);
        }

        if severity != ImpactResult::NoRmsImpact {
            findings.push(impact_finding(
                severity,
                impact_check_for_category(category),
                Some(path_display.clone()),
                module_name.clone(),
                impact_message_for_category(category),
            ));
        }

        report_paths.push(ImpactPath {
            path: path_display,
            status: changed_path.status.clone(),
            category,
            module: module_name,
            module_manifest,
        });
    }

    let affected_modules = modules
        .iter()
        .filter_map(|module| {
            let changed_paths = module_paths.remove(&module.name)?;
            let categories = module_categories
                .remove(&module.name)
                .unwrap_or_default()
                .into_iter()
                .collect();
            Some(ImpactModuleImpact {
                name: module.name.clone(),
                manifest: display_path(&module.manifest),
                implementation: module
                    .implementation
                    .as_ref()
                    .map(|path| display_path(path)),
                changed_paths: changed_paths.into_iter().collect(),
                categories,
            })
        })
        .collect::<Vec<_>>();

    let recommended_checks =
        impact_recommended_checks(root, diff, &report_paths, &affected_modules);

    ImpactReport {
        result: overall,
        root: root.display().to_string(),
        diff: diff.map(ToString::to_string),
        source_revision: source_revision(root),
        changed_paths: report_paths,
        affected_modules,
        findings,
        recommended_checks,
    }
}

fn discover_impact_modules(root: &Path) -> Result<Vec<ImpactModuleMetadata>> {
    let targets = discover_targets(root, vec![], vec![], vec![], vec![], vec![], vec![])?;
    let mut module_manifests = Vec::new();
    let mut implementation_manifests = Vec::new();

    for target in targets {
        let manifest = load_manifest(&target)?;
        match get_str(&manifest.value, &["spec"]) {
            Some("rms/module/v0.1") => module_manifests.push(manifest),
            Some("rms/implementation/v0.1") => implementation_manifests.push(manifest),
            _ => {}
        }
    }

    let mut modules = Vec::new();
    for manifest in module_manifests {
        let name = get_str(&manifest.value, &["module", "name"])
            .unwrap_or("<unknown>")
            .to_string();
        let manifest_path = root_relative_path(root, &manifest.path);
        let base = manifest_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_default();
        let implementation = implementation_manifests.iter().find(|implementation| {
            get_str(&implementation.value, &["module"]) == Some(name.as_str())
                && root_relative_path(root, &implementation.path)
                    .parent()
                    .is_some_and(|implementation_base| implementation_base == base)
        });
        let implementation_path =
            implementation.map(|implementation| root_relative_path(root, &implementation.path));
        let source_root = implementation.and_then(|implementation| {
            get_str(&implementation.value, &["source", "root"])
                .map(|source_root| normalize_relative_path(base.join(source_root)))
        });

        let mut contract_refs = BTreeSet::new();
        let mut evidence_refs = BTreeSet::new();
        for reference in referenced_paths(&manifest.value) {
            let path = normalize_relative_path(base.join(&reference));
            if path_has_component(&path, "verification") {
                evidence_refs.insert(path);
            } else if path_has_component(&path, "contracts") {
                contract_refs.insert(path);
            }
        }

        modules.push(ImpactModuleMetadata {
            name,
            manifest: manifest_path,
            implementation: implementation_path,
            base,
            source_root,
            contract_refs,
            evidence_refs,
        });
    }

    modules.sort_by(|left, right| {
        component_count(&right.base)
            .cmp(&component_count(&left.base))
            .then_with(|| left.name.cmp(&right.name))
    });
    Ok(modules)
}

fn classify_impact_path<'a>(
    path: &Path,
    modules: &'a [ImpactModuleMetadata],
) -> (ImpactCategory, Option<&'a ImpactModuleMetadata>) {
    for module in modules {
        if path == module.manifest {
            return (ImpactCategory::ModuleManifest, Some(module));
        }
        if module
            .implementation
            .as_ref()
            .is_some_and(|implementation| path == implementation)
        {
            return (ImpactCategory::ImplementationBinding, Some(module));
        }
        let Some(remainder) = path_under_base(path, &module.base) else {
            continue;
        };
        if first_component_is(remainder, "verification") {
            return (ImpactCategory::VerificationEvidence, Some(module));
        }
        if path_matches_any_reference(path, &module.evidence_refs) {
            return (ImpactCategory::VerificationEvidence, Some(module));
        }
        if path_matches_any_reference(path, &module.contract_refs) {
            return (ImpactCategory::Contract, Some(module));
        }
        if first_component_is(remainder, "contracts") {
            return (ImpactCategory::Contract, Some(module));
        }
        if first_component_is(remainder, "ops") {
            return (ImpactCategory::Operations, Some(module));
        }
        if is_system_manifest_path(remainder) {
            return (ImpactCategory::SystemManifest, Some(module));
        }
        if is_context_map_path(remainder) {
            return (ImpactCategory::ContextMap, Some(module));
        }
        if is_glossary_path(remainder) {
            return (ImpactCategory::Glossary, Some(module));
        }
        if is_conformance_report_path(remainder) {
            return (ImpactCategory::ConformanceReport, Some(module));
        }
        if is_workbench_config_path(remainder) {
            return (ImpactCategory::WorkbenchConfig, Some(module));
        }
        if module
            .source_root
            .as_ref()
            .is_some_and(|source_root| path_under_base(path, source_root).is_some())
        {
            return (ImpactCategory::Source, Some(module));
        }
        if !remainder.as_os_str().is_empty() {
            return (ImpactCategory::Other, Some(module));
        }
    }

    if is_system_manifest_path(path) {
        (ImpactCategory::SystemManifest, None)
    } else if is_context_map_path(path) {
        (ImpactCategory::ContextMap, None)
    } else if is_glossary_path(path) {
        (ImpactCategory::Glossary, None)
    } else if is_conformance_report_path(path) {
        (ImpactCategory::ConformanceReport, None)
    } else if is_workbench_config_path(path) {
        (ImpactCategory::WorkbenchConfig, None)
    } else {
        (ImpactCategory::Other, None)
    }
}

fn path_under_base<'a>(path: &'a Path, base: &Path) -> Option<&'a Path> {
    if base.as_os_str().is_empty() {
        Some(path)
    } else {
        path.strip_prefix(base).ok()
    }
}

fn path_matches_any_reference(path: &Path, references: &BTreeSet<PathBuf>) -> bool {
    references
        .iter()
        .any(|reference| path == reference || path_under_base(path, reference).is_some())
}

fn impact_for_category(category: ImpactCategory, has_module: bool) -> ImpactResult {
    match category {
        ImpactCategory::SystemManifest
        | ImpactCategory::ContextMap
        | ImpactCategory::ModuleManifest
        | ImpactCategory::Contract
        | ImpactCategory::ImplementationBinding
        | ImpactCategory::Operations
        | ImpactCategory::Glossary => ImpactResult::ReviewRequired,
        ImpactCategory::VerificationEvidence | ImpactCategory::ConformanceReport => {
            ImpactResult::EvidenceReview
        }
        ImpactCategory::Source => ImpactResult::ImplementationOnly,
        ImpactCategory::Other if has_module => ImpactResult::ImplementationOnly,
        ImpactCategory::WorkbenchConfig | ImpactCategory::Other => ImpactResult::NoRmsImpact,
    }
}

fn impact_check_for_category(category: ImpactCategory) -> &'static str {
    match category {
        ImpactCategory::SystemManifest => "system.changed",
        ImpactCategory::ContextMap => "context-map.changed",
        ImpactCategory::ModuleManifest => "module-manifest.changed",
        ImpactCategory::Contract => "contract.changed",
        ImpactCategory::ImplementationBinding => "implementation-binding.changed",
        ImpactCategory::Source => "source.changed",
        ImpactCategory::VerificationEvidence => "verification-evidence.changed",
        ImpactCategory::Operations => "operations.changed",
        ImpactCategory::Glossary => "glossary.changed",
        ImpactCategory::ConformanceReport => "conformance-report.changed",
        ImpactCategory::WorkbenchConfig => "workbench-config.changed",
        ImpactCategory::Other => "path.changed",
    }
}

fn impact_message_for_category(category: ImpactCategory) -> &'static str {
    match category {
        ImpactCategory::SystemManifest => {
            "system-level artifact changed; validate composition and compatibility assumptions"
        }
        ImpactCategory::ContextMap => {
            "context relationship artifact changed; review module composition boundaries"
        }
        ImpactCategory::ModuleManifest => {
            "module manifest changed; review public surface, effects, dependencies, and compatibility"
        }
        ImpactCategory::Contract => {
            "public contract path changed; classify compatibility before accepting the diff"
        }
        ImpactCategory::ImplementationBinding => {
            "implementation binding changed; review build, verification, dependencies, and source boundary declarations"
        }
        ImpactCategory::Source => {
            "implementation source changed; run declared verification for the affected module"
        }
        ImpactCategory::VerificationEvidence => {
            "verification evidence changed; confirm it still proves the declared promise"
        }
        ImpactCategory::Operations => {
            "operational artifact changed; review recovery, reconciliation, observability, and runtime checks"
        }
        ImpactCategory::Glossary => {
            "domain language changed; review affected contracts and module terminology"
        }
        ImpactCategory::ConformanceReport => {
            "conformance evidence changed; confirm it is tied to the intended source revision"
        }
        ImpactCategory::WorkbenchConfig => {
            "workbench configuration changed; treat as operational input, not module semantics"
        }
        ImpactCategory::Other => "path changed near an RMS module but has no specialized category",
    }
}

fn impact_finding(
    severity: ImpactResult,
    check: impl Into<String>,
    path: Option<String>,
    module: Option<String>,
    message: impl Into<String>,
) -> ImpactFinding {
    ImpactFinding {
        severity,
        check: check.into(),
        path,
        module,
        message: message.into(),
    }
}

fn impact_recommended_checks(
    root: &Path,
    diff: Option<&str>,
    paths: &[ImpactPath],
    modules: &[ImpactModuleImpact],
) -> Vec<String> {
    let mut checks = BTreeSet::new();
    if paths.is_empty() {
        return Vec::new();
    }
    checks.insert(format!("rms validate --root {}", root.display()));

    if paths.iter().any(|path| {
        matches!(
            path.category,
            ImpactCategory::SystemManifest
                | ImpactCategory::ContextMap
                | ImpactCategory::ModuleManifest
                | ImpactCategory::Contract
                | ImpactCategory::Operations
                | ImpactCategory::Glossary
        )
    }) {
        checks.insert(format!("rms compose --root {}", root.display()));
    }

    for module in modules {
        let diff_arg = diff
            .map(|diff| format!(" --diff {diff}"))
            .unwrap_or_default();
        checks.insert(format!("rms review {}{}", module.manifest, diff_arg));

        if module.categories.iter().any(|category| {
            matches!(
                category,
                ImpactCategory::Source
                    | ImpactCategory::ImplementationBinding
                    | ImpactCategory::VerificationEvidence
            )
        }) {
            if let Some(target) = module_verification_target(root, module) {
                checks.insert(format!("rms verify {target}"));
            }
        }

        if module.categories.iter().any(|category| {
            matches!(
                category,
                ImpactCategory::ModuleManifest | ImpactCategory::Contract
            )
        }) {
            checks.insert(format!(
                "rms check-compat <previous {}> {}",
                module.manifest, module.manifest
            ));
        }
    }

    checks.into_iter().collect()
}

fn print_impact_report(report: &ImpactReport) {
    println!("RMS impact: {}", impact_result_label(report.result));
    println!("Root: {}", report.root);
    if let Some(diff) = &report.diff {
        println!("Diff: {diff}");
    } else {
        println!("Diff: working tree");
    }
    if let Some(revision) = &report.source_revision {
        println!("Source revision: {revision}");
    }
    print_string_list(
        "Affected modules",
        &report
            .affected_modules
            .iter()
            .map(|module| module.name.clone())
            .collect::<Vec<_>>(),
    );

    if report.changed_paths.is_empty() {
        println!("No changed paths detected.");
        return;
    }

    println!();
    println!("## Changed Paths");
    for path in &report.changed_paths {
        println!(
            "- {} [{}] {}{}",
            path.status,
            impact_category_label(path.category),
            path.path,
            path.module
                .as_ref()
                .map(|module| format!(" ({module})"))
                .unwrap_or_default()
        );
    }

    if !report.findings.is_empty() {
        println!();
        println!("## Findings");
        for finding in &report.findings {
            let path = finding.path.as_deref().unwrap_or("<none>");
            let module = finding.module.as_deref().unwrap_or("<none>");
            println!(
                "- {} [{}] path={} module={}: {}",
                impact_result_label(finding.severity),
                finding.check,
                path,
                module,
                finding.message
            );
        }
    }

    if !report.recommended_checks.is_empty() {
        println!();
        print_string_list("Recommended checks", &report.recommended_checks);
    }
}

fn impact_result_label(result: ImpactResult) -> &'static str {
    match result {
        ImpactResult::NoRmsImpact => "no-rms-impact",
        ImpactResult::ImplementationOnly => "implementation-only",
        ImpactResult::EvidenceReview => "evidence-review",
        ImpactResult::ReviewRequired => "review-required",
    }
}

fn impact_category_label(category: ImpactCategory) -> &'static str {
    match category {
        ImpactCategory::SystemManifest => "system-manifest",
        ImpactCategory::ContextMap => "context-map",
        ImpactCategory::ModuleManifest => "module-manifest",
        ImpactCategory::Contract => "contract",
        ImpactCategory::ImplementationBinding => "implementation-binding",
        ImpactCategory::Source => "source",
        ImpactCategory::VerificationEvidence => "verification-evidence",
        ImpactCategory::Operations => "operations",
        ImpactCategory::Glossary => "glossary",
        ImpactCategory::ConformanceReport => "conformance-report",
        ImpactCategory::WorkbenchConfig => "workbench-config",
        ImpactCategory::Other => "other",
    }
}

fn root_relative_path(root: &Path, path: &Path) -> PathBuf {
    let path = normalize_relative_path(path);
    let root = normalize_relative_path(root);
    if !root.as_os_str().is_empty() {
        if let Ok(stripped) = path.strip_prefix(&root) {
            return normalize_relative_path(stripped);
        }
    }
    path
}

fn normalize_relative_path(path: impl AsRef<Path>) -> PathBuf {
    let mut normalized = PathBuf::new();
    for component in path.as_ref().components() {
        match component {
            Component::CurDir => {}
            Component::Normal(part) => normalized.push(part),
            Component::ParentDir => normalized.push(".."),
            Component::RootDir | Component::Prefix(_) => normalized.push(component.as_os_str()),
        }
    }
    normalized
}

fn display_path(path: &Path) -> String {
    if path.as_os_str().is_empty() {
        ".".to_string()
    } else {
        path.display().to_string()
    }
}

fn component_count(path: &Path) -> usize {
    path.components().count()
}

fn first_component_is(path: &Path, expected: &str) -> bool {
    path.components()
        .next()
        .is_some_and(|component| matches!(component, Component::Normal(part) if part == expected))
}

fn file_name_is(path: &Path, expected: &str) -> bool {
    path.file_name()
        .and_then(|name| name.to_str())
        .is_some_and(|name| name == expected)
}

fn is_system_manifest_path(path: &Path) -> bool {
    file_name_is(path, "system.yaml")
}

fn is_context_map_path(path: &Path) -> bool {
    file_name_is(path, "context-map.yaml")
}

fn is_glossary_path(path: &Path) -> bool {
    file_name_is(path, "GLOSSARY.md")
}

fn is_conformance_report_path(path: &Path) -> bool {
    file_name_is(path, "conformance-report.json")
}

fn is_workbench_config_path(path: &Path) -> bool {
    path.components()
        .collect::<Vec<_>>()
        .windows(2)
        .any(|window| {
            matches!(
                window,
                [Component::Normal(parent), Component::Normal(file)]
                    if *parent == ".rms" && *file == "config.yaml"
            )
        })
}

fn discover_targets(
    root: &Path,
    modules: Vec<PathBuf>,
    systems: Vec<PathBuf>,
    context_maps: Vec<PathBuf>,
    contracts: Vec<PathBuf>,
    implementations: Vec<PathBuf>,
    conformance_reports: Vec<PathBuf>,
) -> Result<Vec<PathBuf>> {
    let mut explicit = Vec::new();
    explicit.extend(modules);
    explicit.extend(systems);
    explicit.extend(context_maps);
    explicit.extend(contracts);
    explicit.extend(implementations);
    explicit.extend(conformance_reports);

    if !explicit.is_empty() {
        return Ok(explicit);
    }

    let mut found = BTreeSet::new();
    for entry in WalkDir::new(root)
        .follow_links(false)
        .into_iter()
        .filter_map(Result::ok)
        .filter(|entry| entry.file_type().is_file())
    {
        let path = entry.path();
        let Some(file_name) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        if file_name == "conformance-report.json" || is_supported_yaml_manifest(path) {
            found.insert(path.to_path_buf());
        }
    }

    Ok(found.into_iter().collect())
}

fn is_supported_yaml_manifest(path: &Path) -> bool {
    if path.extension().and_then(|ext| ext.to_str()) != Some("yaml") {
        return false;
    }
    let Ok(source) = fs::read_to_string(path) else {
        return false;
    };
    source.lines().take(5).any(|line| {
        matches!(
            line.trim(),
            "spec: rms/system/v0.1"
                | "spec: rms/module/v0.1"
                | "spec: rms/contract/v0.1"
                | "spec: rms/context-map/v0.1"
                | "spec: rms/implementation/v0.1"
        )
    })
}

fn validate_loaded_manifest(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let spec = get_str(&manifest.value, &["spec"]);
    validate_against_embedded_schema(manifest, diagnostics);

    match spec {
        Some("rms/system/v0.1") => validate_system(manifest, diagnostics),
        Some("rms/module/v0.1") => {
            validate_module(manifest, diagnostics);
            validate_module_shape_consistency(manifest, diagnostics);
        }
        Some("rms/contract/v0.1") => validate_contract(manifest, diagnostics),
        Some("rms/context-map/v0.1") => validate_context_map(manifest, diagnostics),
        Some("rms/implementation/v0.1") => validate_implementation(manifest, diagnostics),
        Some("rms/conformance/v0.1") => {}
        Some(other) => diagnostics.push(error(
            "manifest.spec",
            &manifest.path,
            format!("unsupported spec identifier `{other}`"),
        )),
        None => diagnostics.push(error(
            "manifest.spec",
            &manifest.path,
            "missing required `spec` field",
        )),
    }

    scan_for_secret_like_keys(&manifest.value, &manifest.path, diagnostics);
}

fn validate_module_shape_consistency(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    for advisory in shape_consistency_advisories(manifest) {
        diagnostics.push(warning(
            "module.shape-consistency",
            &manifest.path,
            advisory,
        ));
    }
}

fn validate_against_embedded_schema(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let Some(spec) = get_str(&manifest.value, &["spec"]) else {
        return;
    };
    let Some(schema_source) = schema_for_spec(spec) else {
        return;
    };

    let schema: JsonValue = match serde_json::from_str(schema_source) {
        Ok(schema) => schema,
        Err(error) => {
            diagnostics.push(error_diagnostic(
                "schema.internal.parse",
                &manifest.path,
                format!("embedded schema for `{spec}` could not be parsed: {error}"),
            ));
            return;
        }
    };

    let instance = match serde_json::to_value(&manifest.value) {
        Ok(instance) => instance,
        Err(error) => {
            diagnostics.push(error_diagnostic(
                "schema.instance.convert",
                &manifest.path,
                format!("manifest could not be converted to JSON for schema validation: {error}"),
            ));
            return;
        }
    };

    let validator = match jsonschema::validator_for(&schema) {
        Ok(validator) => validator,
        Err(error) => {
            diagnostics.push(error_diagnostic(
                "schema.internal.compile",
                &manifest.path,
                format!("embedded schema for `{spec}` could not be compiled: {error}"),
            ));
            return;
        }
    };

    for validation_error in validator.iter_errors(&instance) {
        diagnostics.push(error_diagnostic(
            "schema.validate",
            &manifest.path,
            format!(
                "{} at `{}`",
                validation_error,
                validation_error.instance_path()
            ),
        ));
    }
}

fn schema_for_spec(spec: &str) -> Option<&'static str> {
    match spec {
        "rms/system/v0.1" => Some(include_str!("../../../../schemas/system.schema.json")),
        "rms/module/v0.1" => Some(include_str!("../../../../schemas/module.schema.json")),
        "rms/contract/v0.1" => Some(include_str!("../../../../schemas/contract.schema.json")),
        "rms/context-map/v0.1" => Some(include_str!("../../../../schemas/context-map.schema.json")),
        "rms/implementation/v0.1" => Some(include_str!(
            "../../../../schemas/implementation.schema.json"
        )),
        "rms/conformance/v0.1" => Some(include_str!("../../../../schemas/conformance.schema.json")),
        _ => None,
    }
}

fn validate_system(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    require_str(manifest, diagnostics, "system.name", &["system", "name"]);
    require_str(
        manifest,
        diagnostics,
        "system.version",
        &["system", "version"],
    );
    require_str(
        manifest,
        diagnostics,
        "system.purpose",
        &["system", "purpose"],
    );
    require_array(manifest, diagnostics, "contexts", &["contexts"]);
    require_array(
        manifest,
        diagnostics,
        "public_interfaces",
        &["public_interfaces"],
    );
    require_array(manifest, diagnostics, "invariants", &["invariants"]);
    require_str(
        manifest,
        diagnostics,
        "compatibility.policy",
        &["compatibility", "policy"],
    );

    check_contract_refs(manifest, diagnostics, &["public_interfaces"]);
    check_optional_path(manifest, diagnostics, &["glossary"]);
    check_optional_path(manifest, diagnostics, &["context_map"]);
}

fn validate_module(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    require_str(manifest, diagnostics, "module.name", &["module", "name"]);
    require_str(
        manifest,
        diagnostics,
        "module.version",
        &["module", "version"],
    );
    require_str(manifest, diagnostics, "module.kind", &["module", "kind"]);
    require_str(
        manifest,
        diagnostics,
        "module.purpose",
        &["module", "purpose"],
    );

    for required in [
        "profiles",
        "owns",
        "provides",
        "requires",
        "invariants",
        "effects",
        "compatibility",
        "verification",
    ] {
        if get_path(&manifest.value, &[required]).is_none() {
            diagnostics.push(error(
                format!("module.required.{required}"),
                &manifest.path,
                format!("missing required `{required}` section"),
            ));
        }
    }

    let profiles = get_string_array(&manifest.value, &["profiles"]);
    if !profiles.iter().any(|profile| profile == "core") {
        diagnostics.push(error(
            "profiles.core",
            &manifest.path,
            "`profiles` must include `core`",
        ));
    }
    for profile in &profiles {
        if !matches!(
            profile.as_str(),
            "core" | "stateful" | "distributed" | "workflow" | "boundary" | "monitor"
        ) {
            diagnostics.push(error(
                "profiles.allowed",
                &manifest.path,
                format!("unknown profile `{profile}`"),
            ));
        }
    }

    require_str(
        manifest,
        diagnostics,
        "compatibility.policy",
        &["compatibility", "policy"],
    );
    require_verification_categories(manifest, diagnostics);
    check_contract_refs(manifest, diagnostics, &["provides"]);
    check_contract_refs(manifest, diagnostics, &["requires"]);
    check_invariant_evidence(manifest, diagnostics);
    check_verification_paths(manifest, diagnostics);
    check_change_protocols(manifest, diagnostics);
    check_composition_local_shape(manifest, diagnostics);
    check_profile_obligations(manifest, diagnostics, &profiles);
}

fn check_composition_local_shape(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let Some(composition) = get_path(&manifest.value, &["composition"]) else {
        return;
    };

    if let Some(children) = get_path(composition, &["contains"]).and_then(YamlValue::as_sequence) {
        let mut names = BTreeSet::new();
        for child in children {
            let Some(name) = get_str(child, &["name"]) else {
                continue;
            };
            if !names.insert(name.to_string()) {
                diagnostics.push(error(
                    "composition.contains.unique",
                    &manifest.path,
                    format!("duplicate contained module `{name}`"),
                ));
            }
            if let Some(visibility) = get_str(child, &["visibility"]) {
                if !matches!(visibility, "internal" | "public") {
                    diagnostics.push(error(
                        "composition.contains.visibility",
                        &manifest.path,
                        format!("contained module `{name}` has invalid visibility `{visibility}`"),
                    ));
                }
            }
            if let Some(path) = get_str(child, &["path"]) {
                check_relative_ref(
                    manifest,
                    diagnostics,
                    "references.composition.contains.path",
                    path,
                    "referenced contained module manifest does not exist",
                );
            }
        }
    }

    if let Some(exports) = get_path(composition, &["exports"]).and_then(YamlValue::as_sequence) {
        let mut exported = BTreeSet::new();
        for export in exports {
            let Some(name) = get_str(export, &["name"]) else {
                continue;
            };
            let Some(group) = get_str(export, &["group"]) else {
                continue;
            };
            if !matches!(group, "commands" | "queries" | "events" | "capabilities") {
                diagnostics.push(error(
                    "composition.exports.group",
                    &manifest.path,
                    format!("export `{name}` has invalid group `{group}`"),
                ));
                continue;
            }
            if !exported.insert((group.to_string(), name.to_string())) {
                diagnostics.push(error(
                    "composition.exports.unique",
                    &manifest.path,
                    format!("duplicate composition export `{group}.{name}`"),
                ));
            }
        }
    }
}

fn validate_contract(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    require_str(manifest, diagnostics, "contract.name", &["name"]);
    require_str(manifest, diagnostics, "contract.kind", &["kind"]);
    require_str(manifest, diagnostics, "contract.meaning", &["meaning"]);

    for field in ["preconditions", "postconditions"] {
        validate_contract_assumptions(manifest, diagnostics, field);
    }
    validate_contract_named_statements(manifest, diagnostics, "failure_categories");
}

fn validate_contract_assumptions(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    field: &str,
) {
    let Some(items) = get_path(&manifest.value, &[field]).and_then(YamlValue::as_sequence) else {
        return;
    };

    let mut ids = BTreeSet::new();
    for item in items {
        let Some(id) = get_str(item, &["id"]) else {
            continue;
        };
        if !ids.insert(id.to_string()) {
            diagnostics.push(error(
                format!("contract.{field}.duplicate-id"),
                &manifest.path,
                format!("duplicate `{field}` id `{id}`"),
            ));
        }
        if let Some(path) = get_str(item, &["verified_by"]) {
            check_relative_ref(
                manifest,
                diagnostics,
                format!("references.contract.{field}.verified-by"),
                path,
                "referenced contract assumption evidence does not exist",
            );
        }
    }
}

fn validate_contract_named_statements(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    field: &str,
) {
    let Some(items) = get_path(&manifest.value, &[field]).and_then(YamlValue::as_sequence) else {
        return;
    };

    let mut ids = BTreeSet::new();
    for item in items {
        let Some(id) = get_str(item, &["id"]) else {
            continue;
        };
        if !ids.insert(id.to_string()) {
            diagnostics.push(error(
                format!("contract.{field}.duplicate-id"),
                &manifest.path,
                format!("duplicate `{field}` id `{id}`"),
            ));
        }
    }
}

fn validate_context_map(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    if get_path(&manifest.value, &["contexts"]).is_none()
        && get_path(&manifest.value, &["relationships"]).is_none()
    {
        diagnostics.push(error(
            "context-map.content",
            &manifest.path,
            "context map should declare `contexts`, `relationships`, or both",
        ));
    }
    check_contract_refs(manifest, diagnostics, &["relationships"]);
}

fn validate_implementation(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    require_str(manifest, diagnostics, "module", &["module"]);
    require_str(manifest, diagnostics, "binding", &["binding"]);
    require_str(manifest, diagnostics, "source.root", &["source", "root"]);
    require_str(
        manifest,
        diagnostics,
        "source.public_entrypoint",
        &["source", "public_entrypoint"],
    );
    require_str(
        manifest,
        diagnostics,
        "commands.build",
        &["commands", "build"],
    );
    require_str(
        manifest,
        diagnostics,
        "commands.verify",
        &["commands", "verify"],
    );

    check_optional_path(manifest, diagnostics, &["source", "root"]);
    check_optional_path(manifest, diagnostics, &["source", "public_entrypoint"]);
    validate_semantic_function_declarations(manifest, diagnostics);
    validate_inner_structure(manifest, diagnostics);

    match get_str(&manifest.value, &["binding"]) {
        Some("rust") => validate_rust_implementation(manifest, diagnostics),
        Some("swift") => validate_swift_implementation(manifest, diagnostics),
        Some("js") => validate_js_implementation(manifest, diagnostics),
        Some("executable") => validate_executable_implementation(manifest, diagnostics),
        _ => {}
    }
}

fn validate_semantic_function_declarations(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let Some(functions) = semantic_function_items(implementation) else {
        return;
    };

    let base = implementation
        .path
        .parent()
        .unwrap_or_else(|| Path::new("."));
    let module_manifest = load_binding_module_manifest(implementation, base);
    let invariant_ids = module_manifest
        .as_ref()
        .map(module_invariant_ids)
        .unwrap_or_default();
    let mut ids = BTreeSet::new();

    for function in functions {
        if let Some(id) = get_str(function, &["id"]) {
            if !ids.insert(id.to_string()) {
                diagnostics.push(error(
                    "implementation.semantic-functions.duplicate-id",
                    &implementation.path,
                    format!("duplicate semantic function id `{id}`"),
                ));
            }
        }

        for contract in get_string_array(function, &["discharges", "contracts"]) {
            check_relative_ref(
                implementation,
                diagnostics,
                "references.semantic-functions.contract",
                &contract,
                "semantic function references a contract that does not exist",
            );
        }

        for invariant in get_string_array(function, &["discharges", "invariants"]) {
            if module_manifest.is_some() && !invariant_ids.contains(&invariant) {
                diagnostics.push(error(
                    "implementation.semantic-functions.invariant",
                    &implementation.path,
                    format!(
                        "semantic function references undeclared module invariant `{invariant}`"
                    ),
                ));
            }
        }

        for category in verification_reference_categories() {
            for path in get_string_array(function, &["evidence", category]) {
                check_relative_ref(
                    implementation,
                    diagnostics,
                    format!("references.semantic-functions.evidence.{category}"),
                    &path,
                    "semantic function references evidence that does not exist",
                );
                check_evidence_quality(implementation, diagnostics, &path);
            }
        }
    }
}

fn validate_inner_structure(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    if get_str(&manifest.value, &["architecture", "static_inspection"]) == Some("opaque")
        || get_str(&manifest.value, &["binding"]) == Some("executable")
    {
        return;
    }

    let Some(shape) = get_str(&manifest.value, &["architecture", "shape"]) else {
        push_unique_warning(
            diagnostics,
            "structure.semantic-shape-missing",
            &manifest.path,
            "implementation should declare `architecture.shape` before structure checks can be precise",
        );
        return;
    };

    if machine_expected_for_shape(shape)
        && get_str(&manifest.value, &["architecture", "machine", "name"]).is_none()
    {
        push_unique_warning(
            diagnostics,
            "structure.machine-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare `architecture.machine.name`"),
        );
    }
    if let Some(machine_name) = get_str(&manifest.value, &["architecture", "machine", "name"]) {
        warn_on_role_suffix_machine_name(manifest, diagnostics, shape, machine_name);
    }

    if transition_expected_for_shape(shape)
        && get_str(
            &manifest.value,
            &["architecture", "machine", "transition_function"],
        )
        .is_none()
    {
        push_unique_warning(
            diagnostics,
            "structure.transition-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare a transition function"),
        );
    }

    if representation_expected_for_shape(shape)
        && structure_role_paths(manifest, "representation").is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.representation-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare a representation role"),
        );
    }

    if transition_expected_for_shape(shape)
        && structure_role_paths(manifest, "transition").is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.transition-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare a transition role"),
        );
    }

    if parser_expected_for_shape(shape) && structure_role_paths(manifest, "parser").is_empty() {
        push_unique_warning(
            diagnostics,
            "structure.boundary-parser-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare a boundary parser role"),
        );
    }

    validate_traceable_machine_structure(manifest, diagnostics, shape);
    validate_machine_gate_structure(manifest, diagnostics, shape);
    validate_structure_role_paths(manifest, diagnostics);
    inspect_projection_role_sources(manifest, diagnostics);

    if shape == "domain-engine" {
        inspect_domain_transition_sources(manifest, diagnostics);
    }
    inspect_numeric_safety_sources(manifest, diagnostics, shape);
    inspect_cross_module_private_import_sources(manifest, diagnostics);
}

fn validate_machine_gate_structure(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    shape: &str,
) {
    let mode = get_str(&manifest.value, &["architecture", "machine", "mode"]);
    if machine_expected_for_shape(shape) && mode.is_none() {
        push_unique_warning(
            diagnostics,
            "structure.machine-mode-missing",
            &manifest.path,
            "implemented modules should declare `architecture.machine.mode` so Ready-only stateless decisions are distinguishable from lifecycle state machines",
        );
    }
    if let Some(mode) = mode {
        let states = get_string_array(&manifest.value, &["architecture", "machine", "states"]);
        if is_stateful_machine_mode(mode) && !states.iter().any(|state| !is_ready_like_state(state))
        {
            push_unique_warning(
                diagnostics,
                "structure.lifecycle-without-state",
                &manifest.path,
                format!("`{mode}` declares lifecycle behavior but has no meaningful non-Ready state variants"),
            );
        }
        if mode == "stateless-decision-machine"
            && get_str(
                &manifest.value,
                &["architecture", "machine", "stateless_justification"],
            )
            .is_none()
        {
            push_unique_warning(
                diagnostics,
                "structure.fake-machine-ready-only",
                &manifest.path,
                "stateless machine declarations should justify why Ready -> Ready is the complete lifecycle",
            );
        }
    }

    inspect_scaffold_trace_sources(manifest, diagnostics);
    inspect_parser_role_drift(manifest, diagnostics);
    inspect_pure_role_effect_markers(manifest, diagnostics);
    inspect_effect_executor_coverage(manifest, diagnostics);
    inspect_effect_result_handling(manifest, diagnostics);
    inspect_semantic_role_source_residue(manifest, diagnostics);
    inspect_public_command_representation(manifest, diagnostics);
    inspect_runnable_surface_declarations(manifest, diagnostics);
    inspect_runnable_surface_boundary_use(manifest, diagnostics);
}

fn validate_traceable_machine_structure(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    shape: &str,
) {
    if !traceable_structure_expected_for_shape(shape) {
        return;
    }

    let mut envelope_declarations = vec![
        (
            "command_envelope",
            get_structure_values(
                &manifest.value,
                &["architecture", "messages", "command_envelope"],
            ),
        ),
        (
            "event_envelope",
            get_structure_values(
                &manifest.value,
                &["architecture", "messages", "event_envelope"],
            ),
        ),
    ];
    let effects = get_string_array(&manifest.value, &["architecture", "machine", "effects"]);
    if !effects.is_empty() || represented_effect_envelope_types(manifest) {
        envelope_declarations.push((
            "effect_envelope",
            get_structure_values(
                &manifest.value,
                &["architecture", "messages", "effect_envelope"],
            ),
        ));
    }
    let effect_results = get_string_array(
        &manifest.value,
        &["architecture", "machine", "effect_results"],
    );
    if !effect_results.is_empty() || represented_effect_result_envelope_types(manifest) {
        envelope_declarations.push((
            "effect_result_envelope",
            get_structure_values(
                &manifest.value,
                &["architecture", "messages", "effect_result_envelope"],
            ),
        ));
    }
    let missing_envelopes = envelope_declarations
        .into_iter()
        .filter_map(|(name, values)| if values.is_empty() { Some(name) } else { None })
        .collect::<Vec<_>>();
    if !missing_envelopes.is_empty() {
        push_unique_warning(
            diagnostics,
            "structure.message-envelope-missing",
            &manifest.path,
            format!(
                "`{shape}` implementations should declare message envelope fields for {}",
                missing_envelopes.join(", ")
            ),
        );
    }

    if transition_output_expected_for_shape(shape)
        && get_structure_values(&manifest.value, &["architecture", "transition", "output"])
            .is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.transition-output-missing",
            &manifest.path,
            format!(
                "`{shape}` implementations should declare transition output fields such as next_state, events, commands, effects, and reply"
            ),
        );
    }

    let effect_lifecycle_required = effect_lifecycle_expected_for_shape(shape)
        && (shape != "boundary-adapter" || !effects.is_empty());
    if effect_lifecycle_required
        && get_structure_values(&manifest.value, &["architecture", "effects", "lifecycle"])
            .is_empty()
        && structure_role_paths(manifest, "effect_lifecycle").is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.effect-lifecycle-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare an effect lifecycle"),
        );
    }

    if journal_expected_for_shape(shape)
        && get_structure_scalar(&manifest.value, &["architecture", "trace", "journal"]).is_none()
        && structure_role_paths(manifest, "journal").is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.journal-role-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare a transition journal role"),
        );
    }

    if timeline_projection_expected_for_shape(shape)
        && get_structure_scalar(
            &manifest.value,
            &["architecture", "trace", "timeline_projection"],
        )
        .is_none()
        && structure_role_paths(manifest, "timeline_projection").is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.timeline-projection-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare a timeline projection role"),
        );
    }

    if replay_bundle_expected_for_shape(shape)
        && get_structure_scalar(&manifest.value, &["architecture", "trace", "replay_bundle"])
            .is_none()
        && structure_role_paths(manifest, "replay_bundle").is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.replay-bundle-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare replay bundle support"),
        );
    }

    if first_bad_transition_expected_for_shape(shape)
        && get_structure_scalar(
            &manifest.value,
            &["architecture", "trace", "first_bad_transition"],
        )
        .is_none()
    {
        push_unique_warning(
            diagnostics,
            "structure.first-bad-transition-unsupported",
            &manifest.path,
            format!(
                "`{shape}` implementations should declare whether trace evidence supports first-bad-transition debugging"
            ),
        );
    }

    if subscription_registry_expected_for_shape(shape)
        && structure_role_paths(manifest, "subscription_registry").is_empty()
        && get_structure_values(
            &manifest.value,
            &["architecture", "messages", "subscriptions"],
        )
        .is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.subscription-registry-missing",
            &manifest.path,
            "`workflow` implementations should declare an explicit subscription registry",
        );
    }

    if idempotency_expected_for_shape(shape)
        && get_structure_values(
            &manifest.value,
            &["architecture", "effects", "idempotency_keys"],
        )
        .is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.idempotency-missing",
            &manifest.path,
            format!("`{shape}` implementations should declare idempotency key strategy"),
        );
    }
}

