fn structure_role_paths(manifest: &LoadedManifest, role: &str) -> Vec<String> {
    let mut paths = Vec::new();
    for role in structure_role_aliases(role) {
        for path in get_path(&manifest.value, &["architecture", "roles", role])
            .map(yaml_string_values)
            .unwrap_or_default()
        {
            if !paths.contains(&path) {
                paths.push(path);
            }
        }
    }
    paths
}

fn structure_role_aliases(role: &str) -> Vec<&str> {
    match role {
        "parser" => vec!["parser", "boundary_parser", "boundary-parser", "parsers"],
        "effect_executor" => vec!["effect_executor", "effect-executor", "effect_executors"],
        _ => vec![role],
    }
}

fn get_structure_values(value: &YamlValue, path: &[&str]) -> Vec<String> {
    let Some(value) = get_path(value, path) else {
        return Vec::new();
    };
    if let Some(value) = value.as_str() {
        return vec![value.to_string()];
    }
    if let Some(items) = value.as_sequence() {
        return items
            .iter()
            .filter_map(YamlValue::as_str)
            .map(ToString::to_string)
            .collect();
    }
    if let Some(mapping) = value.as_mapping() {
        return mapping
            .keys()
            .filter_map(YamlValue::as_str)
            .map(ToString::to_string)
            .collect();
    }
    Vec::new()
}

fn get_structure_scalar(value: &YamlValue, path: &[&str]) -> Option<String> {
    let value = get_path(value, path)?;
    if let Some(value) = value.as_str() {
        return Some(value.to_string());
    }
    if let Some(value) = value.as_bool() {
        return Some(value.to_string());
    }
    if let Some(value) = value.as_i64() {
        return Some(value.to_string());
    }
    if let Some(items) = value.as_sequence() {
        if items.is_empty() {
            return None;
        }
        return Some(format!("{} item(s)", items.len()));
    }
    if let Some(mapping) = value.as_mapping() {
        if mapping.is_empty() {
            return None;
        }
        return Some(format!("{} field(s)", mapping.len()));
    }
    None
}

fn validate_structure_role_paths(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let Some(roles) =
        get_path(&manifest.value, &["architecture", "roles"]).and_then(YamlValue::as_mapping)
    else {
        return;
    };
    for (role, value) in roles {
        let role = role.as_str().unwrap_or("<unknown>");
        for path in yaml_string_values(value) {
            check_relative_ref(
                manifest,
                diagnostics,
                format!("references.structure.role.{role}"),
                &path,
                "structure role references an artifact that does not exist",
            );
            if is_evidence_role(role) {
                check_evidence_quality(manifest, diagnostics, &path);
            }
        }
    }
}

fn is_evidence_role(role: &str) -> bool {
    let lower = role.to_ascii_lowercase();
    lower.contains("evidence") || lower.contains("trace")
}

fn inspect_projection_role_sources(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    inspect_role_sources_for_markers(
        manifest,
        diagnostics,
        &["timeline_projection", "projection"],
        "structure.projection-emits-command",
        "projection role appears to emit commands; projections should observe and build read models only",
        &["emit_command", "emitCommand", "commands.push", "issuedCommands"],
    );
    inspect_role_sources_for_markers(
        manifest,
        diagnostics,
        &["subscription_registry"],
        "structure.hidden-choreography",
        "subscription registry appears to issue commands directly; route meaningful workflow progress through an explicit workflow transition",
        &["emit_command", "emitCommand", "commands.push", "runEffect"],
    );
}

fn inspect_scaffold_trace_sources(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let mut references = Vec::new();
    for role in ["replay_bundle", "trace_evidence"] {
        for reference in structure_role_paths(manifest, role) {
            if !references.contains(&reference) {
                references.push(reference);
            }
        }
    }
    if let Some(reference) =
        get_structure_scalar(&manifest.value, &["architecture", "trace", "replay_bundle"])
    {
        if reference.ends_with(".yaml") || reference.ends_with(".json") {
            references.push(reference);
        }
    }
    references.sort();
    references.dedup();
    for reference in references {
        let path = base.join(&reference);
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        if [
            "TraceableScaffoldMachine",
            "BoundaryScaffoldMachine",
            "DomainScaffoldMachine",
        ]
        .iter()
        .any(|name| source.contains(name))
        {
            push_unique_warning(
                diagnostics,
                "structure.scaffold-trace-active",
                &manifest.path,
                format!("trace role `{reference}` still contains generated scaffold machine names"),
            );
        }
    }
}

fn inspect_parser_role_drift(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let parser_paths = structure_role_paths(manifest, "parser")
        .into_iter()
        .collect::<BTreeSet<_>>();
    if parser_paths.is_empty() {
        return;
    }
    let Some(functions) = semantic_function_items(manifest) else {
        return;
    };
    for function in functions {
        if get_str(function, &["kind"]) != Some("parser") {
            continue;
        }
        let Some(symbol) = get_str(function, &["symbol"]) else {
            continue;
        };
        let Some(path) = symbol.split('#').next() else {
            continue;
        };
        if !symbol_source_path_like(path) {
            continue;
        }
        if !path.is_empty() && !parser_paths.contains(path) {
            push_unique_warning(
                diagnostics,
                "structure.role-file-drift",
                &manifest.path,
                format!(
                    "parser semantic function `{symbol}` is not declared in architecture.roles.parser"
                ),
            );
        }
    }
}

fn inspect_public_command_representation(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let Some(module_manifest) = load_binding_module_manifest(manifest, base) else {
        return;
    };
    let public_commands = module_provided_command_names(&module_manifest.value);
    if public_commands.is_empty() {
        return;
    }

    let mut candidates =
        get_string_array(&manifest.value, &["architecture", "machine", "commands"]);
    candidates.extend(module_verification_references(&module_manifest.value));
    candidates.extend(get_string_array(
        &manifest.value,
        &["architecture", "representation", "closed_variants"],
    ));
    candidates.extend(get_string_array(
        &manifest.value,
        &["architecture", "representation", "transition_functions"],
    ));
    candidates.extend(semantic_function_symbols(manifest));
    let declared_source = read_declared_semantic_surface_sources(manifest, false);
    if !declared_source.trim().is_empty() {
        candidates.push(declared_source.clone());
    }

    let missing = public_commands
        .iter()
        .filter(|command| {
            !candidates
                .iter()
                .any(|candidate| semantic_name_is_represented_by(candidate, command))
        })
        .cloned()
        .collect::<Vec<_>>();
    if missing.is_empty() {
        return;
    }

    push_unique_warning(
        diagnostics,
        "structure.public-command-not-represented",
        &manifest.path,
        format!(
            "module publishes command(s) {}, but the declared machine, semantic functions, and declared role sources do not represent them; apply a semantic change or route the product command through the declared boundary/domain surface",
            missing.join(", ")
        ),
    );

    if source_contains_generic_accept_reject_scaffold(&declared_source) {
        push_unique_warning(
            diagnostics,
            "structure.generic-scaffold-command-active",
            &manifest.path,
            "declared role sources still expose generic Accept/Reject scaffold commands while the module publishes product-specific commands",
        );
    }
}

fn module_provided_command_names(module: &YamlValue) -> Vec<String> {
    let mut names = BTreeSet::new();
    if let Some(items) =
        get_path(module, &["provides", "commands"]).and_then(YamlValue::as_sequence)
    {
        for item in items {
            if let Some(name) = item.as_str() {
                names.insert(name.to_string());
            }
            if let Some(name) = get_str(item, &["name"]) {
                names.insert(name.to_string());
            }
            if let Some(command) = get_str(item, &["command"]) {
                names.insert(command.to_string());
            }
        }
    }
    names.into_iter().collect()
}

fn semantic_function_symbols(manifest: &LoadedManifest) -> Vec<String> {
    let Some(functions) = semantic_function_items(manifest) else {
        return Vec::new();
    };
    let mut candidates = Vec::new();
    for function in functions {
        if let Some(id) = get_str(function, &["id"]) {
            candidates.push(id.to_string());
        }
        if let Some(symbol) = get_str(function, &["symbol"]) {
            candidates.push(symbol.to_string());
        }
        for contract in get_string_array(function, &["discharges", "contracts"]) {
            candidates.push(contract);
        }
        for category in verification_reference_categories() {
            for evidence in get_string_array(function, &["evidence", category]) {
                candidates.push(evidence);
            }
        }
    }
    candidates
}

fn semantic_name_is_represented_by(candidate: &str, name: &str) -> bool {
    if candidate.contains(name) || semantic_text_mentions_id(candidate, name) {
        return true;
    }
    let wanted = semantic_token_set(name)
        .into_iter()
        .filter(|token| !is_low_signal_semantic_token(token))
        .collect::<BTreeSet<_>>();
    if wanted.is_empty() {
        return false;
    }
    let candidate_tokens = semantic_token_set(candidate);
    wanted
        .iter()
        .all(|token| candidate_tokens.contains(token.as_str()))
}

fn semantic_token_set(value: &str) -> BTreeSet<String> {
    identifier_word_tokens(value)
        .into_iter()
        .filter(|token| !token.is_empty())
        .collect()
}

fn is_low_signal_semantic_token(token: &str) -> bool {
    matches!(
        token,
        "a" | "an"
            | "and"
            | "api"
            | "app"
            | "command"
            | "do"
            | "get"
            | "handle"
            | "run"
            | "the"
            | "to"
    )
}

fn read_declared_semantic_surface_sources(
    manifest: &LoadedManifest,
    include_runnable_roles: bool,
) -> String {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let mut references = declared_semantic_surface_references(manifest, include_runnable_roles);
    references.sort();
    references.dedup();

    let mut source = String::new();
    for reference in references {
        let path = base.join(&reference);
        if path.is_file() {
            if let Ok(contents) = fs::read_to_string(&path) {
                source.push_str(&contents);
                source.push('\n');
            }
        }
    }
    source
}

fn declared_semantic_surface_references(
    manifest: &LoadedManifest,
    include_runnable_roles: bool,
) -> Vec<String> {
    let mut references = Vec::new();
    if let Some(public_entrypoint) = get_str(&manifest.value, &["source", "public_entrypoint"]) {
        references.push(public_entrypoint.to_string());
    }
    for role in [
        "representation",
        "transition",
        "parser",
        "adapter",
        "effect_executor",
        "ports",
        "port",
        "pure_transform",
    ] {
        references.extend(structure_role_paths(manifest, role));
    }
    if include_runnable_roles {
        for role in runnable_surface_role_names() {
            references.extend(structure_role_paths(manifest, role));
        }
    }
    if let Some(functions) = semantic_function_items(manifest) {
        for function in functions {
            if let Some(symbol) = get_str(function, &["symbol"]) {
                if let Some(path) = symbol.split('#').next() {
                    if symbol_source_path_like(path) {
                        references.push(path.to_string());
                    }
                }
            }
        }
    }
    references
}

fn source_contains_generic_accept_reject_scaffold(source: &str) -> bool {
    (source.contains("CommandAccept") || source.contains("Command.Accept"))
        && (source.contains("CommandReject") || source.contains("Command.Reject"))
        && (source.contains("missing-label")
            || source.contains("input?.label")
            || source.contains("InvalidCommand")
            || source.contains("MalformedInput"))
}

fn inspect_runnable_surface_boundary_use(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if get_str(&manifest.value, &["architecture", "shape"]) != Some("boundary-adapter") {
        return;
    }

    let runnable_refs = runnable_surface_references(manifest);
    if runnable_refs.is_empty() {
        return;
    }

    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let boundary_refs = boundary_entrypoint_references(manifest);
    let pure_refs = private_decision_role_references(manifest);
    let declared_semantic_source = read_declared_semantic_surface_sources(manifest, false);
    let declared_surfaces = architecture_surface_declarations(manifest);
    for declaration in &declared_surfaces {
        let mut declaration_boundary_refs = boundary_refs.clone();
        if !declaration_boundary_refs
            .iter()
            .any(|reference| same_semantic_path(reference, &declaration.entrypoint))
        {
            declaration_boundary_refs.push(declaration.entrypoint.clone());
        }
        let Some(launch_entrypoint) = declaration.launch_entrypoint.as_deref() else {
            continue;
        };
        let path = base.join(launch_entrypoint);
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        if !source_mentions_path_or_stem(&source, &declaration.entrypoint) {
            push_unique_warning(
                diagnostics,
                "structure.runnable-surface-not-wired",
                &manifest.path,
                format!(
                    "runnable launch surface `{launch_entrypoint}` does not reference declared entrypoint `{}`",
                    declaration.entrypoint
                ),
            );
        }
        if pure_refs
            .iter()
            .any(|private_role| source_mentions_path_or_stem(&source, private_role))
        {
            push_unique_warning(
                diagnostics,
                "structure.runnable-surface-private-domain-access",
                &manifest.path,
                format!(
                    "runnable launch surface `{launch_entrypoint}` imports or references private decision roles instead of the declared entrypoint"
                ),
            );
        }
        for launch_asset in
            runnable_launch_asset_references(declaration, launch_entrypoint, &source)
        {
            if launch_asset == declaration.entrypoint {
                continue;
            }
            let asset_path = base.join(&launch_asset);
            let Ok(asset_source) = fs::read_to_string(&asset_path) else {
                push_unique_warning(
                    diagnostics,
                    "structure.runnable-surface-not-wired",
                    &manifest.path,
                    format!(
                        "runnable launch asset `{launch_asset}` referenced by `{launch_entrypoint}` could not be inspected"
                    ),
                );
                continue;
            };
            inspect_runnable_surface_source(
                manifest,
                diagnostics,
                &launch_asset,
                &asset_source,
                &declaration_boundary_refs,
                &pure_refs,
                &declared_semantic_source,
                "runnable launch asset",
            );
        }
    }
    for reference in runnable_refs {
        let path = base.join(&reference);
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        inspect_runnable_surface_source(
            manifest,
            diagnostics,
            &reference,
            &source,
            &boundary_refs,
            &pure_refs,
            &declared_semantic_source,
            "runnable surface",
        );
    }
}

fn inspect_runnable_surface_source(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    reference: &str,
    source: &str,
    boundary_refs: &[String],
    pure_refs: &[String],
    declared_semantic_source: &str,
    label: &str,
) {
    if boundary_refs
        .iter()
        .any(|boundary| same_semantic_path(boundary, &reference))
    {
        return;
    }
    let uses_boundary = boundary_refs
        .iter()
        .any(|boundary| source_mentions_path_or_stem(&source, boundary))
        || source.contains("handleBoundaryInput")
        || source.contains("handleBoundaryTransition");
    let imports_private_decision_role = pure_refs
        .iter()
        .any(|private_role| source_mentions_path_or_stem(&source, private_role));
    if !uses_boundary {
        push_unique_warning(
                diagnostics,
                "structure.runnable-surface-not-wired",
                &manifest.path,
                format!("{label} `{reference}` does not reference the declared boundary adapter, parser, transition, or public entrypoint"),
            );
    }
    if imports_private_decision_role {
        push_unique_warning(
                diagnostics,
                "structure.runnable-surface-private-domain-access",
                &manifest.path,
                format!("{label} `{reference}` imports or references private decision roles instead of a declared boundary entrypoint"),
            );
    }
    let duplicates_domain_logic =
        runnable_surface_looks_like_domain_logic(&source, &declared_semantic_source)
            && !uses_boundary;
    if imports_private_decision_role && !uses_boundary {
        push_unique_warning(
                diagnostics,
                "structure.runnable-surface-bypasses-boundary",
                &manifest.path,
                format!("{label} `{reference}` imports declared pure/private role code without going through the declared boundary adapter or public entrypoint"),
            );
    }
    if duplicates_domain_logic {
        push_unique_warning(
                diagnostics,
                "structure.runnable-surface-domain-logic-duplication",
                &manifest.path,
                format!("{label} `{reference}` appears to define core decision logic while disconnected from the declared boundary"),
            );
        push_unique_warning(
                diagnostics,
                "structure.runnable-surface-bypasses-boundary",
                &manifest.path,
                format!("{label} `{reference}` appears to reimplement domain decisions instead of routing through the declared boundary adapter or public entrypoint"),
            );
    }
}

fn inspect_runnable_surface_declarations(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if get_str(&manifest.value, &["architecture", "shape"]) != Some("boundary-adapter") {
        return;
    }
    let declarations = architecture_surface_declarations(manifest);
    if declarations.is_empty() && module_mentions_runnable_surface_intent(manifest) {
        push_unique_warning(
            diagnostics,
            "structure.runnable-surface-missing",
            &manifest.path,
            "boundary implementation appears to own a runnable app/tool/UI surface but does not declare `architecture.surfaces`",
        );
    }
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    for declaration in declarations {
        if declaration.evidence.is_empty()
            || !declaration
                .evidence
                .iter()
                .any(|path| concrete_evidence_path_exists(&base.join(path)))
        {
            push_unique_warning(
                diagnostics,
                "structure.runnable-surface-evidence-missing",
                &manifest.path,
                format!(
                    "runnable surface `{}` should reference concrete evidence proving delegation through the boundary",
                    declaration.name
                ),
            );
        }
    }
}

fn architecture_surface_declarations(manifest: &LoadedManifest) -> Vec<SurfaceDeclaration> {
    let Some(items) =
        get_path(&manifest.value, &["architecture", "surfaces"]).and_then(YamlValue::as_sequence)
    else {
        return Vec::new();
    };
    items
        .iter()
        .filter_map(|item| serde_yaml::from_value(item.clone()).ok())
        .collect()
}

fn declaration_launch_scripts(declaration: &SurfaceDeclaration) -> Vec<String> {
    let mut scripts = declaration.launch_scripts.clone();
    if let Some(script) = declaration.launch_script.as_deref() {
        if !script.trim().is_empty() {
            scripts.push(script.to_string());
        }
    }
    scripts.sort();
    scripts.dedup();
    scripts
}

fn runnable_launch_asset_references(
    declaration: &SurfaceDeclaration,
    launch_entrypoint: &str,
    launch_source: &str,
) -> Vec<String> {
    let mut references = declaration_launch_scripts(declaration);
    if declaration.surface == "browser" || launch_entrypoint.ends_with(".html") {
        for source in html_script_src_references(launch_source) {
            if let Some(reference) = resolve_launch_asset_reference(launch_entrypoint, &source) {
                references.push(reference);
            }
        }
    }
    references.sort();
    references.dedup();
    references
}

fn html_script_src_references(source: &str) -> Vec<String> {
    let mut references = Vec::new();
    let lower = source.to_ascii_lowercase();
    let bytes = source.as_bytes();
    let mut search_from = 0;
    while let Some(relative_start) = lower[search_from..].find("<script") {
        let start = search_from + relative_start;
        let Some(relative_end) = lower[start..].find('>') else {
            break;
        };
        let end = start + relative_end;
        let tag = &source[start..end];
        if let Some(src) = html_attribute_value(tag, "src") {
            references.push(src);
        }
        search_from = end.saturating_add(1).min(bytes.len());
    }
    references
}

fn html_attribute_value(tag: &str, attribute: &str) -> Option<String> {
    let lower = tag.to_ascii_lowercase();
    let mut search_from = 0;
    let needle = attribute.to_ascii_lowercase();
    while let Some(relative_start) = lower[search_from..].find(&needle) {
        let start = search_from + relative_start;
        let before = lower[..start].chars().next_back();
        let after = lower[start + needle.len()..].chars().next();
        let boundary_before = before.is_none_or(|ch| ch.is_ascii_whitespace() || ch == '<');
        let boundary_after = after.is_none_or(|ch| ch.is_ascii_whitespace() || ch == '=');
        if !boundary_before || !boundary_after {
            search_from = start + needle.len();
            continue;
        }
        let mut rest = tag[start + needle.len()..].trim_start();
        if !rest.starts_with('=') {
            search_from = start + needle.len();
            continue;
        }
        rest = rest[1..].trim_start();
        let Some(first) = rest.chars().next() else {
            return None;
        };
        if first == '"' || first == '\'' {
            let value_start = first.len_utf8();
            let value_rest = &rest[value_start..];
            let end = value_rest.find(first)?;
            return Some(value_rest[..end].to_string());
        }
        let value = rest
            .split_whitespace()
            .next()
            .unwrap_or("")
            .trim_end_matches('/')
            .to_string();
        if !value.is_empty() {
            return Some(value);
        }
        search_from = start + needle.len();
    }
    None
}

fn resolve_launch_asset_reference(launch_entrypoint: &str, reference: &str) -> Option<String> {
    let trimmed = reference.trim();
    if trimmed.is_empty() || is_external_launch_asset_reference(trimmed) {
        return None;
    }
    let path_part = trimmed.split(['?', '#']).next().unwrap_or(trimmed).trim();
    if path_part.is_empty() || !is_safe_relative_artifact_path(path_part) {
        return None;
    }
    let launch_path = Path::new(launch_entrypoint);
    let base = launch_path.parent().unwrap_or_else(|| Path::new(""));
    let resolved = normalize_relative_path(base.join(path_part));
    let rendered = path_to_manifest_reference(&resolved);
    if is_safe_relative_artifact_path(&rendered) {
        Some(rendered)
    } else {
        None
    }
}

fn is_external_launch_asset_reference(reference: &str) -> bool {
    let lower = reference.to_ascii_lowercase();
    lower.starts_with("http://")
        || lower.starts_with("https://")
        || lower.starts_with("//")
        || lower.starts_with("data:")
        || lower.starts_with("blob:")
        || lower.starts_with("javascript:")
        || lower.starts_with('#')
}

fn path_to_manifest_reference(path: &Path) -> String {
    path.components()
        .filter_map(|component| match component {
            Component::Normal(part) => part.to_str().map(ToString::to_string),
            Component::CurDir => None,
            Component::ParentDir => Some("..".to_string()),
            Component::RootDir | Component::Prefix(_) => None,
        })
        .collect::<Vec<_>>()
        .join("/")
}

fn module_mentions_runnable_surface_intent(manifest: &LoadedManifest) -> bool {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let Some(module) = load_binding_module_manifest(manifest, base) else {
        return false;
    };
    let mut text = String::new();
    if let Some(purpose) = get_str(&module.value, &["module", "purpose"]) {
        text.push_str(purpose);
        text.push('\n');
    }
    for concept in get_string_array(&module.value, &["owns", "concepts"]) {
        text.push_str(&concept);
        text.push('\n');
    }
    semantic_name_contains_any(
        &text,
        &[
            "app",
            "tool",
            "ui",
            "cli",
            "browser",
            "web",
            "mobile",
            "desktop",
            "runnable",
            "local-first",
            "smoke",
        ],
    )
}

fn runnable_surface_looks_like_domain_logic(source: &str, declared_semantic_source: &str) -> bool {
    let runnable_functions = source_function_names(source);
    if runnable_functions.is_empty() {
        return false;
    }
    let declared_functions = source_function_names(declared_semantic_source);
    if runnable_functions.iter().any(|name| {
        declared_functions.contains(name) && semantic_function_name_is_decision_like(name)
    }) {
        return true;
    }
    runnable_functions
        .iter()
        .filter(|name| semantic_function_name_is_decision_like(name))
        .count()
        >= 2
}

fn source_function_names(source: &str) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for line in source.lines() {
        let trimmed = line.trim_start();
        for marker in ["function ", "export function "] {
            if let Some(rest) = trimmed.strip_prefix(marker) {
                let name = rest
                    .chars()
                    .take_while(|character| {
                        character.is_ascii_alphanumeric() || *character == '_' || *character == '$'
                    })
                    .collect::<String>();
                if !name.is_empty() {
                    names.insert(name);
                }
            }
        }
        if let Some((left, _right)) = trimmed.split_once("=>") {
            if let Some((_, name)) = left.rsplit_once(" ") {
                let name = name
                    .trim_matches(|character: char| !character.is_ascii_alphanumeric())
                    .to_string();
                if !name.is_empty() {
                    names.insert(name);
                }
            }
        }
    }
    names
}

fn semantic_function_name_is_decision_like(name: &str) -> bool {
    semantic_name_contains_any(
        name,
        &[
            "create",
            "compute",
            "calculate",
            "decide",
            "resolve",
            "evaluate",
            "generate",
            "parse",
            "normalize",
            "validate",
            "transition",
            "apply",
            "mask",
            "alpha",
            "discount",
            "authorize",
            "reserve",
        ],
    )
}

fn runnable_surface_role_names() -> &'static [&'static str] {
    &[
        "browser_adapter",
        "browser-adapter",
        "cli",
        "cli_adapter",
        "cli-adapter",
        "ui",
        "ui_adapter",
        "ui-adapter",
        "web_adapter",
        "web-adapter",
        "app",
        "runnable_surface",
        "runnable-surface",
    ]
}

fn runnable_surface_references(manifest: &LoadedManifest) -> Vec<String> {
    let mut references = Vec::new();
    for declaration in architecture_surface_declarations(manifest) {
        references.push(declaration.entrypoint);
    }
    for role in runnable_surface_role_names() {
        references.extend(structure_role_paths(manifest, role));
    }
    for reference in get_string_array(&manifest.value, &["architecture", "public_modules"]) {
        if looks_like_runnable_surface_path(&reference) {
            references.push(reference);
        }
    }
    references.sort();
    references.dedup();
    references
}

fn looks_like_runnable_surface_path(reference: &str) -> bool {
    let path = reference.replace('\\', "/");
    let file = path
        .rsplit('/')
        .next()
        .unwrap_or(&path)
        .to_ascii_lowercase();
    path.starts_with("public/")
        || path.contains("/public/")
        || file.starts_with("app.")
        || file.starts_with("main.")
        || file.starts_with("cli.")
        || file == "index.js"
        || file == "index.mjs"
}

fn boundary_entrypoint_references(manifest: &LoadedManifest) -> Vec<String> {
    let mut references = Vec::new();
    if let Some(public_entrypoint) = get_str(&manifest.value, &["source", "public_entrypoint"]) {
        references.push(public_entrypoint.to_string());
    }
    for role in ["adapter", "transition"] {
        references.extend(structure_role_paths(manifest, role));
    }
    for declaration in architecture_surface_declarations(manifest) {
        if let Some(symbol) = declaration
            .delegates_to
            .as_ref()
            .and_then(|delegation| delegation.symbol.as_deref())
        {
            references.push(symbol.split('#').next().unwrap_or(symbol).to_string());
        }
        if let Some(role) = declaration
            .delegates_to
            .as_ref()
            .and_then(|delegation| delegation.role.as_deref())
        {
            references.extend(structure_role_paths(manifest, role));
        }
    }
    references.sort();
    references.dedup();
    references
}

fn private_decision_role_references(manifest: &LoadedManifest) -> Vec<String> {
    let mut references = Vec::new();
    for role in ["pure_transform", "domain", "representation", "transition"] {
        references.extend(structure_role_paths(manifest, role));
    }
    let boundary_refs = boundary_entrypoint_references(manifest)
        .into_iter()
        .collect::<BTreeSet<_>>();
    references.retain(|reference| !boundary_refs.contains(reference));
    references.sort();
    references.dedup();
    references
}

fn same_semantic_path(left: &str, right: &str) -> bool {
    left.replace('\\', "/") == right.replace('\\', "/")
}

fn source_mentions_path_or_stem(source: &str, reference: &str) -> bool {
    let normalized_ref = reference.replace('\\', "/");
    if source.contains(&normalized_ref) {
        return true;
    }
    let Some(file_name) = normalized_ref.rsplit('/').next() else {
        return false;
    };
    source.contains(file_name)
        || file_name.split_once('.').is_some_and(|(stem, _)| {
            stem.len() >= 4 && !is_low_signal_semantic_token(stem) && source.contains(stem)
        })
}

fn inspect_pure_role_effect_markers(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let mut pure_references = pure_semantic_function_source_paths(manifest);
    if pure_references.is_empty()
        && get_str(&manifest.value, &["architecture", "shape"]) == Some("domain-engine")
    {
        for role in ["representation", "transition"] {
            for reference in structure_role_paths(manifest, role) {
                pure_references.insert(reference);
            }
        }
    }
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    for reference in pure_references {
        let path = base.join(&reference);
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        if contains_hidden_effect_marker(&source) {
            push_unique_warning(
                diagnostics,
                "structure.effectful-helper-in-pure-role",
                &manifest.path,
                format!(
                    "pure role `{reference}` contains IO, clock, randomness, process, provider, or network effect markers; move the effect behind an adapter, port, or effect_executor role"
                ),
            );
        }
    }
}

fn pure_semantic_function_source_paths(manifest: &LoadedManifest) -> BTreeSet<String> {
    let Some(functions) = semantic_function_items(manifest) else {
        return BTreeSet::new();
    };
    functions
        .iter()
        .filter(|function| get_str(function, &["purity"]) == Some("pure"))
        .filter_map(|function| get_str(function, &["symbol"]))
        .filter_map(|symbol| symbol.split('#').next())
        .filter(|path| symbol_source_path_like(path))
        .map(ToString::to_string)
        .collect()
}

fn symbol_source_path_like(path: &str) -> bool {
    path.contains('/')
        || path.ends_with(".rs")
        || path.ends_with(".mjs")
        || path.ends_with(".js")
        || path.ends_with(".ts")
        || path.ends_with(".swift")
        || path.ends_with(".py")
}

fn inspect_effect_executor_coverage(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let shape = get_str(&manifest.value, &["architecture", "shape"]).unwrap_or("");
    if !effect_lifecycle_expected_for_shape(shape) {
        return;
    }
    let effects = get_string_array(&manifest.value, &["architecture", "machine", "effects"]);
    if effects.is_empty() {
        return;
    }
    if structure_role_paths(manifest, "effect_executor").is_empty()
        && structure_role_paths(manifest, "adapter").is_empty()
        && structure_role_paths(manifest, "ports").is_empty()
        && structure_role_paths(manifest, "port").is_empty()
    {
        push_unique_warning(
            diagnostics,
            "structure.effect-without-executor",
            &manifest.path,
            "declared effects should be executed by a declared effect_executor, adapter, port, or explicit delegation role",
        );
    }
}

fn inspect_effect_result_handling(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let has_machine = get_path(&manifest.value, &["architecture", "machine"])
        .and_then(YamlValue::as_mapping)
        .is_some();
    if !has_machine {
        return;
    }
    let has_reconciliation_evidence = implementation_has_reconciliation_evidence(manifest);
    let effect_results = get_string_array(
        &manifest.value,
        &["architecture", "machine", "effect_results"],
    );
    let effects = get_string_array(&manifest.value, &["architecture", "machine", "effects"]);
    let commands = get_string_array(&manifest.value, &["architecture", "machine", "commands"]);
    let handled = existing_transition_inputs(manifest);
    let unclassified_outcome_inputs = handled
        .iter()
        .filter(|input| {
            effect_result_like_transition_input(input)
                && !effect_results.contains(input)
                && !commands.contains(input)
        })
        .cloned()
        .collect::<Vec<_>>();
    for input in &unclassified_outcome_inputs {
        push_unique_warning(
            diagnostics,
            "structure.transition-input-not-classified",
            &manifest.path,
            format!(
                "transition input `{input}` looks like an effect outcome but is neither a declared command nor a declared effect result"
            ),
        );
    }
    if effect_results.is_empty()
        && !effects.is_empty()
        && (!unclassified_outcome_inputs.is_empty()
            || effect_lifecycle_needs_result_semantics(manifest))
        && !implementation_has_effect_result_exception(manifest)
    {
        let detail = if unclassified_outcome_inputs.is_empty() {
            "effect lifecycle declares retry, recovery, abandoned, or failure states but no effect results"
                .to_string()
        } else {
            format!(
                "transition consumes outcome input(s) {} but `architecture.machine.effect_results` is empty",
                unclassified_outcome_inputs.join(", ")
            )
        };
        push_unique_warning(
            diagnostics,
            "structure.effect-result-change-not-declared",
            &manifest.path,
            detail,
        );
    }
    for effect_result in &effect_results {
        if semantic_name_contains_any(
            effect_result,
            &["unknown", "uncertain", "stale", "partial", "conflict"],
        ) && !has_reconciliation_evidence
        {
            push_unique_warning(
                diagnostics,
                "structure.unknown-effect-result-without-reconciliation",
                &manifest.path,
                format!(
                    "effect result `{effect_result}` represents uncertain external truth without reconciliation evidence"
                ),
            );
        }
    }
    for effect in effects {
        if semantic_name_contains_any(
            &effect,
            &[
                "compensate",
                "compensation",
                "rollback",
                "release",
                "recover",
                "recovery",
            ],
        ) && !has_reconciliation_evidence
        {
            push_unique_warning(
                diagnostics,
                "structure.compensation-without-recovery-evidence",
                &manifest.path,
                format!(
                    "effect `{effect}` appears to compensate or recover external truth without reconciliation evidence"
                ),
            );
        }
    }
    let represented_effect_results = represented_effect_result_types(manifest);
    if effect_results.is_empty() && !represented_effect_results.is_empty() {
        push_unique_warning(
            diagnostics,
            "structure.effect-result-type-not-declared",
            &manifest.path,
            format!(
                "representation declares effect-result type(s) {}, but `architecture.machine.effect_results` is empty",
                represented_effect_results.join(", ")
            ),
        );
    }
    if effect_results.is_empty()
        && (!get_structure_values(
            &manifest.value,
            &["architecture", "messages", "effect_result_envelope"],
        )
        .is_empty()
            || represented_effect_result_envelope_types(manifest))
    {
        push_unique_warning(
            diagnostics,
            "structure.effect-result-envelope-unused",
            &manifest.path,
            "effect-result envelope structure is declared or represented, but no machine effect results are declared",
        );
    }
    if effect_results.is_empty() {
        return;
    }
    let has_declared_transitions =
        get_path(&manifest.value, &["architecture", "machine", "transitions"])
            .and_then(YamlValue::as_sequence)
            .is_some_and(|transitions| !transitions.is_empty());
    if handled.is_empty() {
        if has_declared_transitions {
            push_unique_warning(
                diagnostics,
                "structure.effect-result-declared-not-consumed",
                &manifest.path,
                "machine declares effect results, but no declared transitions consume command or effect-result inputs",
            );
        }
        return;
    }
    if has_declared_transitions && !effect_results.iter().any(|result| handled.contains(result)) {
        push_unique_warning(
            diagnostics,
            "structure.effect-result-declared-not-consumed",
            &manifest.path,
            "machine declares effect results, but declared transitions do not consume any effect-result input",
        );
    }
    for effect_result in effect_results {
        if !handled.contains(&effect_result) {
            push_unique_warning(
                diagnostics,
                "structure.effect-result-unhandled",
                &manifest.path,
                format!("effect result `{effect_result}` is not consumed by a declared transition"),
            );
        }
    }
}

fn effect_result_like_transition_input(input: &str) -> bool {
    semantic_name_contains_any(
        input,
        &[
            "succeeded",
            "success",
            "failed",
            "failure",
            "unknown",
            "uncertain",
            "timeout",
            "timedout",
            "stale",
            "partial",
            "conflict",
            "completed",
            "abandoned",
        ],
    )
}

fn effect_lifecycle_needs_result_semantics(manifest: &LoadedManifest) -> bool {
    let mode = get_str(&manifest.value, &["architecture", "machine", "mode"]).unwrap_or("");
    if !matches!(
        mode,
        "workflow-effect-machine" | "storage-machine" | "integration-machine"
    ) {
        return false;
    }
    let states = get_string_array(&manifest.value, &["architecture", "machine", "states"]);
    states.iter().any(|state| {
        semantic_name_contains_any(
            state,
            &[
                "retry",
                "abandoned",
                "recover",
                "recovery",
                "failed",
                "failure",
                "waitingfor",
                "pending",
            ],
        )
    })
}

fn implementation_has_effect_result_exception(manifest: &LoadedManifest) -> bool {
    [
        &["architecture", "machine", "effect_result_justification"][..],
        &["architecture", "machine", "effect_results_justification"][..],
        &["architecture", "machine", "no_effect_results_justification"][..],
        &["architecture", "effect_results_justification"][..],
        &["x-rms", "effect_results_justification"][..],
        &["x-rms", "no_effect_results_justification"][..],
    ]
    .iter()
    .any(|path| get_str(&manifest.value, path).is_some_and(|text| !text.trim().is_empty()))
}

fn implementation_has_reconciliation_evidence(manifest: &LoadedManifest) -> bool {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    if concrete_evidence_path_exists(&base.join("verification").join("reconciliation")) {
        return true;
    }
    for role in [
        "trace_evidence",
        "journal",
        "timeline_projection",
        "replay_bundle",
        "effect_lifecycle",
    ] {
        for reference in structure_role_paths(manifest, role) {
            let normalized = normalize_semantic_identifier(&reference);
            if semantic_name_contains_any(
                &normalized,
                &["reconciliation", "reconcile", "recovery", "recover"],
            ) {
                return true;
            }
            let path = base.join(&reference);
            if path.is_file()
                && fs::read_to_string(&path).is_ok_and(|source| {
                    let normalized = normalize_semantic_identifier(&source);
                    semantic_name_contains_any(
                        &normalized,
                        &["reconciliation", "reconcile", "recovery", "recover"],
                    )
                })
            {
                return true;
            }
        }
    }
    false
}

fn semantic_name_contains_any(value: &str, needles: &[&str]) -> bool {
    let normalized = normalize_semantic_identifier(value);
    needles
        .iter()
        .any(|needle| semantic_text_mentions_id(&normalized, needle))
}

fn represented_effect_result_types(manifest: &LoadedManifest) -> Vec<String> {
    get_string_array(
        &manifest.value,
        &["architecture", "representation", "closed_variants"],
    )
    .into_iter()
    .filter(|variant| {
        variant.ends_with("EffectResult")
            || variant.ends_with("EffectResults")
            || variant.ends_with("EffectOutcome")
            || variant.ends_with("EffectOutcomes")
    })
    .collect()
}

fn represented_effect_result_envelope_types(manifest: &LoadedManifest) -> bool {
    get_string_array(
        &manifest.value,
        &["architecture", "representation", "closed_variants"],
    )
    .into_iter()
    .any(|variant| variant.ends_with("EffectResultEnvelope"))
}

fn represented_effect_envelope_types(manifest: &LoadedManifest) -> bool {
    get_string_array(
        &manifest.value,
        &["architecture", "representation", "closed_variants"],
    )
    .into_iter()
    .any(|variant| variant.ends_with("EffectEnvelope"))
}

fn inspect_semantic_role_source_residue(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let effects = get_string_array(&manifest.value, &["architecture", "machine", "effects"]);
    let effect_results = get_string_array(
        &manifest.value,
        &["architecture", "machine", "effect_results"],
    );
    if !effects.is_empty() && !effect_results.is_empty() {
        return;
    }

    let source_types = semantic_role_source_types(manifest);
    if source_types.is_empty() {
        return;
    }

    let mut residue_found = false;
    if effects.is_empty() {
        let effect_types = source_types
            .iter()
            .filter(|(name, _)| is_effect_role_type(name))
            .cloned()
            .collect::<Vec<_>>();
        let effect_envelopes = source_types
            .iter()
            .filter(|(name, _)| is_effect_envelope_role_type(name))
            .cloned()
            .collect::<Vec<_>>();
        let effect_lifecycles = source_types
            .iter()
            .filter(|(name, _)| is_effect_lifecycle_role_type(name))
            .cloned()
            .collect::<Vec<_>>();
        if !effect_types.is_empty() {
            residue_found = true;
            push_unique_warning(
                diagnostics,
                "structure.undeclared-effect-type-represented",
                &manifest.path,
                format!(
                    "source exposes effect role type(s) {}, but `architecture.machine.effects` is empty",
                    format_source_type_locations(&effect_types)
                ),
            );
        }
        if !effect_envelopes.is_empty() {
            residue_found = true;
            push_unique_warning(
                diagnostics,
                "structure.effect-envelope-without-effects",
                &manifest.path,
                format!(
                    "source exposes effect envelope type(s) {}, but no machine effects are declared",
                    format_source_type_locations(&effect_envelopes)
                ),
            );
        }
        if !effect_lifecycles.is_empty() {
            residue_found = true;
            push_unique_warning(
                diagnostics,
                "structure.effect-lifecycle-without-effects",
                &manifest.path,
                format!(
                    "source exposes effect lifecycle type(s) {}, but no machine effects are declared",
                    format_source_type_locations(&effect_lifecycles)
                ),
            );
        }
    }

    if effect_results.is_empty() {
        let effect_result_types = source_types
            .iter()
            .filter(|(name, _)| is_effect_result_role_type(name))
            .cloned()
            .collect::<Vec<_>>();
        if !effect_result_types.is_empty() {
            residue_found = true;
            push_unique_warning(
                diagnostics,
                "structure.undeclared-effect-result-type-represented",
                &manifest.path,
                format!(
                    "source exposes effect-result role type(s) {}, but `architecture.machine.effect_results` is empty",
                    format_source_type_locations(&effect_result_types)
                ),
            );
        }
    }

    if residue_found {
        push_unique_warning(
            diagnostics,
            "structure.semantic-role-source-residue",
            &manifest.path,
            "source exposes semantic role types that are absent from canonical implementation declarations",
        );
    }
}

fn semantic_role_source_types(manifest: &LoadedManifest) -> Vec<(String, String)> {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let binding = get_str(&manifest.value, &["binding"]).unwrap_or("");
    let mut references = Vec::new();
    for role in ["representation", "transition", "message_envelope"] {
        for reference in structure_role_paths(manifest, role) {
            if !references.contains(&reference) {
                references.push(reference);
            }
        }
    }
    if references.is_empty() {
        if let Some(public_entrypoint) = get_str(&manifest.value, &["source", "public_entrypoint"])
        {
            references.push(public_entrypoint.to_string());
        }
    }

    let mut types = Vec::new();
    let mut seen = BTreeSet::new();
    for reference in references {
        let path = base.join(&reference);
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        for type_name in declared_source_type_names(&source, binding) {
            if seen.insert((type_name.clone(), reference.clone())) {
                types.push((type_name, reference.clone()));
            }
        }
    }
    types
}

fn declared_source_type_names(source: &str, binding: &str) -> Vec<String> {
    let mut names = Vec::new();
    for line in source.lines() {
        let trimmed = line.trim_start();
        let candidates: &[&str] = match binding {
            "rust" => &["pub enum ", "pub struct ", "pub type "],
            "swift" => &[
                "public enum ",
                "public struct ",
                "public typealias ",
                "public final class ",
                "public class ",
            ],
            "js" => &["export function make", "export const ", "export class "],
            _ => &[],
        };
        for prefix in candidates {
            if let Some(rest) = trimmed.strip_prefix(prefix) {
                if let Some(name) = leading_identifier(rest) {
                    let normalized = if binding == "js" && *prefix == "export function make" {
                        name.to_string()
                    } else {
                        name.to_string()
                    };
                    names.push(normalized);
                }
            }
        }
    }
    names
}

fn leading_identifier(value: &str) -> Option<&str> {
    let end = value
        .char_indices()
        .find_map(|(index, ch)| {
            if ch == '_' || ch.is_ascii_alphanumeric() {
                None
            } else {
                Some(index)
            }
        })
        .unwrap_or(value.len());
    if end == 0 {
        None
    } else {
        Some(&value[..end])
    }
}

fn format_source_type_locations(types: &[(String, String)]) -> String {
    types
        .iter()
        .map(|(name, reference)| format!("{name} in `{reference}`"))
        .collect::<Vec<_>>()
        .join(", ")
}

fn is_effect_role_type(name: &str) -> bool {
    (name.ends_with("Effect") || name.ends_with("Effects"))
        && !is_effect_envelope_role_type(name)
        && !is_effect_lifecycle_role_type(name)
        && !is_effect_result_role_type(name)
}

fn is_effect_envelope_role_type(name: &str) -> bool {
    name.ends_with("EffectEnvelope")
}

fn is_effect_lifecycle_role_type(name: &str) -> bool {
    name.ends_with("EffectLifecycle")
}

fn is_effect_result_role_type(name: &str) -> bool {
    name.ends_with("EffectResult")
        || name.ends_with("EffectResults")
        || name.ends_with("EffectResultEnvelope")
        || name.ends_with("EffectOutcome")
        || name.ends_with("EffectOutcomes")
}

fn inspect_role_sources_for_markers(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    roles: &[&str],
    check: &str,
    message: &str,
    markers: &[&str],
) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    for role in roles {
        for reference in structure_role_paths(manifest, role) {
            let path = base.join(&reference);
            let Ok(source) = fs::read_to_string(&path) else {
                continue;
            };
            if markers.iter().any(|marker| source.contains(marker)) {
                push_unique_warning(
                    diagnostics,
                    check,
                    &manifest.path,
                    format!("{message}: `{reference}`"),
                );
            }
        }
    }
}

fn inspect_domain_transition_sources(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let mut references = structure_role_paths(manifest, "transition");
    if references.is_empty() {
        if let Some(public_entrypoint) = get_str(&manifest.value, &["source", "public_entrypoint"])
        {
            references.push(public_entrypoint.to_string());
        }
    }

    for reference in references {
        let path = base.join(&reference);
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        if contains_hidden_effect_marker(&source) {
            push_unique_warning(
                diagnostics,
                "structure.hidden-effect-in-domain",
                &manifest.path,
                format!(
                    "domain-engine transition role `{reference}` contains time, randomness, IO, process, or network effect markers"
                ),
            );
        }
        if source.contains("throw new Error") || source.contains("throw Error") {
            push_unique_warning(
                diagnostics,
                "structure.expected-failure-throws",
                &manifest.path,
                format!(
                    "domain-engine transition role `{reference}` appears to throw for expected failures; prefer explicit rejection values"
                ),
            );
        }
    }
}

fn inspect_numeric_safety_sources(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    shape: &str,
) {
    let numeric_tokens = numeric_validated_value_tokens(&manifest.value);
    if !numeric_safety_expected_for_shape(shape) || numeric_tokens.is_empty() {
        return;
    }

    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let mut references = Vec::new();
    for role in ["representation", "transition", "parser"] {
        for reference in structure_role_paths(manifest, role) {
            if !references.contains(&reference) {
                references.push(reference);
            }
        }
    }
    if references.is_empty() {
        if let Some(public_entrypoint) = get_str(&manifest.value, &["source", "public_entrypoint"])
        {
            references.push(public_entrypoint.to_string());
        }
    }

    for reference in references {
        let path = base.join(&reference);
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        if let Some(line) = first_unchecked_numeric_arithmetic_line(&source, &numeric_tokens) {
            push_unique_warning(
                diagnostics,
                "structure.unchecked-numeric-arithmetic",
                &manifest.path,
                format!(
                    "`{shape}` role `{reference}` performs arithmetic on a module with numeric validated values near line {line}; use bounded, checked, saturating, or explicitly proven arithmetic"
                ),
            );
        }
    }
}

fn inspect_cross_module_private_import_sources(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let mut references = Vec::new();
    for role in ["adapter", "parser", "transition", "representation"] {
        for reference in structure_role_paths(manifest, role) {
            if !references.contains(&reference) {
                references.push(reference);
            }
        }
    }
    if references.is_empty() {
        if let Some(public_entrypoint) = get_str(&manifest.value, &["source", "public_entrypoint"])
        {
            references.push(public_entrypoint.to_string());
        }
    }

    for reference in references {
        let path = base.join(&reference);
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        if let Some(line) = first_cross_module_private_import_line(&source, &path) {
            push_unique_warning(
                diagnostics,
                "structure.cross-module-private-import",
                &manifest.path,
                format!(
                    "role `{reference}` appears to import another module's private representation or transition internals near line {line}; call declared public entrypoints or contract-shaped commands instead"
                ),
            );
        }
    }
}

fn first_cross_module_private_import_line(source: &str, path: &Path) -> Option<usize> {
    source
        .lines()
        .enumerate()
        .find_map(|(index, line)| cross_module_private_import_line(line, path).then_some(index + 1))
}

fn cross_module_private_import_line(line: &str, path: &Path) -> bool {
    let trimmed = line.trim_start();
    if trimmed.starts_with("//") || trimmed.starts_with('#') || trimmed.is_empty() {
        return false;
    }
    let extension = path
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or("");
    let is_js_like = matches!(extension, "js" | "mjs" | "cjs" | "ts" | "tsx");
    let is_rust_or_swift_like = matches!(extension, "rs" | "swift");
    let code = mask_quoted_segments(line);
    let code_lower = code.to_ascii_lowercase();

    let rust_or_swift_private_role = is_rust_or_swift_like
        && ["::transition::", "::representation::"]
            .iter()
            .any(|marker| code_lower.contains(marker))
        && ![
            "crate::transition",
            "crate::representation",
            "self::transition",
            "self::representation",
            "super::transition",
            "super::representation",
        ]
        .iter()
        .any(|marker| code_lower.contains(marker));
    if rust_or_swift_private_role {
        return true;
    }

    let line_lower = line.to_ascii_lowercase();
    is_js_like
        && (line_lower.contains(" from ")
            || line_lower.trim_start().starts_with("import ")
            || line_lower.contains("require("))
        && line_lower.contains("../")
        && (line_lower.contains("transition.")
            || line_lower.contains("representation.")
            || line_lower.contains("/transition")
            || line_lower.contains("/representation"))
}

fn numeric_safety_expected_for_shape(shape: &str) -> bool {
    matches!(
        shape,
        "domain-engine"
            | "workflow"
            | "storage-adapter"
            | "integration-adapter"
            | "boundary-adapter"
    )
}

fn numeric_validated_value_tokens(value: &YamlValue) -> BTreeSet<String> {
    let mut tokens = BTreeSet::new();
    let mut found_numeric_value = false;
    for value in get_string_array(
        value,
        &["architecture", "representation", "validated_values"],
    )
    .iter()
    {
        if looks_numeric_value_name(value) {
            found_numeric_value = true;
            tokens.extend(identifier_word_tokens(value));
        }
    }
    if found_numeric_value {
        tokens.extend(
            numeric_value_name_tokens()
                .iter()
                .map(|token| token.to_string()),
        );
    }
    tokens
}

fn looks_numeric_value_name(value: &str) -> bool {
    let tokens = identifier_word_tokens(value);
    let numeric_tokens = numeric_value_name_tokens();
    tokens
        .iter()
        .any(|token| numeric_tokens.contains(&token.as_str()))
}

fn numeric_value_name_tokens() -> &'static [&'static str] {
    &[
        "amount", "balance", "capacity", "cent", "cents", "cost", "count", "duration", "fee",
        "limit", "money", "percent", "price", "quantity", "rate", "ratio", "score", "size",
        "subtotal", "total", "unit", "units",
    ]
}

fn first_unchecked_numeric_arithmetic_line(
    source: &str,
    numeric_tokens: &BTreeSet<String>,
) -> Option<usize> {
    source.lines().enumerate().find_map(|(index, line)| {
        unchecked_numeric_arithmetic_line(line, numeric_tokens).then_some(index + 1)
    })
}

fn unchecked_numeric_arithmetic_line(line: &str, numeric_tokens: &BTreeSet<String>) -> bool {
    let trimmed = line.trim_start();
    if trimmed.is_empty()
        || trimmed.starts_with("//")
        || trimmed.starts_with('#')
        || trimmed.starts_with("use ")
        || trimmed.starts_with("pub use ")
    {
        return false;
    }

    let safe_markers = [
        "checked_",
        "saturating_",
        "wrapping_",
        "overflowing_",
        "checkedAdd",
        "checkedSubtract",
        "checkedMultiply",
        "checkedDivide",
        "saturating",
        "BigInt",
        "Number.isSafeInteger",
        "ReportingOverflow",
        "addingReportingOverflow",
        "subtractingReportingOverflow",
        "multipliedReportingOverflow",
        "dividedReportingOverflow",
        "remainderReportingOverflow",
    ];
    if safe_markers.iter().any(|marker| line.contains(marker)) {
        return false;
    }

    let code = mask_quoted_segments(line);
    if !line_mentions_numeric_concept(&code, numeric_tokens) {
        return false;
    }
    let chars = code.chars().collect::<Vec<_>>();
    for (index, character) in chars.iter().enumerate() {
        if is_unchecked_arithmetic_operator(&chars, index, *character) {
            return true;
        }
    }
    false
}

fn line_mentions_numeric_concept(line: &str, numeric_tokens: &BTreeSet<String>) -> bool {
    identifier_word_tokens(line)
        .iter()
        .any(|token| numeric_tokens.contains(token))
}

fn is_unchecked_arithmetic_operator(chars: &[char], index: usize, character: char) -> bool {
    let previous = index.checked_sub(1).and_then(|index| chars.get(index));
    let next = chars.get(index + 1);
    let previous_non_space = previous_non_whitespace(chars, index);

    match character {
        '+' => true,
        '-' => next != Some(&'>') && !looks_like_unary_operator(previous_non_space),
        '*' => previous != Some(&':') && previous != Some(&'('),
        '/' => {
            next != Some(&'/')
                && next != Some(&'*')
                && previous != Some(&'*')
                && previous != Some(&'/')
                && !matches!(
                    previous_non_space,
                    None | Some('=' | '(' | '[' | '{' | ',' | ':' | ';' | '!')
                )
        }
        '%' => previous != Some(&'%') && next != Some(&'%'),
        _ => false,
    }
}

fn previous_non_whitespace(chars: &[char], index: usize) -> Option<char> {
    chars
        .get(..index)?
        .iter()
        .rev()
        .copied()
        .find(|character| !character.is_whitespace())
}

fn looks_like_unary_operator(previous: Option<char>) -> bool {
    matches!(
        previous,
        None | Some(
            '(' | '['
                | '{'
                | '='
                | ':'
                | ','
                | ';'
                | '!'
                | '<'
                | '>'
                | '+'
                | '-'
                | '*'
                | '/'
                | '%'
                | '&'
                | '|'
                | '?'
        )
    )
}

fn mask_quoted_segments(line: &str) -> String {
    let mut output = String::with_capacity(line.len());
    let mut quote: Option<char> = None;
    let mut escaped = false;
    for character in line.chars() {
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
                output.push(' ');
                continue;
            }
            if character == '\\' {
                escaped = true;
                output.push(' ');
                continue;
            }
            if character == active_quote {
                quote = None;
            }
            output.push(' ');
            continue;
        }
        if matches!(character, '"' | '\'' | '`') {
            quote = Some(character);
            output.push(' ');
        } else {
            output.push(character);
        }
    }
    output
}

fn contains_hidden_effect_marker(source: &str) -> bool {
    [
        "Date.now",
        "Math.random",
        "fetch(",
        "readFile",
        "writeFile",
        "node:fs",
        "from \"fs\"",
        "from 'fs'",
        "process.env",
        "std::fs",
        "SystemTime::now",
        "rand::",
    ]
    .iter()
    .any(|marker| source.contains(marker))
}

fn semantic_function_items(manifest: &LoadedManifest) -> Option<&[YamlValue]> {
    get_path(&manifest.value, &["semantic_functions"])?
        .as_sequence()
        .map(Vec::as_slice)
}

fn declared_architecture_symbols(value: &YamlValue) -> Vec<DeclaredArchitectureSymbol> {
    let mut symbols = Vec::new();
    if let Some(symbol) = get_str(value, &["architecture", "machine", "name"]) {
        push_declared_architecture_symbol(
            &mut symbols,
            "machine.name",
            symbol,
            DeclaredSymbolKind::Type,
        );
    }
    if let Some(symbol) = get_str(value, &["architecture", "machine", "state"]) {
        push_declared_architecture_symbol(
            &mut symbols,
            "machine.state",
            symbol,
            DeclaredSymbolKind::Type,
        );
    }
    for (role, path) in [
        (
            "machine.commands",
            &["architecture", "machine", "commands"][..],
        ),
        ("machine.events", &["architecture", "machine", "events"][..]),
        (
            "machine.effects",
            &["architecture", "machine", "effects"][..],
        ),
        (
            "machine.effect_results",
            &["architecture", "machine", "effect_results"][..],
        ),
        (
            "machine.replies",
            &["architecture", "machine", "replies"][..],
        ),
        (
            "machine.rejections",
            &["architecture", "machine", "rejections"][..],
        ),
    ] {
        for symbol in get_string_array(value, path) {
            push_declared_architecture_symbol(
                &mut symbols,
                role,
                &symbol,
                DeclaredSymbolKind::Type,
            );
        }
    }
    if let Some(symbol) = get_str(value, &["architecture", "machine", "transition_function"]) {
        push_declared_architecture_symbol(
            &mut symbols,
            "machine.transition_function",
            symbol,
            DeclaredSymbolKind::Function,
        );
    }
    symbols
}

fn push_declared_architecture_symbol(
    symbols: &mut Vec<DeclaredArchitectureSymbol>,
    role: &'static str,
    symbol: &str,
    kind: DeclaredSymbolKind,
) {
    if is_checkable_identifier(symbol) {
        symbols.push(DeclaredArchitectureSymbol {
            role,
            symbol: symbol.to_string(),
            kind,
        });
    }
}

fn is_checkable_identifier(symbol: &str) -> bool {
    let mut chars = symbol.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    (first.is_ascii_alphabetic() || first == '_')
        && chars.all(|character| character.is_ascii_alphanumeric() || character == '_')
}

fn module_invariant_ids(manifest: &LoadedManifest) -> BTreeSet<String> {
    get_path(&manifest.value, &["invariants"])
        .and_then(YamlValue::as_sequence)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| get_str(item, &["id"]))
                .map(ToString::to_string)
                .collect()
        })
        .unwrap_or_default()
}

fn validate_rust_implementation(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let Some(source_root_ref) = get_str(&manifest.value, &["source", "root"]) else {
        return;
    };
    let Some(public_entrypoint_ref) = get_str(&manifest.value, &["source", "public_entrypoint"])
    else {
        return;
    };

    let source_root = base.join(source_root_ref);
    let public_entrypoint = base.join(public_entrypoint_ref);

    if public_entrypoint.extension().and_then(|ext| ext.to_str()) != Some("rs") {
        diagnostics.push(error(
            "implementation.rust.public-entrypoint",
            &manifest.path,
            "`source.public_entrypoint` must point to a Rust source file",
        ));
    }

    if public_entrypoint.exists()
        && source_root.exists()
        && !public_entrypoint.starts_with(&source_root)
    {
        diagnostics.push(error(
            "implementation.rust.public-entrypoint",
            &manifest.path,
            "`source.public_entrypoint` must be inside `source.root` for Rust bindings",
        ));
    }

    let cargo_manifest = rust_cargo_manifest_path(manifest, base, &source_root);
    if !cargo_manifest.exists() {
        diagnostics.push(error(
            "implementation.rust.cargo-manifest",
            &manifest.path,
            format!(
                "Rust binding requires a Cargo manifest at `{}`",
                display_relative(base, &cargo_manifest)
            ),
        ));
        return;
    }

    let cargo = match load_toml(&cargo_manifest) {
        Ok(cargo) => cargo,
        Err(load_error) => {
            diagnostics.push(error(
                "implementation.rust.cargo-manifest.parse",
                &manifest.path,
                format!(
                    "failed to parse Cargo manifest `{}`: {load_error}",
                    display_relative(base, &cargo_manifest)
                ),
            ));
            return;
        }
    };

    validate_cargo_package_shape(manifest, diagnostics, &cargo_manifest, &cargo);
    validate_declared_rust_package(manifest, diagnostics, &cargo);
    validate_rust_dependency_allowlist(manifest, diagnostics, &cargo);
    validate_rust_public_modules(manifest, diagnostics, &public_entrypoint);
    validate_rust_source_boundaries(manifest, diagnostics, &source_root, &cargo);
    validate_rust_typing(manifest, diagnostics, base, &source_root);
}

fn validate_swift_implementation(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let Some(source_root_ref) = get_str(&manifest.value, &["source", "root"]) else {
        return;
    };
    let Some(public_entrypoint_ref) = get_str(&manifest.value, &["source", "public_entrypoint"])
    else {
        return;
    };

    let source_root = base.join(source_root_ref);
    let public_entrypoint = base.join(public_entrypoint_ref);

    if public_entrypoint.extension().and_then(|ext| ext.to_str()) != Some("swift") {
        diagnostics.push(error(
            "implementation.swift.public-entrypoint",
            &manifest.path,
            "`source.public_entrypoint` must point to a Swift source file",
        ));
    }

    if public_entrypoint.exists()
        && source_root.exists()
        && !public_entrypoint.starts_with(&source_root)
    {
        diagnostics.push(error(
            "implementation.swift.public-entrypoint",
            &manifest.path,
            "`source.public_entrypoint` must be inside `source.root` for Swift bindings",
        ));
    }

    let package_manifest = swift_package_manifest_path(manifest, base);
    if !package_manifest.exists() {
        diagnostics.push(error(
            "implementation.swift.package-manifest",
            &manifest.path,
            format!(
                "Swift binding requires a package manifest at `{}`",
                display_relative(base, &package_manifest)
            ),
        ));
        return;
    }

    let package_source = match fs::read_to_string(&package_manifest) {
        Ok(source) => source,
        Err(read_error) => {
            diagnostics.push(error(
                "implementation.swift.package-manifest.read",
                &manifest.path,
                format!(
                    "failed to read Swift package manifest `{}`: {read_error}",
                    display_relative(base, &package_manifest)
                ),
            ));
            return;
        }
    };

    validate_swift_package_shape(manifest, diagnostics, &package_manifest, &package_source);
    validate_declared_swift_package(manifest, diagnostics, &package_source);
    validate_declared_swift_target(manifest, diagnostics, &source_root);
    validate_swift_source_boundaries(manifest, diagnostics, &source_root);
    validate_swift_typing(manifest, diagnostics, base, &source_root);
}

fn validate_js_implementation(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let Some(source_root_ref) = get_str(&manifest.value, &["source", "root"]) else {
        return;
    };
    let Some(public_entrypoint_ref) = get_str(&manifest.value, &["source", "public_entrypoint"])
    else {
        return;
    };

    let source_root = base.join(source_root_ref);
    let public_entrypoint = base.join(public_entrypoint_ref);

    if !matches!(
        public_entrypoint.extension().and_then(|ext| ext.to_str()),
        Some("js" | "mjs" | "cjs")
    ) {
        diagnostics.push(error(
            "implementation.js.public-entrypoint",
            &manifest.path,
            "`source.public_entrypoint` must point to a JavaScript source file",
        ));
    }

    if public_entrypoint.exists()
        && source_root.exists()
        && !public_entrypoint.starts_with(&source_root)
    {
        diagnostics.push(error(
            "implementation.js.public-entrypoint",
            &manifest.path,
            "`source.public_entrypoint` must be inside `source.root` for JavaScript bindings",
        ));
    }

    if !source_root.exists() {
        return;
    }

    let mut summary = JsSourceSummary::default();
    for path in js_source_files(&source_root) {
        let source = match fs::read_to_string(&path) {
            Ok(source) => source,
            Err(read_error) => {
                diagnostics.push(error(
                    "implementation.js.source.read",
                    &manifest.path,
                    format!(
                        "failed to read JavaScript source `{}`: {read_error}",
                        path.display()
                    ),
                ));
                continue;
            }
        };
        inspect_js_source(&source, &mut summary);
    }

    validate_js_declared_architecture_symbols(manifest, diagnostics, &summary);
    validate_js_semantic_function_symbols(manifest, diagnostics, &summary);
    validate_js_machine_shape(manifest, diagnostics, &source_root);
}

fn validate_executable_implementation(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let Some(source_root_ref) = get_str(&manifest.value, &["source", "root"]) else {
        return;
    };
    let Some(public_entrypoint_ref) = get_str(&manifest.value, &["source", "public_entrypoint"])
    else {
        return;
    };

    let source_root = base.join(source_root_ref);
    let public_entrypoint = base.join(public_entrypoint_ref);

    if public_entrypoint.exists()
        && source_root.exists()
        && !public_entrypoint.starts_with(&source_root)
    {
        diagnostics.push(error(
            "implementation.executable.public-entrypoint",
            &manifest.path,
            "`source.public_entrypoint` must be inside `source.root` for executable bindings",
        ));
    }

    if get_str(&manifest.value, &["toolchain", "runner"]).is_none() {
        diagnostics.push(warning(
            "implementation.executable.runner.declared",
            &manifest.path,
            "executable bindings should declare `toolchain.runner` to name the command environment",
        ));
    }
}

fn swift_package_manifest_path(manifest: &LoadedManifest, base: &Path) -> PathBuf {
    if let Some(path) = get_str(&manifest.value, &["toolchain", "package_manifest"]) {
        base.join(path)
    } else {
        base.join("Package.swift")
    }
}

fn validate_swift_package_shape(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    package_manifest: &Path,
    package_source: &str,
) {
    if !package_source.contains("import PackageDescription") || !package_source.contains("Package(")
    {
        diagnostics.push(error(
            "implementation.swift.package-manifest.shape",
            &manifest.path,
            format!(
                "Swift package manifest `{}` must import PackageDescription and declare `Package(...)`",
                package_manifest.display()
            ),
        ));
    }

    if parse_swift_package_name(package_source).is_none() {
        diagnostics.push(error(
            "implementation.swift.package.name",
            &manifest.path,
            "Swift package bindings must declare a package `name`",
        ));
    }
}

fn validate_declared_swift_package(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    package_source: &str,
) {
    let declared_package = get_str(&manifest.value, &["toolchain", "package"]);
    let package_name = parse_swift_package_name(package_source);

    match (declared_package, package_name.as_deref()) {
        (Some(declared), Some(actual)) if declared != actual => diagnostics.push(error(
            "implementation.swift.package.match",
            &manifest.path,
            format!("`toolchain.package` declares `{declared}` but Swift package is `{actual}`"),
        )),
        (None, Some(actual)) => diagnostics.push(warning(
            "implementation.swift.package.declared",
            &manifest.path,
            format!("Swift binding should declare `toolchain.package: {actual}`"),
        )),
        _ => {}
    }
}

fn validate_declared_swift_target(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    source_root: &Path,
) {
    let Some(target) = get_str(&manifest.value, &["toolchain", "target"]) else {
        diagnostics.push(warning(
            "implementation.swift.target.declared",
            &manifest.path,
            "Swift binding should declare `toolchain.target`",
        ));
        return;
    };

    if source_root.exists()
        && source_root
            .file_name()
            .and_then(|name| name.to_str())
            .is_none_or(|name| name != target)
    {
        diagnostics.push(warning(
            "implementation.swift.target.source-root",
            &manifest.path,
            format!("`source.root` usually points at `Sources/{target}` for Swift package targets"),
        ));
    }
}

fn validate_swift_source_boundaries(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    source_root: &Path,
) {
    if !source_root.exists() {
        return;
    }

    let allowed_external_modules: BTreeSet<_> = get_string_array(
        &manifest.value,
        &["dependencies", "allowed_external_modules"],
    )
    .into_iter()
    .collect();
    let allowed_public_reexports: BTreeSet<_> = get_string_array(
        &manifest.value,
        &["architecture", "allowed_public_reexports"],
    )
    .into_iter()
    .collect();
    let target = get_str(&manifest.value, &["toolchain", "target"]);

    for path in swift_source_files(source_root) {
        let source = match fs::read_to_string(&path) {
            Ok(source) => source,
            Err(read_error) => {
                diagnostics.push(error(
                    "implementation.swift.source.read",
                    &manifest.path,
                    format!(
                        "failed to read Swift source `{}`: {read_error}",
                        path.display()
                    ),
                ));
                continue;
            }
        };

        for import in collect_swift_imports(&source) {
            if is_swift_standard_module(&import.module) || target == Some(import.module.as_str()) {
                continue;
            }

            if !allowed_external_modules.contains(&import.module) {
                diagnostics.push(error(
                    "implementation.swift.imports.declared",
                    &manifest.path,
                    format!(
                        "Swift source `{}` imports external module `{}` not declared in `dependencies.allowed_external_modules`",
                        path.display(),
                        import.module
                    ),
                ));
            }

            if import.is_public_reexport && !allowed_public_reexports.contains(&import.module) {
                diagnostics.push(error(
                    "implementation.swift.reexports.external",
                    &manifest.path,
                    format!(
                        "Swift source `{}` publicly re-exports module `{}` without `architecture.allowed_public_reexports`",
                        path.display(),
                        import.module
                    ),
                ));
            }
        }
    }
}

fn validate_swift_typing(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    base: &Path,
    source_root: &Path,
) {
    if !source_root.exists() {
        return;
    }

    let module_manifest = load_binding_module_manifest(implementation, base);
    let mut summary = SwiftTypingSummary::default();

    for path in swift_source_files(source_root) {
        let source = match fs::read_to_string(&path) {
            Ok(source) => source,
            Err(read_error) => {
                diagnostics.push(error(
                    "implementation.swift.typing.source.read",
                    &implementation.path,
                    format!(
                        "failed to read Swift source `{}`: {read_error}",
                        path.display()
                    ),
                ));
                continue;
            }
        };

        inspect_swift_typing_file(implementation, diagnostics, &path, &source, &mut summary);
    }

    validate_swift_constructor_evidence(implementation, diagnostics, &summary);
    validate_swift_stateful_representation(
        implementation,
        diagnostics,
        module_manifest.as_ref(),
        &summary,
    );
    validate_swift_declared_architecture_symbols(implementation, diagnostics, &summary);
}

fn rust_cargo_manifest_path(manifest: &LoadedManifest, base: &Path, source_root: &Path) -> PathBuf {
    if let Some(path) = get_str(&manifest.value, &["toolchain", "cargo_manifest"]) {
        base.join(path)
    } else {
        source_root.join("Cargo.toml")
    }
}

fn validate_cargo_package_shape(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    cargo_manifest: &Path,
    cargo: &TomlValue,
) {
    let has_package = cargo.get("package").and_then(TomlValue::as_table).is_some();
    let has_workspace = cargo
        .get("workspace")
        .and_then(TomlValue::as_table)
        .is_some();

    if !has_package && !has_workspace {
        diagnostics.push(error(
            "implementation.rust.cargo-manifest.shape",
            &manifest.path,
            format!(
                "Cargo manifest `{}` must declare `[package]` or `[workspace]`",
                cargo_manifest.display()
            ),
        ));
    }

    if let Some(package) = cargo.get("package").and_then(TomlValue::as_table) {
        if package.get("name").and_then(TomlValue::as_str).is_none() {
            diagnostics.push(error(
                "implementation.rust.package.name",
                &manifest.path,
                "Rust package bindings must declare `package.name`",
            ));
        }

        if package.get("edition").and_then(TomlValue::as_str).is_none() {
            diagnostics.push(warning(
                "implementation.rust.package.edition",
                &manifest.path,
                "Rust package should declare `package.edition` explicitly",
            ));
        }
    }
}

fn validate_declared_rust_package(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    cargo: &TomlValue,
) {
    let declared_package = get_str(&manifest.value, &["toolchain", "package"]);
    let cargo_package = cargo
        .get("package")
        .and_then(|package| package.get("name"))
        .and_then(TomlValue::as_str);

    match (declared_package, cargo_package) {
        (Some(declared), Some(actual)) if declared != actual => diagnostics.push(error(
            "implementation.rust.package.match",
            &manifest.path,
            format!("`toolchain.package` declares `{declared}` but Cargo package is `{actual}`"),
        )),
        (None, Some(actual)) => diagnostics.push(warning(
            "implementation.rust.package.declared",
            &manifest.path,
            format!("Rust binding should declare `toolchain.package: {actual}`"),
        )),
        (None, None)
            if cargo
                .get("workspace")
                .and_then(TomlValue::as_table)
                .is_some() =>
        {
            diagnostics.push(warning(
                "implementation.rust.package.declared",
                &manifest.path,
                "workspace Rust bindings should declare `toolchain.package`",
            ));
        }
        _ => {}
    }
}

fn validate_rust_dependency_allowlist(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    cargo: &TomlValue,
) {
    let dependencies = collect_rust_dependencies(cargo);
    if dependencies.is_empty() {
        return;
    }

    let allowed = get_string_array(
        &manifest.value,
        &["dependencies", "allowed_external_crates"],
    );
    if allowed.is_empty() {
        diagnostics.push(warning(
            "implementation.rust.dependencies.allowlist",
            &manifest.path,
            "Rust binding should declare `dependencies.allowed_external_crates` to make crate dependencies explicit",
        ));
        return;
    }

    let allowed: BTreeSet<_> = allowed.into_iter().collect();
    for dependency in dependencies {
        if !allowed.contains(&dependency) {
            diagnostics.push(error(
                "implementation.rust.dependencies.allowlist",
                &manifest.path,
                format!(
                    "Cargo dependency `{dependency}` is not declared in `dependencies.allowed_external_crates`"
                ),
            ));
        }
    }
}

fn validate_rust_public_modules(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    public_entrypoint: &Path,
) {
    let allowed_modules = get_string_array(&manifest.value, &["architecture", "public_modules"]);
    if allowed_modules.is_empty() || !public_entrypoint.exists() {
        return;
    }

    let allowed: BTreeSet<_> = allowed_modules.into_iter().collect();
    let source = match fs::read_to_string(public_entrypoint) {
        Ok(source) => source,
        Err(read_error) => {
            diagnostics.push(error(
                "implementation.rust.public-modules.read",
                &manifest.path,
                format!(
                    "failed to read public entrypoint `{}`: {read_error}",
                    public_entrypoint.display()
                ),
            ));
            return;
        }
    };

    for module in public_modules_declared_in_source(&source) {
        if !allowed.contains(&module) {
            diagnostics.push(error(
                "implementation.rust.public-modules",
                &manifest.path,
                format!(
                    "public module `{module}` is not declared in `architecture.public_modules`"
                ),
            ));
        }
    }
}

fn validate_rust_source_boundaries(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    source_root: &Path,
    cargo: &TomlValue,
) {
    if !source_root.exists() {
        return;
    }

    let allowed_external_crates: BTreeSet<_> = get_string_array(
        &manifest.value,
        &["dependencies", "allowed_external_crates"],
    )
    .into_iter()
    .collect();
    let public_modules: BTreeSet<_> =
        get_string_array(&manifest.value, &["architecture", "public_modules"])
            .into_iter()
            .collect();
    let mut local_modules = local_module_roots(source_root);
    local_modules.extend(public_modules.iter().cloned());
    local_modules.extend(rust_local_crate_names(cargo));
    let allowed_public_reexports: BTreeSet<_> = get_string_array(
        &manifest.value,
        &["architecture", "allowed_public_reexports"],
    )
    .into_iter()
    .collect();

    for path in rust_source_files(source_root) {
        let source = match fs::read_to_string(&path) {
            Ok(source) => source,
            Err(read_error) => {
                diagnostics.push(error(
                    "implementation.rust.source.read",
                    &manifest.path,
                    format!(
                        "failed to read Rust source `{}`: {read_error}",
                        path.display()
                    ),
                ));
                continue;
            }
        };
        let parsed = match syn::parse_file(&source) {
            Ok(parsed) => parsed,
            Err(parse_error) => {
                diagnostics.push(error(
                    "implementation.rust.source.parse",
                    &manifest.path,
                    format!(
                        "failed to parse Rust source `{}`: {parse_error}",
                        path.display()
                    ),
                ));
                continue;
            }
        };

        for import in collect_rust_imports(&parsed) {
            match rust_import_root_kind(&import.root, &local_modules) {
                RustImportRootKind::External => {
                    if !allowed_external_crates.contains(&import.root) {
                        diagnostics.push(error(
                            "implementation.rust.imports.declared",
                            &manifest.path,
                            format!(
                                "Rust source `{}` imports external crate `{}` not declared in `dependencies.allowed_external_crates`",
                                path.display(),
                                import.root
                            ),
                        ));
                    }
                    if import.is_public && !allowed_public_reexports.contains(&import.root) {
                        diagnostics.push(error(
                            "implementation.rust.reexports.external",
                            &manifest.path,
                            format!(
                                "Rust source `{}` publicly re-exports external crate `{}` without `architecture.allowed_public_reexports`",
                                path.display(),
                                import.root
                            ),
                        ));
                    }
                }
                RustImportRootKind::LocalModule => {
                    if import.is_public
                        && !public_modules.is_empty()
                        && !public_modules.contains(&import.root)
                    {
                        diagnostics.push(error(
                            "implementation.rust.reexports.private-module",
                            &manifest.path,
                            format!(
                                "Rust source `{}` publicly re-exports local module `{}` that is not declared in `architecture.public_modules`",
                                path.display(),
                                import.root
                            ),
                        ));
                    }
                }
                RustImportRootKind::Standard | RustImportRootKind::SelfQualified => {}
            }
        }
    }
}

fn validate_rust_typing(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    base: &Path,
    source_root: &Path,
) {
    if !source_root.exists() {
        return;
    }

    let module_manifest = load_binding_module_manifest(implementation, base);
    let mut summary = RustTypingSummary::default();

    for path in rust_source_files(source_root) {
        let source = match fs::read_to_string(&path) {
            Ok(source) => source,
            Err(read_error) => {
                diagnostics.push(error(
                    "implementation.rust.typing.source.read",
                    &implementation.path,
                    format!(
                        "failed to read Rust source `{}`: {read_error}",
                        path.display()
                    ),
                ));
                continue;
            }
        };
        let parsed = match syn::parse_file(&source) {
            Ok(parsed) => parsed,
            Err(parse_error) => {
                diagnostics.push(error(
                    "implementation.rust.typing.source.parse",
                    &implementation.path,
                    format!(
                        "failed to parse Rust source `{}`: {parse_error}",
                        path.display()
                    ),
                ));
                continue;
            }
        };

        inspect_rust_typing_file(implementation, diagnostics, &path, &parsed, &mut summary);
    }

    validate_rust_constructor_evidence(implementation, diagnostics, &summary);
    validate_rust_stateful_representation(
        implementation,
        diagnostics,
        module_manifest.as_ref(),
        &summary,
    );
    validate_rust_declared_architecture_symbols(implementation, diagnostics, &summary);
    validate_rust_semantic_function_symbols(implementation, diagnostics, &summary);
}

fn inspect_rust_typing_file(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    path: &Path,
    parsed: &syn::File,
    summary: &mut RustTypingSummary,
) {
    let allowed_public_field_structs: BTreeSet<_> = get_string_array(
        &implementation.value,
        &["architecture", "allowed_public_field_structs"],
    )
    .into_iter()
    .collect();
    let allowed_primitive_aliases: BTreeSet<_> = get_string_array(
        &implementation.value,
        &["architecture", "allowed_primitive_type_aliases"],
    )
    .into_iter()
    .collect();
    let allow_panics =
        get_bool(&implementation.value, &["architecture", "allow_panics"]).unwrap_or(false);

    for item in &parsed.items {
        if has_cfg_test_attr(item_attrs(item)) {
            continue;
        }

        match item {
            Item::Struct(item_struct) => {
                inspect_rust_struct_typing(
                    implementation,
                    diagnostics,
                    path,
                    item_struct,
                    &allowed_public_field_structs,
                    summary,
                );
            }
            Item::Enum(item_enum) => {
                if matches!(item_enum.vis, Visibility::Public(_)) {
                    summary.public_types.insert(item_enum.ident.to_string());
                } else {
                    summary.private_types.insert(item_enum.ident.to_string());
                }
            }
            Item::Type(item_type) => {
                if matches!(item_type.vis, Visibility::Public(_)) {
                    summary.public_types.insert(item_type.ident.to_string());
                    if is_primitive_alias_target(&item_type.ty)
                        && !allowed_primitive_aliases.contains(&item_type.ident.to_string())
                    {
                        diagnostics.push(error(
                            "implementation.rust.typing.primitive-alias",
                            &implementation.path,
                            format!(
                                "public type alias `{}` in `{}` points at a primitive; prefer a newtype/opaque value or declare it in `architecture.allowed_primitive_type_aliases`",
                                item_type.ident,
                                path.display()
                            ),
                        ));
                    }
                } else {
                    summary.private_types.insert(item_type.ident.to_string());
                }
            }
            Item::Impl(item_impl) => collect_rust_impl_methods(item_impl, summary),
            Item::Fn(item_fn) => {
                summary.functions.insert(item_fn.sig.ident.to_string());
            }
            _ => {}
        }

        if !allow_panics {
            let mut visitor = RustFailureVisitor::default();
            visitor.visit_item(item);
            for failure in visitor.failures {
                diagnostics.push(error(
                    "implementation.rust.typing.failure-discipline",
                    &implementation.path,
                    format!(
                        "Rust source `{}` uses `{}` in non-test domain code; prefer explicit result/error types for expected failures",
                        path.display(),
                        failure
                    ),
                ));
            }
        }
    }
}

fn inspect_rust_struct_typing(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    path: &Path,
    item_struct: &ItemStruct,
    allowed_public_field_structs: &BTreeSet<String>,
    summary: &mut RustTypingSummary,
) {
    let struct_name = item_struct.ident.to_string();
    if matches!(item_struct.vis, Visibility::Public(_)) {
        summary.public_types.insert(struct_name.clone());
    } else {
        summary.private_types.insert(struct_name.clone());
    }

    let public_fields = public_struct_field_count(item_struct);
    if public_fields > 0 && !allowed_public_field_structs.contains(&struct_name) {
        diagnostics.push(error(
            "implementation.rust.typing.public-fields",
            &implementation.path,
            format!(
                "public struct `{struct_name}` in `{}` exposes {public_fields} public field(s); prefer private fields plus validated constructors/accessors or declare it in `architecture.allowed_public_field_structs`",
                path.display()
            ),
        ));
    }

    if matches!(item_struct.vis, Visibility::Public(_))
        && private_struct_field_count(item_struct) > 0
    {
        summary
            .public_structs_with_private_fields
            .insert(struct_name);
    }
}

fn validate_rust_constructor_evidence(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    summary: &RustTypingSummary,
) {
    let allowed_missing_constructors: BTreeSet<_> = get_string_array(
        &implementation.value,
        &["architecture", "allowed_missing_constructors"],
    )
    .into_iter()
    .collect();

    for struct_name in &summary.public_structs_with_private_fields {
        if allowed_missing_constructors.contains(struct_name) {
            continue;
        }
        let Some(methods) = summary.impl_methods.get(struct_name) else {
            diagnostics.push(warning(
                "implementation.rust.typing.constructor",
                &implementation.path,
                format!(
                    "public struct `{struct_name}` has private fields but no public constructor evidence; add `new`/`try_new`/`parse`, or if it is produced only by a query/projector declare `architecture.allowed_missing_constructors` and evidence the producer"
                ),
            ));
            continue;
        };
        if !methods.iter().any(|method| is_constructor_like(method)) {
            diagnostics.push(warning(
                "implementation.rust.typing.constructor",
                &implementation.path,
                format!(
                    "public struct `{struct_name}` has private fields but no constructor-like method (`new`, `try_new`, `parse`, `from_*`); add one, or if it is produced only by a query/projector declare `architecture.allowed_missing_constructors` and evidence the producer"
                ),
            ));
        }
    }
}

fn validate_rust_stateful_representation(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    module_manifest: Option<&LoadedManifest>,
    summary: &RustTypingSummary,
) {
    let Some(module_manifest) = module_manifest else {
        return;
    };
    let profiles = get_string_array(&module_manifest.value, &["profiles"]);
    if !profiles.iter().any(|profile| profile == "stateful") {
        return;
    }

    let state_type = get_str(&implementation.value, &["architecture", "state_type"]);
    let transition_function = get_str(
        &implementation.value,
        &["architecture", "transition_function"],
    );

    if state_type.is_none() && transition_function.is_none() {
        diagnostics.push(error(
            "implementation.rust.typing.stateful-representation",
            &implementation.path,
            "stateful Rust bindings must declare `architecture.state_type` or `architecture.transition_function`",
        ));
        return;
    }

    if let Some(state_type) = state_type {
        if !summary.public_types.contains(state_type) && !summary.private_types.contains(state_type)
        {
            diagnostics.push(error(
                "implementation.rust.typing.state-type",
                &implementation.path,
                format!("declared `architecture.state_type` `{state_type}` was not found in Rust source"),
            ));
        }
    }

    if let Some(transition_function) = transition_function {
        if !summary.functions.contains(transition_function) {
            diagnostics.push(error(
                "implementation.rust.typing.transition-function",
                &implementation.path,
                format!("declared `architecture.transition_function` `{transition_function}` was not found in Rust source"),
            ));
        }
    }
}

fn validate_rust_semantic_function_symbols(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    summary: &RustTypingSummary,
) {
    let Some(functions) = semantic_function_items(implementation) else {
        return;
    };

    for function in functions {
        let Some(symbol) = get_str(function, &["symbol"]) else {
            continue;
        };

        if !rust_symbol_exists(summary, symbol) {
            diagnostics.push(error(
                "implementation.rust.semantic-functions.symbol",
                &implementation.path,
                format!("semantic function symbol `{symbol}` was not found in Rust source"),
            ));
        }
    }
}

fn validate_rust_declared_architecture_symbols(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    summary: &RustTypingSummary,
) {
    for declared in declared_architecture_symbols(&implementation.value) {
        let found = match declared.kind {
            DeclaredSymbolKind::Type => rust_type_exists(summary, &declared.symbol),
            DeclaredSymbolKind::Function => rust_symbol_exists(summary, &declared.symbol),
        };
        if !found {
            diagnostics.push(error(
                "structure.declared-symbol-missing",
                &implementation.path,
                format!(
                    "declared architecture {} `{}` was not found in Rust source",
                    declared.role, declared.symbol
                ),
            ));
        }
    }
}

fn rust_type_exists(summary: &RustTypingSummary, symbol: &str) -> bool {
    summary.public_types.contains(symbol) || summary.private_types.contains(symbol)
}

fn rust_symbol_exists(summary: &RustTypingSummary, symbol: &str) -> bool {
    if summary.functions.contains(symbol) {
        return true;
    }

    let parts: Vec<_> = symbol.split("::").filter(|part| !part.is_empty()).collect();
    if parts.is_empty() {
        return false;
    }

    if let Some(function_name) = parts.last() {
        if summary.functions.contains(*function_name) {
            return true;
        }
    }

    if parts.len() >= 2 {
        let type_name = parts[parts.len() - 2];
        let method_name = parts[parts.len() - 1];
        if summary
            .impl_methods
            .get(type_name)
            .is_some_and(|methods| methods.contains(method_name))
        {
            return true;
        }
    }

    false
}

fn collect_rust_dependencies(cargo: &TomlValue) -> BTreeSet<String> {
    let mut dependencies = BTreeSet::new();
    for table_name in ["dependencies", "dev-dependencies", "build-dependencies"] {
        collect_dependency_table(cargo.get(table_name), &mut dependencies);
    }

    if let Some(targets) = cargo.get("target").and_then(TomlValue::as_table) {
        for target in targets.values() {
            collect_dependency_table(target.get("dependencies"), &mut dependencies);
            collect_dependency_table(target.get("dev-dependencies"), &mut dependencies);
            collect_dependency_table(target.get("build-dependencies"), &mut dependencies);
        }
    }

    dependencies
}

fn rust_local_crate_names(cargo: &TomlValue) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    if let Some(lib_name) = cargo
        .get("lib")
        .and_then(TomlValue::as_table)
        .and_then(|lib| lib.get("name"))
        .and_then(TomlValue::as_str)
    {
        names.insert(lib_name.to_string());
    }
    if let Some(package_name) = cargo
        .get("package")
        .and_then(|package| package.get("name"))
        .and_then(TomlValue::as_str)
    {
        names.insert(package_name.replace('-', "_"));
    }
    names
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct RustImport {
    root: String,
    is_public: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RustImportRootKind {
    External,
    LocalModule,
    Standard,
    SelfQualified,
}

fn rust_import_root_kind(root: &str, local_modules: &BTreeSet<String>) -> RustImportRootKind {
    match root {
        "std" | "core" | "alloc" => RustImportRootKind::Standard,
        "crate" | "self" | "super" => RustImportRootKind::SelfQualified,
        _ if local_modules.contains(root) => RustImportRootKind::LocalModule,
        _ => RustImportRootKind::External,
    }
}

fn rust_source_files(source_root: &Path) -> Vec<PathBuf> {
    WalkDir::new(source_root)
        .follow_links(false)
        .into_iter()
        .filter_map(Result::ok)
        .filter(|entry| entry.file_type().is_file())
        .map(|entry| entry.into_path())
        .filter(|path| !path_has_component(path, "target"))
        .filter(|path| !path_has_component(path, ".git"))
        .filter(|path| path.extension().and_then(|ext| ext.to_str()) == Some("rs"))
        .collect()
}

fn path_has_component(path: &Path, component: &str) -> bool {
    path.components()
        .any(|part| matches!(part, Component::Normal(value) if value == component))
}

fn collect_rust_imports(file: &syn::File) -> Vec<RustImport> {
    let mut imports = Vec::new();
    for item in &file.items {
        match item {
            Item::Use(item_use) => {
                let is_public = matches!(item_use.vis, Visibility::Public(_));
                collect_use_tree_roots(&item_use.tree, None, is_public, &mut imports);
            }
            Item::ExternCrate(extern_crate) => {
                imports.push(RustImport {
                    root: extern_crate.ident.to_string(),
                    is_public: matches!(extern_crate.vis, Visibility::Public(_)),
                });
            }
            _ => {}
        }
    }
    imports
}

#[derive(Default)]
struct RustTypingSummary {
    public_types: BTreeSet<String>,
    private_types: BTreeSet<String>,
    public_structs_with_private_fields: BTreeSet<String>,
    impl_methods: std::collections::BTreeMap<String, BTreeSet<String>>,
    functions: BTreeSet<String>,
}

#[derive(Default)]
struct RustFailureVisitor {
    failures: Vec<String>,
}

impl<'ast> Visit<'ast> for RustFailureVisitor {
    fn visit_item(&mut self, item: &'ast Item) {
        if has_cfg_test_attr(item_attrs(item)) {
            return;
        }
        visit::visit_item(self, item);
    }

    fn visit_expr_method_call(&mut self, node: &'ast ExprMethodCall) {
        let method = node.method.to_string();
        if matches!(method.as_str(), "unwrap" | "expect") {
            self.failures.push(format!(".{method}()"));
        }
        visit::visit_expr_method_call(self, node);
    }

    fn visit_expr_macro(&mut self, node: &'ast ExprMacro) {
        if let Some(name) = node
            .mac
            .path
            .segments
            .last()
            .map(|segment| segment.ident.to_string())
        {
            if matches!(name.as_str(), "panic" | "todo" | "unimplemented") {
                self.failures.push(format!("{name}!"));
            }
        }
        visit::visit_expr_macro(self, node);
    }
}

fn collect_rust_impl_methods(item_impl: &syn::ItemImpl, summary: &mut RustTypingSummary) {
    let Some(type_name) = rust_type_name(&item_impl.self_ty) else {
        return;
    };

    let methods = summary.impl_methods.entry(type_name).or_default();
    for item in &item_impl.items {
        if let ImplItem::Fn(function) = item {
            if matches!(function.vis, Visibility::Public(_)) {
                methods.insert(function.sig.ident.to_string());
            }
        }
    }
}

fn rust_type_name(ty: &Type) -> Option<String> {
    let Type::Path(path) = ty else {
        return None;
    };
    path.path
        .segments
        .last()
        .map(|segment| segment.ident.to_string())
}

fn is_constructor_like(method: &str) -> bool {
    method == "new"
        || method == "try_new"
        || method == "parse"
        || method == "from_validated"
        || method.starts_with("from_")
}

fn public_struct_field_count(item_struct: &ItemStruct) -> usize {
    match &item_struct.fields {
        Fields::Named(fields) => fields
            .named
            .iter()
            .filter(|field| matches!(field.vis, Visibility::Public(_)))
            .count(),
        Fields::Unnamed(fields) => fields
            .unnamed
            .iter()
            .filter(|field| matches!(field.vis, Visibility::Public(_)))
            .count(),
        Fields::Unit => 0,
    }
}

fn private_struct_field_count(item_struct: &ItemStruct) -> usize {
    match &item_struct.fields {
        Fields::Named(fields) => fields
            .named
            .iter()
            .filter(|field| !matches!(field.vis, Visibility::Public(_)))
            .count(),
        Fields::Unnamed(fields) => fields
            .unnamed
            .iter()
            .filter(|field| !matches!(field.vis, Visibility::Public(_)))
            .count(),
        Fields::Unit => 0,
    }
}

fn is_primitive_alias_target(ty: &Type) -> bool {
    let Some(name) = rust_type_name(ty) else {
        return false;
    };
    matches!(
        name.as_str(),
        "String"
            | "str"
            | "bool"
            | "char"
            | "u8"
            | "u16"
            | "u32"
            | "u64"
            | "u128"
            | "usize"
            | "i8"
            | "i16"
            | "i32"
            | "i64"
            | "i128"
            | "isize"
            | "f32"
            | "f64"
    )
}

fn item_attrs(item: &Item) -> &[Attribute] {
    match item {
        Item::Const(item) => &item.attrs,
        Item::Enum(item) => &item.attrs,
        Item::ExternCrate(item) => &item.attrs,
        Item::Fn(item) => &item.attrs,
        Item::Impl(item) => &item.attrs,
        Item::Mod(item) => &item.attrs,
        Item::Static(item) => &item.attrs,
        Item::Struct(item) => &item.attrs,
        Item::Trait(item) => &item.attrs,
        Item::TraitAlias(item) => &item.attrs,
        Item::Type(item) => &item.attrs,
        Item::Union(item) => &item.attrs,
        Item::Use(item) => &item.attrs,
        _ => &[],
    }
}

fn has_cfg_test_attr(attrs: &[Attribute]) -> bool {
    attrs.iter().any(|attr| {
        if attr.path().is_ident("test") {
            return true;
        }
        match &attr.meta {
            Meta::List(list) if list.path.is_ident("cfg") => {
                list.tokens.to_string().contains("test")
            }
            _ => false,
        }
    })
}

fn collect_use_tree_roots(
    tree: &UseTree,
    prefix: Option<String>,
    is_public: bool,
    imports: &mut Vec<RustImport>,
) {
    match tree {
        UseTree::Path(path) => {
            let root = prefix.unwrap_or_else(|| path.ident.to_string());
            collect_use_tree_roots(&path.tree, Some(root), is_public, imports);
        }
        UseTree::Name(name) => imports.push(RustImport {
            root: prefix.unwrap_or_else(|| name.ident.to_string()),
            is_public,
        }),
        UseTree::Rename(rename) => imports.push(RustImport {
            root: prefix.unwrap_or_else(|| rename.ident.to_string()),
            is_public,
        }),
        UseTree::Glob(_) => {
            if let Some(root) = prefix {
                imports.push(RustImport {
                    root: root.to_string(),
                    is_public,
                });
            }
        }
        UseTree::Group(group) => {
            for item in &group.items {
                collect_use_tree_roots(item, prefix.clone(), is_public, imports);
            }
        }
    }
}

fn local_module_roots(source_root: &Path) -> BTreeSet<String> {
    let mut roots = BTreeSet::new();
    let Ok(entries) = fs::read_dir(source_root) else {
        return roots;
    };

    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        if path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some("rs") {
            if let Some(stem) = path.file_stem().and_then(|stem| stem.to_str()) {
                if stem != "lib" && stem != "main" {
                    roots.insert(stem.to_string());
                }
            }
        } else if path.is_dir() {
            if let Some(name) = path.file_name().and_then(|name| name.to_str()) {
                roots.insert(name.to_string());
            }
        }
    }

    roots
}

fn collect_dependency_table(value: Option<&TomlValue>, dependencies: &mut BTreeSet<String>) {
    let Some(table) = value.and_then(TomlValue::as_table) else {
        return;
    };
    for name in table.keys() {
        dependencies.insert(name.to_string());
    }
}

fn public_modules_declared_in_source(source: &str) -> BTreeSet<String> {
    let mut modules = BTreeSet::new();
    for line in source.lines() {
        let trimmed = line.trim_start();
        let Some(rest) = trimmed.strip_prefix("pub mod ") else {
            continue;
        };
        let module = rest
            .split(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
            .next()
            .unwrap_or_default();
        if !module.is_empty() {
            modules.insert(module.to_string());
        }
    }
    modules
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct SwiftImport {
    module: String,
    is_public_reexport: bool,
}

#[derive(Default)]
struct SwiftTypingSummary {
    public_types: BTreeSet<String>,
    private_types: BTreeSet<String>,
    public_structs_with_private_fields: BTreeSet<String>,
    public_structs_with_constructors: BTreeSet<String>,
    functions: BTreeSet<String>,
}

#[derive(Default)]
struct JsSourceSummary {
    symbols: BTreeSet<String>,
    functions: BTreeSet<String>,
}

#[derive(Default)]
struct SwiftStructScan {
    name: String,
    depth: i32,
    private_fields: usize,
    public_fields: usize,
    has_constructor: bool,
}

fn parse_swift_package_name(source: &str) -> Option<String> {
    find_keyed_quoted_value(source, "name:")
}

fn find_keyed_quoted_value(source: &str, key: &str) -> Option<String> {
    for line in source.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("//") {
            continue;
        }
        let Some(index) = trimmed.find(key) else {
            continue;
        };
        let after_key = &trimmed[index + key.len()..];
        let start = after_key.find('"')?;
        let after_quote = &after_key[start + 1..];
        let end = after_quote.find('"')?;
        return Some(after_quote[..end].to_string());
    }
    None
}

fn swift_source_files(source_root: &Path) -> Vec<PathBuf> {
    WalkDir::new(source_root)
        .follow_links(false)
        .into_iter()
        .filter_map(Result::ok)
        .filter(|entry| entry.file_type().is_file())
        .map(|entry| entry.into_path())
        .filter(|path| !path_has_component(path, ".build"))
        .filter(|path| !path_has_component(path, ".git"))
        .filter(|path| path.extension().and_then(|ext| ext.to_str()) == Some("swift"))
        .collect()
}

fn js_source_files(source_root: &Path) -> Vec<PathBuf> {
    WalkDir::new(source_root)
        .follow_links(false)
        .into_iter()
        .filter_map(Result::ok)
        .filter(|entry| entry.file_type().is_file())
        .map(|entry| entry.into_path())
        .filter(|path| !path_has_component(path, "node_modules"))
        .filter(|path| !path_has_component(path, ".git"))
        .filter(|path| {
            matches!(
                path.extension().and_then(|ext| ext.to_str()),
                Some("js" | "mjs" | "cjs")
            )
        })
        .collect()
}

fn inspect_js_source(source: &str, summary: &mut JsSourceSummary) {
    for line in source.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("//") {
            continue;
        }

        if let Some(name) = parse_js_function_name(trimmed) {
            summary.functions.insert(name.clone());
            summary.symbols.insert(name);
        }
        if let Some(name) = parse_js_declaration_name(trimmed, "const") {
            summary.symbols.insert(name);
        }
        if let Some(name) = parse_js_declaration_name(trimmed, "let") {
            summary.symbols.insert(name);
        }
        if let Some(name) = parse_js_declaration_name(trimmed, "class") {
            summary.symbols.insert(name);
        }
        for name in parse_js_export_list(trimmed) {
            summary.symbols.insert(name);
        }
    }
}

fn parse_js_function_name(line: &str) -> Option<String> {
    let mut rest = strip_js_export(line);
    if let Some(after_async) = rest.strip_prefix("async ") {
        rest = after_async.trim_start();
    }
    let rest = rest.strip_prefix("function ")?.trim_start();
    Some(js_identifier(rest)?.to_string())
}

fn parse_js_declaration_name(line: &str, kind: &str) -> Option<String> {
    let rest = strip_js_export(line);
    let rest = rest.strip_prefix(kind)?.trim_start();
    Some(js_identifier(rest)?.to_string())
}

fn parse_js_export_list(line: &str) -> Vec<String> {
    let Some(rest) = line.strip_prefix("export {") else {
        return Vec::new();
    };
    let Some((items, _)) = rest.split_once('}') else {
        return Vec::new();
    };
    items
        .split(',')
        .filter_map(|item| {
            let item = item.trim();
            let name = item
                .split_whitespace()
                .collect::<Vec<_>>()
                .split(|token| *token == "as")
                .next()
                .and_then(|tokens| tokens.first())
                .copied()
                .unwrap_or(item);
            js_identifier(name).map(str::to_string)
        })
        .collect()
}

fn strip_js_export(line: &str) -> &str {
    let mut rest = line.trim_start();
    if let Some(after_export) = rest.strip_prefix("export ") {
        rest = after_export.trim_start();
    }
    if let Some(after_default) = rest.strip_prefix("default ") {
        rest = after_default.trim_start();
    }
    rest
}

fn js_identifier(value: &str) -> Option<&str> {
    let identifier = value
        .trim_start()
        .split(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
        .next()
        .unwrap_or_default();
    if is_checkable_identifier(identifier) {
        Some(identifier)
    } else {
        None
    }
}

fn collect_swift_imports(source: &str) -> Vec<SwiftImport> {
    let mut imports = Vec::new();
    for line in source.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("//") {
            continue;
        }

        let (rest, is_public_reexport) =
            if let Some(rest) = trimmed.strip_prefix("@_exported import ") {
                (rest, true)
            } else if let Some(rest) = trimmed.strip_prefix("import ") {
                (rest, false)
            } else {
                continue;
            };

        let rest = strip_swift_import_qualifier(rest.trim_start());
        let module = rest
            .split(|character: char| {
                !(character.is_ascii_alphanumeric() || character == '_' || character == '.')
            })
            .next()
            .unwrap_or_default()
            .split('.')
            .next()
            .unwrap_or_default();
        if !module.is_empty() {
            imports.push(SwiftImport {
                module: module.to_string(),
                is_public_reexport,
            });
        }
    }
    imports
}

fn strip_swift_import_qualifier(value: &str) -> &str {
    for qualifier in ["class ", "struct ", "enum ", "protocol ", "func ", "var "] {
        if let Some(rest) = value.strip_prefix(qualifier) {
            return rest.trim_start();
        }
    }
    value
}

fn is_swift_standard_module(module: &str) -> bool {
    matches!(
        module,
        "Swift"
            | "Foundation"
            | "Dispatch"
            | "Darwin"
            | "Glibc"
            | "UIKit"
            | "AppKit"
            | "SwiftUI"
            | "Combine"
            | "Observation"
            | "XCTest"
    )
}

fn inspect_swift_typing_file(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    path: &Path,
    source: &str,
    summary: &mut SwiftTypingSummary,
) {
    let allowed_public_field_structs: BTreeSet<_> = get_string_array(
        &implementation.value,
        &["architecture", "allowed_public_field_structs"],
    )
    .into_iter()
    .collect();
    let allowed_primitive_aliases: BTreeSet<_> = get_string_array(
        &implementation.value,
        &["architecture", "allowed_primitive_type_aliases"],
    )
    .into_iter()
    .collect();
    let allow_traps =
        get_bool(&implementation.value, &["architecture", "allow_traps"]).unwrap_or(false);
    let mut current_struct: Option<SwiftStructScan> = None;

    for line in source.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("//") {
            continue;
        }

        if !allow_traps {
            for trap in swift_traps_in_line(trimmed) {
                diagnostics.push(error(
                    "implementation.swift.typing.failure-discipline",
                    &implementation.path,
                    format!(
                        "Swift source `{}` uses `{trap}` in domain code; prefer explicit result/error types for expected failures",
                        path.display()
                    ),
                ));
            }
        }

        if let Some((name, target)) = parse_swift_public_typealias(trimmed) {
            summary.public_types.insert(name.clone());
            if is_swift_primitive_type(target) && !allowed_primitive_aliases.contains(name.as_str())
            {
                diagnostics.push(error(
                    "implementation.swift.typing.primitive-alias",
                    &implementation.path,
                    format!(
                        "public typealias `{name}` in `{}` points at a primitive; prefer an opaque value type or declare it in `architecture.allowed_primitive_type_aliases`",
                        path.display()
                    ),
                ));
            }
        }

        if let Some(name) = parse_swift_declaration_name(trimmed, "enum") {
            if has_swift_public_modifier(trimmed) {
                summary.public_types.insert(name);
            } else {
                summary.private_types.insert(name);
            }
        }
        if let Some(name) = parse_swift_function_name(trimmed) {
            summary.functions.insert(name);
        }

        if let Some(scan) = current_struct.as_mut() {
            if is_swift_public_field(trimmed) {
                scan.public_fields += 1;
            } else if is_swift_stored_field(trimmed) {
                scan.private_fields += 1;
            }
            if is_swift_constructor_like(trimmed) {
                scan.has_constructor = true;
            }
            scan.depth += swift_brace_delta(trimmed);
            if scan.depth <= 0 {
                if let Some(finished_scan) = current_struct.take() {
                    finish_swift_struct_scan(
                        implementation,
                        diagnostics,
                        path,
                        &allowed_public_field_structs,
                        summary,
                        finished_scan,
                    );
                }
            }
            continue;
        }

        if let Some(name) = parse_swift_declaration_name(trimmed, "struct") {
            if has_swift_public_modifier(trimmed) {
                summary.public_types.insert(name.clone());
                current_struct = Some(SwiftStructScan {
                    name,
                    depth: swift_brace_delta(trimmed).max(1),
                    private_fields: 0,
                    public_fields: 0,
                    has_constructor: false,
                });
            } else {
                summary.private_types.insert(name);
            }
        }
    }

    if let Some(scan) = current_struct {
        finish_swift_struct_scan(
            implementation,
            diagnostics,
            path,
            &allowed_public_field_structs,
            summary,
            scan,
        );
    }
}

fn finish_swift_struct_scan(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    path: &Path,
    allowed_public_field_structs: &BTreeSet<String>,
    summary: &mut SwiftTypingSummary,
    scan: SwiftStructScan,
) {
    if scan.public_fields > 0 && !allowed_public_field_structs.contains(&scan.name) {
        diagnostics.push(error(
            "implementation.swift.typing.public-fields",
            &implementation.path,
            format!(
                "public struct `{}` in `{}` exposes {} public field(s); prefer private fields plus validated initializers/accessors or declare it in `architecture.allowed_public_field_structs`",
                scan.name,
                path.display(),
                scan.public_fields
            ),
        ));
    }

    if scan.private_fields > 0 {
        summary
            .public_structs_with_private_fields
            .insert(scan.name.clone());
    }
    if scan.has_constructor {
        summary.public_structs_with_constructors.insert(scan.name);
    }
}

fn validate_swift_constructor_evidence(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    summary: &SwiftTypingSummary,
) {
    let allowed_missing_constructors: BTreeSet<_> = get_string_array(
        &implementation.value,
        &["architecture", "allowed_missing_constructors"],
    )
    .into_iter()
    .collect();

    for struct_name in &summary.public_structs_with_private_fields {
        if allowed_missing_constructors.contains(struct_name)
            || summary
                .public_structs_with_constructors
                .contains(struct_name)
        {
            continue;
        }
        diagnostics.push(warning(
            "implementation.swift.typing.constructor",
            &implementation.path,
            format!(
                "public struct `{struct_name}` has private fields but no public initializer/factory evidence; add `init`, `new`, `parse`, or if it is produced only by a query/projector declare `architecture.allowed_missing_constructors` and evidence the producer"
            ),
        ));
    }
}

fn validate_swift_stateful_representation(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    module_manifest: Option<&LoadedManifest>,
    summary: &SwiftTypingSummary,
) {
    let Some(module_manifest) = module_manifest else {
        return;
    };
    let profiles = get_string_array(&module_manifest.value, &["profiles"]);
    if !profiles.iter().any(|profile| profile == "stateful") {
        return;
    }

    let state_type = get_str(&implementation.value, &["architecture", "state_type"]);
    let transition_function = get_str(
        &implementation.value,
        &["architecture", "transition_function"],
    );

    if state_type.is_none() && transition_function.is_none() {
        diagnostics.push(error(
            "implementation.swift.typing.stateful-representation",
            &implementation.path,
            "stateful Swift bindings must declare `architecture.state_type` or `architecture.transition_function`",
        ));
        return;
    }

    if let Some(state_type) = state_type {
        if !summary.public_types.contains(state_type) && !summary.private_types.contains(state_type)
        {
            diagnostics.push(error(
                "implementation.swift.typing.state-type",
                &implementation.path,
                format!(
                    "declared `architecture.state_type` `{state_type}` was not found in Swift source"
                ),
            ));
        }
    }

    if let Some(transition_function) = transition_function {
        if !summary.functions.contains(transition_function) {
            diagnostics.push(error(
                "implementation.swift.typing.transition-function",
                &implementation.path,
                format!("declared `architecture.transition_function` `{transition_function}` was not found in Swift source"),
            ));
        }
    }
}

fn validate_swift_declared_architecture_symbols(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    summary: &SwiftTypingSummary,
) {
    for declared in declared_architecture_symbols(&implementation.value) {
        let found = match declared.kind {
            DeclaredSymbolKind::Type => swift_type_exists(summary, &declared.symbol),
            DeclaredSymbolKind::Function => summary.functions.contains(&declared.symbol),
        };
        if !found {
            diagnostics.push(error(
                "structure.declared-symbol-missing",
                &implementation.path,
                format!(
                    "declared architecture {} `{}` was not found in Swift source",
                    declared.role, declared.symbol
                ),
            ));
        }
    }
}

fn swift_type_exists(summary: &SwiftTypingSummary, symbol: &str) -> bool {
    summary.public_types.contains(symbol) || summary.private_types.contains(symbol)
}

fn validate_js_declared_architecture_symbols(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    summary: &JsSourceSummary,
) {
    for declared in declared_architecture_symbols(&implementation.value) {
        let found = match declared.kind {
            DeclaredSymbolKind::Type => js_type_like_symbol_exists(summary, &declared.symbol),
            DeclaredSymbolKind::Function => summary.functions.contains(&declared.symbol),
        };
        if !found {
            diagnostics.push(error(
                "structure.declared-symbol-missing",
                &implementation.path,
                format!(
                    "declared architecture {} `{}` was not found in JavaScript source",
                    declared.role, declared.symbol
                ),
            ));
        }
    }
}

fn validate_js_semantic_function_symbols(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    summary: &JsSourceSummary,
) {
    let Some(functions) = semantic_function_items(implementation) else {
        return;
    };
    for function in functions {
        let Some(symbol) = get_str(function, &["symbol"]) else {
            continue;
        };
        let function_name = symbol.rsplit_once('#').map_or(symbol, |(_, name)| name);
        if !summary.functions.contains(function_name) && !summary.symbols.contains(function_name) {
            diagnostics.push(error(
                "implementation.js.semantic-functions.symbol",
                &implementation.path,
                format!("semantic function symbol `{symbol}` was not found in JavaScript source"),
            ));
        }
    }
}

fn validate_js_machine_shape(
    implementation: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    source_root: &Path,
) {
    let source = read_js_sources_concatenated(source_root);
    if source.trim().is_empty() {
        return;
    }

    for state in get_string_array(
        &implementation.value,
        &["architecture", "machine", "states"],
    ) {
        if !js_variant_represented(&source, &state) {
            push_unique_warning(
                diagnostics,
                "structure.declared-state-not-represented",
                &implementation.path,
                format!(
                    "declared state `{state}` is not represented by a JS tagged constructor, phase/tag variant, or exported symbol"
                ),
            );
        }
    }
    for command in get_string_array(
        &implementation.value,
        &["architecture", "machine", "commands"],
    ) {
        if !js_variant_represented(&source, &command) {
            push_unique_warning(
                diagnostics,
                "structure.declared-command-not-represented",
                &implementation.path,
                format!(
                    "declared command `{command}` is not represented by a JS tagged constructor, tag variant, or exported symbol"
                ),
            );
        }
    }

    let Some(transition_function) = get_str(
        &implementation.value,
        &["architecture", "machine", "transition_function"],
    ) else {
        return;
    };
    let Some(function_source) = js_function_source(&source, transition_function) else {
        return;
    };
    let transition_shaped = function_source.contains("next_state")
        && function_source.contains("events")
        && function_source.contains("effects")
        && function_source.contains("reply");
    let record_shaped = function_source.contains("transitionRecord")
        || function_source.contains("TransitionRecord")
        || function_source.contains("state_before")
        || function_source.contains("state_after");
    if !transition_shaped && !record_shaped {
        push_unique_warning(
            diagnostics,
            "structure.transition-function-not-transition-shaped",
            &implementation.path,
            format!(
                "declared transition function `{transition_function}` does not appear to return a transition output or transition record"
            ),
        );
    }
    if get_str(&implementation.value, &["architecture", "machine", "mode"])
        == Some("boundary-machine")
        && !transition_shaped
        && !record_shaped
        && function_source.contains("Reply")
    {
        push_unique_warning(
            diagnostics,
            "structure.boundary-machine-reply-only",
            &implementation.path,
            format!(
                "boundary-machine transition `{transition_function}` appears to return only a reply; expose a transition output or transition record wrapper"
            ),
        );
    }
}

fn read_js_sources_concatenated(source_root: &Path) -> String {
    let mut out = String::new();
    for path in js_source_files(source_root) {
        if let Ok(source) = fs::read_to_string(path) {
            out.push_str(&source);
            out.push('\n');
        }
    }
    out
}

fn js_variant_represented(source: &str, variant: &str) -> bool {
    let quoted = format!("\"{variant}\"");
    let single_quoted = format!("'{variant}'");
    let tag_prefix = format!("tag: \"{variant}");
    let phase = format!("phase: \"{variant}\"");
    let make_prefix = format!("function make{variant}");
    let exported_const = format!("export const {variant}");
    source.contains(&tag_prefix)
        || source.contains(&phase)
        || source.contains(&make_prefix)
        || source.contains(&exported_const)
        || source.contains(&format!("tag: {quoted}"))
        || source.contains(&format!("tag: {single_quoted}"))
}

fn js_function_source<'a>(source: &'a str, function_name: &str) -> Option<&'a str> {
    let patterns = [
        format!("function {function_name}"),
        format!("function* {function_name}"),
        format!("const {function_name} ="),
        format!("let {function_name} ="),
        format!("export function {function_name}"),
        format!("export const {function_name} ="),
    ];
    let start = patterns
        .iter()
        .filter_map(|pattern| source.find(pattern))
        .min()?;
    let after = &source[start..];
    let next_export = after
        .get(1..)
        .and_then(|rest| rest.find("\nexport "))
        .map(|index| index + 1)
        .unwrap_or(after.len());
    Some(&after[..next_export])
}

fn js_type_like_symbol_exists(summary: &JsSourceSummary, symbol: &str) -> bool {
    if summary.symbols.contains(symbol) {
        return true;
    }
    if let Some(lower_camel) = lower_camel_identifier(symbol) {
        if summary.symbols.contains(&lower_camel) {
            return true;
        }
    }
    let make_prefix = format!("make{symbol}");
    let initial_name = format!("initial{symbol}");
    summary
        .functions
        .iter()
        .any(|function| function == &initial_name || function.starts_with(&make_prefix))
}

fn lower_camel_identifier(symbol: &str) -> Option<String> {
    let mut chars = symbol.chars();
    let first = chars.next()?;
    if !first.is_ascii_uppercase() {
        return None;
    }
    Some(first.to_ascii_lowercase().to_string() + chars.as_str())
}

fn parse_swift_public_typealias(line: &str) -> Option<(String, &str)> {
    if !has_swift_public_modifier(line) {
        return None;
    }
    let rest = strip_swift_modifiers(line);
    let rest = rest.strip_prefix("typealias ")?;
    let (name, target) = rest.split_once('=')?;
    Some((swift_identifier(name.trim())?.to_string(), target.trim()))
}

fn parse_swift_function_name(line: &str) -> Option<String> {
    let rest = strip_swift_modifiers(line);
    let rest = rest.strip_prefix("func ")?;
    Some(swift_identifier(rest)?.to_string())
}

fn parse_swift_declaration_name(line: &str, kind: &str) -> Option<String> {
    let rest = strip_swift_modifiers(line);
    let rest = rest.strip_prefix(kind)?.trim_start();
    Some(swift_identifier(rest)?.to_string())
}

fn strip_swift_modifiers(mut line: &str) -> &str {
    loop {
        let trimmed = line.trim_start();
        let Some((token, rest)) = trimmed.split_once(char::is_whitespace) else {
            return trimmed;
        };
        if matches!(
            token,
            "public"
                | "open"
                | "internal"
                | "private"
                | "fileprivate"
                | "final"
                | "static"
                | "mutating"
                | "nonmutating"
        ) {
            line = rest;
        } else {
            return trimmed;
        }
    }
}

fn has_swift_public_modifier(line: &str) -> bool {
    line.split_whitespace()
        .take_while(|token| !matches!(*token, "struct" | "enum" | "class" | "typealias" | "func"))
        .any(|token| matches!(token, "public" | "open"))
}

fn swift_identifier(value: &str) -> Option<&str> {
    let identifier = value
        .trim_start()
        .split(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
        .next()
        .unwrap_or_default();
    if identifier.is_empty() {
        None
    } else {
        Some(identifier)
    }
}

fn is_swift_public_field(line: &str) -> bool {
    let rest = strip_swift_modifiers(line);
    has_swift_public_modifier(line)
        && (rest.starts_with("let ") || rest.starts_with("var "))
        && !line.contains('{')
}

fn is_swift_stored_field(line: &str) -> bool {
    let rest = strip_swift_modifiers(line);
    (rest.starts_with("let ") || rest.starts_with("var ")) && !line.contains('{')
}

fn is_swift_constructor_like(line: &str) -> bool {
    let rest = strip_swift_modifiers(line);
    has_swift_public_modifier(line)
        && (rest.starts_with("init(")
            || rest.starts_with("init?")
            || rest.starts_with("init!")
            || rest.starts_with("static func new(")
            || rest.starts_with("static func parse(")
            || rest.starts_with("static func from"))
}

fn swift_brace_delta(line: &str) -> i32 {
    let open = line.chars().filter(|character| *character == '{').count() as i32;
    let close = line.chars().filter(|character| *character == '}').count() as i32;
    open - close
}

fn swift_traps_in_line(line: &str) -> Vec<&'static str> {
    let mut traps = Vec::new();
    if line.contains("fatalError(") {
        traps.push("fatalError");
    }
    if line.contains("preconditionFailure(") {
        traps.push("preconditionFailure");
    }
    if line.contains("try!") {
        traps.push("try!");
    }
    if line.contains("as!") {
        traps.push("as!");
    }
    traps
}

fn is_swift_primitive_type(value: &str) -> bool {
    let Some(name) = swift_identifier(value.trim_start_matches('[').trim_start()) else {
        return false;
    };
    matches!(
        name,
        "String"
            | "Substring"
            | "Bool"
            | "Character"
            | "Int"
            | "Int8"
            | "Int16"
            | "Int32"
            | "Int64"
            | "UInt"
            | "UInt8"
            | "UInt16"
            | "UInt32"
            | "UInt64"
            | "Float"
            | "Double"
            | "Decimal"
            | "Date"
            | "UUID"
            | "Data"
    )
}

fn load_toml(path: &Path) -> Result<TomlValue> {
    let contents = fs::read_to_string(path)
        .with_context(|| format!("failed to read TOML `{}`", path.display()))?;
    contents
        .parse::<TomlValue>()
        .with_context(|| format!("failed to parse TOML `{}`", path.display()))
}

fn display_relative(base: &Path, path: &Path) -> String {
    path.strip_prefix(base)
        .unwrap_or(path)
        .components()
        .filter(|component| !matches!(component, Component::CurDir))
        .collect::<PathBuf>()
        .display()
        .to_string()
}

fn load_binding_module_manifest(
    implementation: &LoadedManifest,
    base: &Path,
) -> Option<LoadedManifest> {
    let declared_module = get_str(&implementation.value, &["module"])?;
    let direct = base.join("module.yaml");
    if let Ok(manifest) = load_manifest(&direct) {
        if get_str(&manifest.value, &["module", "name"]) == Some(declared_module) {
            return Some(manifest);
        }
    }

    let entries = fs::read_dir(base).ok()?;
    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        if path
            .file_name()
            .and_then(|name| name.to_str())
            .is_some_and(|name| name.ends_with(".module.yaml"))
        {
            if let Ok(manifest) = load_manifest(&path) {
                if get_str(&manifest.value, &["module", "name"]) == Some(declared_module) {
                    return Some(manifest);
                }
            }
        }
    }

    None
}

fn require_verification_categories(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    for category in REQUIRED_VERIFICATION_CATEGORIES {
        require_array(
            manifest,
            diagnostics,
            format!("verification.{category}"),
            &["verification", category],
        );
    }
}

fn check_profile_obligations(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    profiles: &[String],
) {
    if profiles.iter().any(|profile| profile == "stateful")
        && get_path(&manifest.value, &["state"]).is_none()
    {
        diagnostics.push(error(
            "profile.stateful",
            &manifest.path,
            "stateful modules must declare a `state` section",
        ));
    }

    if profiles.iter().any(|profile| profile == "distributed")
        && get_path(&manifest.value, &["operations", "reconciliation"]).is_none()
    {
        diagnostics.push(error(
            "profile.distributed.reconciliation",
            &manifest.path,
            "distributed modules must declare reconciliation or repair operations",
        ));
    }

    if profiles.iter().any(|profile| profile == "workflow")
        && get_path(&manifest.value, &["workflow"]).is_none()
    {
        diagnostics.push(error(
            "profile.workflow",
            &manifest.path,
            "workflow modules must declare a `workflow` section",
        ));
    }

    if profiles.iter().any(|profile| profile == "boundary")
        && get_path(&manifest.value, &["boundary"]).is_none()
    {
        diagnostics.push(error(
            "profile.boundary",
            &manifest.path,
            "boundary modules must declare a `boundary` section",
        ));
    }

    if profiles.iter().any(|profile| profile == "monitor")
        && get_path(&manifest.value, &["monitor"]).is_none()
    {
        diagnostics.push(error(
            "profile.monitor",
            &manifest.path,
            "monitor modules must declare a `monitor` section",
        ));
    }
}

fn check_contract_refs(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    path: &[&str],
) {
    let Some(value) = get_path(&manifest.value, path) else {
        return;
    };
    collect_contract_paths(value, &mut |contract| {
        check_relative_ref(
            manifest,
            diagnostics,
            "references.contract",
            contract,
            "referenced contract does not exist",
        );
    });
}

fn check_invariant_evidence(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let Some(invariants) =
        get_path(&manifest.value, &["invariants"]).and_then(YamlValue::as_sequence)
    else {
        return;
    };
    for invariant in invariants {
        if let Some(path) = get_str(invariant, &["verified_by"]) {
            check_relative_ref(
                manifest,
                diagnostics,
                "references.invariant-evidence",
                path,
                "referenced invariant evidence does not exist",
            );
            check_evidence_quality(manifest, diagnostics, path);
        }
    }
}

fn check_verification_paths(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let Some(verification) = get_path(&manifest.value, &["verification"]) else {
        return;
    };
    for category in verification_reference_categories() {
        let Some(paths) = get_path(verification, &[category]).and_then(YamlValue::as_sequence)
        else {
            continue;
        };
        for path in paths.iter().filter_map(YamlValue::as_str) {
            check_relative_ref(
                manifest,
                diagnostics,
                format!("references.verification.{category}"),
                path,
                "referenced verification evidence does not exist",
            );
            check_evidence_quality(manifest, diagnostics, path);
        }
    }
}

fn check_evidence_quality(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    reference: &str,
) {
    if reference.starts_with("http://")
        || reference.starts_with("https://")
        || reference.starts_with("urn:")
    {
        return;
    }

    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let full_path = base.join(reference);
    if full_path.is_dir() {
        for entry in WalkDir::new(&full_path)
            .follow_links(false)
            .into_iter()
            .filter_map(Result::ok)
            .filter(|entry| entry.file_type().is_file())
        {
            if entry.path().file_name().and_then(|name| name.to_str()) == Some("README.md") {
                continue;
            }
            let Ok(source) = fs::read_to_string(entry.path()) else {
                continue;
            };
            let nested_reference = display_relative(base, entry.path());
            check_evidence_source_quality(
                manifest,
                diagnostics,
                &nested_reference,
                &source,
                entry.path(),
            );
        }
        return;
    }

    if !full_path.is_file() {
        return;
    }
    let Ok(source) = fs::read_to_string(&full_path) else {
        return;
    };
    check_evidence_source_quality(manifest, diagnostics, reference, &source, &full_path);
}

fn check_evidence_source_quality(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    reference: &str,
    source: &str,
    full_path: &Path,
) {
    let lower = source.to_ascii_lowercase();

    if lower.contains("replace this placeholder")
        || lower.contains("evidence to add")
        || lower.contains("record the exact command used")
        || lower.contains("replace or extend this script")
    {
        push_unique_warning(
            diagnostics,
            "evidence.placeholder",
            &manifest.path,
            format!("referenced evidence `{reference}` still contains scaffold placeholder text"),
        );
    }

    if lower.contains("bootstrap")
        || lower.contains("generated scaffold")
        || lower.contains("scaffold obligations")
    {
        push_unique_warning(
            diagnostics,
            "evidence.bootstrap-active",
            &manifest.path,
            format!("referenced evidence `{reference}` still reads as bootstrap scaffold evidence"),
        );
    }

    if lower.contains("source revision: not recorded")
        || lower.contains("source revision: unknown")
        || lower.contains("before first git commit")
        || (lower.contains("local workspace") && !lower.contains("git:"))
    {
        push_unique_warning(
            diagnostics,
            "evidence.source-unpinned",
            &manifest.path,
            format!("referenced evidence `{reference}` does not pin a source revision"),
        );
    }

    if full_path.file_name().and_then(|name| name.to_str()) == Some("semantic_shape.md") {
        push_unique_warning(
            diagnostics,
            "evidence.semantic-shape-only",
            &manifest.path,
            format!("referenced evidence `{reference}` is shape evidence; use concrete law, contract, boundary, scenario, trace, runtime, recovery, or reconciliation evidence for release proof"),
        );
    }
}

fn check_change_protocols(manifest: &LoadedManifest, diagnostics: &mut Vec<Diagnostic>) {
    let Some(protocols) = change_protocol_items(&manifest.value) else {
        return;
    };

    let mut ids = BTreeSet::new();
    for (index, protocol) in protocols.iter().enumerate() {
        let Some(id) = get_str(protocol, &["id"]) else {
            diagnostics.push(error(
                "change-protocol.id",
                &manifest.path,
                format!("change protocol at index {index} is missing `id`"),
            ));
            continue;
        };
        if !ids.insert(id.to_string()) {
            diagnostics.push(error(
                "change-protocol.duplicate-id",
                &manifest.path,
                format!("duplicate change protocol id `{id}`"),
            ));
        }
        if get_str(protocol, &["applies_when"]).is_none() {
            diagnostics.push(error(
                "change-protocol.applies-when",
                &manifest.path,
                format!("change protocol `{id}` is missing `applies_when`"),
            ));
        }
        collect_change_protocol_reference_paths(protocol, &mut |reference| {
            check_relative_ref(
                manifest,
                diagnostics,
                "references.change-protocol",
                reference,
                "change protocol references an artifact that does not exist",
            );
        });
    }
}

fn check_optional_path(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    path: &[&str],
) {
    if let Some(reference) = get_str(&manifest.value, path) {
        check_relative_ref(
            manifest,
            diagnostics,
            format!("references.{}", path.join(".")),
            reference,
            "referenced path does not exist",
        );
    }
}

fn check_relative_ref(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    check: impl Into<String>,
    reference: &str,
    message: &str,
) {
    if reference.starts_with("http://")
        || reference.starts_with("https://")
        || reference.starts_with("urn:")
    {
        return;
    }

    let base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let full_path = base.join(reference);
    if !full_path.exists() {
        diagnostics.push(error(
            check,
            &manifest.path,
            format!("{message}: `{reference}`"),
        ));
    }
}

fn collect_contract_paths(value: &YamlValue, emit: &mut impl FnMut(&str)) {
    match value {
        YamlValue::Mapping(mapping) => {
            if let Some(contract) = mapping
                .get(YamlValue::String("contract".to_string()))
                .and_then(YamlValue::as_str)
            {
                emit(contract);
            }
            for child in mapping.values() {
                collect_contract_paths(child, emit);
            }
        }
        YamlValue::Sequence(items) => {
            for item in items {
                collect_contract_paths(item, emit);
            }
        }
        _ => {}
    }
}

fn change_protocol_items(value: &YamlValue) -> Option<&[YamlValue]> {
    get_path(value, &["x-change-protocols"])?
        .as_sequence()
        .map(Vec::as_slice)
}

fn collect_change_protocol_reference_paths(value: &YamlValue, emit: &mut impl FnMut(&str)) {
    let Some(references) = get_path(value, &["references"]) else {
        return;
    };
    collect_string_leaf_values(references, emit);
}

fn collect_string_leaf_values(value: &YamlValue, emit: &mut impl FnMut(&str)) {
    match value {
        YamlValue::String(reference) => emit(reference),
        YamlValue::Sequence(items) => {
            for item in items {
                collect_string_leaf_values(item, emit);
            }
        }
        YamlValue::Mapping(mapping) => {
            for child in mapping.values() {
                collect_string_leaf_values(child, emit);
            }
        }
        _ => {}
    }
}

fn scan_for_secret_like_keys(value: &YamlValue, path: &Path, diagnostics: &mut Vec<Diagnostic>) {
    fn walk(
        value: &YamlValue,
        key_path: &mut Vec<String>,
        path: &Path,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        match value {
            YamlValue::Mapping(mapping) => {
                for (key, child) in mapping {
                    let key_text = key.as_str().unwrap_or("<non-string-key>").to_string();
                    key_path.push(key_text.clone());
                    let normalized = key_text.to_ascii_lowercase().replace('-', "_");
                    if matches!(
                        normalized.as_str(),
                        "secret" | "secrets" | "password" | "token" | "access_token" | "api_key"
                    ) {
                        diagnostics.push(error(
                            "security.secret-key",
                            path,
                            format!(
                                "canonical artifacts must not contain secret-bearing fields: `{}`",
                                key_path.join(".")
                            ),
                        ));
                    }
                    walk(child, key_path, path, diagnostics);
                    key_path.pop();
                }
            }
            YamlValue::Sequence(items) => {
                for item in items {
                    walk(item, key_path, path, diagnostics);
                }
            }
            _ => {}
        }
    }

    walk(value, &mut Vec::new(), path, diagnostics);
}

fn print_module_brief(manifest: &LoadedManifest) {
    println!("# RMS Module Brief");
    println!();
    println!("Path: {}", manifest.path.display());
    println!(
        "Module: {} {}",
        get_str(&manifest.value, &["module", "name"]).unwrap_or("<unknown>"),
        get_str(&manifest.value, &["module", "version"]).unwrap_or("")
    );
    println!(
        "Purpose: {}",
        get_str(&manifest.value, &["module", "purpose"]).unwrap_or("<missing>")
    );
    println!(
        "Kind: {}",
        get_str(&manifest.value, &["module", "kind"]).unwrap_or("<missing>")
    );
    print_string_list(
        "Profiles",
        &get_string_array(&manifest.value, &["profiles"]),
    );
    print_owned_terms(&manifest.value);
    print_contract_groups("Provides", get_path(&manifest.value, &["provides"]));
    print_contract_groups("Requires", get_path(&manifest.value, &["requires"]));
    print_invariants(&manifest.value);
    print_effects(&manifest.value);
    println!(
        "Compatibility: {}",
        get_str(&manifest.value, &["compatibility", "policy"]).unwrap_or("<missing>")
    );
    print_verification(&manifest.value);
    print_change_protocols(&manifest.value);
}

fn print_module_explanation(
    manifest: &LoadedManifest,
    root: &Path,
    question: Option<&str>,
) -> Result<()> {
    println!("# RMS Module Explanation");
    println!();
    println!("Path: {}", manifest.path.display());
    if let Some(question) = question {
        println!("Question: {question}");
    }
    println!();

    println!("## What This Module Is");
    println!(
        "{} {} is a {}.",
        get_str(&manifest.value, &["module", "name"]).unwrap_or("<unknown>"),
        get_str(&manifest.value, &["module", "version"]).unwrap_or(""),
        get_str(&manifest.value, &["module", "kind"]).unwrap_or("<missing-kind>")
    );
    println!(
        "Purpose: {}",
        get_str(&manifest.value, &["module", "purpose"]).unwrap_or("<missing>")
    );
    print_string_list(
        "Profiles",
        &get_string_array(&manifest.value, &["profiles"]),
    );

    print_owned_terms(&manifest.value);

    print_contract_groups("Provides", get_path(&manifest.value, &["provides"]));
    print_contract_groups("Requires", get_path(&manifest.value, &["requires"]));

    print_invariants(&manifest.value);
    print_effects(&manifest.value);
    println!(
        "Compatibility: {}",
        get_str(&manifest.value, &["compatibility", "policy"]).unwrap_or("<missing>")
    );
    print_verification(&manifest.value);
    print_change_protocols(&manifest.value);

    println!();
    println!("## Before Changing It");
    println!("- Keep changes inside this module's ownership boundary.");
    println!("- Change public contracts first when public meaning changes.");
    println!(
        "- Declare new dependencies, effects, profiles, and recovery paths before relying on them."
    );
    println!("- Add only the smallest evidence that strongly demonstrates the changed promise.");

    let module_base = manifest.path.parent().unwrap_or_else(|| Path::new("."));
    let module_name = get_str(&manifest.value, &["module", "name"]).unwrap_or("");
    if !module_name.is_empty() {
        if let Some(implementation) = sibling_implementation_manifest(module_base, module_name)? {
            println!(
                "- Implementation binding: {}",
                implementation.path.display()
            );
            if let Some(command) = get_str(&implementation.value, &["commands", "verify"]) {
                println!("- Verification command: {command}");
            }
        }
    }

    println!();
    println!("## Useful Commands");
    println!("- rms inspect {}", manifest.path.display());
    println!(
        "- rms context {} --root {} --task \"<task>\"",
        manifest.path.display(),
        root.display()
    );
    println!("- rms validate --root {}", root.display());
    if !module_name.is_empty() && module_base.join("implementation.yaml").exists() {
        println!(
            "- rms verify {}",
            module_base.join("implementation.yaml").display()
        );
    }

    if let Some(question) = question {
        println!();
        println!("## Question Focus");
        print_question_focus(&manifest.value, question);
    }

    Ok(())
}

fn print_context_packet(manifest: &LoadedManifest, root: &Path, task: Option<&str>) -> Result<()> {
    println!("# RMS Context Packet");
    println!();
    if let Some(task) = task {
        println!("Task: {task}");
        println!();
    }

    print_module_brief(manifest);

    if let Some(task) = task {
        let report = build_route_report(&manifest.path, root, task)?;
        if report.result != RouteResult::TargetOnly {
            let mut rendered = String::new();
            append_route_recommendation_section(&mut rendered, &report)?;
            println!();
            print!("{}", rendered);
        }
    }

    println!();
    println!("## Canonical Files");
    for file_name in ["system.yaml", "context-map.yaml", "GLOSSARY.md"] {
        let path = root.join(file_name);
        if path.exists() {
            println!("- {}", path.display());
        }
    }

    println!();
    println!("## Public References");
    for reference in referenced_paths(&manifest.value) {
        let path = manifest
            .path
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .join(&reference);
        println!("- {}", path.display());
    }

    println!();
    println!("## Working Rules");
    println!("- Preserve the owning module boundary.");
    println!("- Update public contracts before implementation when public meaning changes.");
    println!("- Declare new dependencies, effects, profile obligations, and recovery paths.");
    println!("- Verify declared laws, contracts, scenarios, and boundaries that the task affects.");
    Ok(())
}

fn run_route(module: &Path, root: &Path, task: &str, json_output: bool) -> Result<()> {
    let report = build_route_report(module, root, task)?;
    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_route_report(&report);
    }
    Ok(())
}

#[derive(Debug, Serialize)]
struct RouteReport {
    result: RouteResult,
    task: String,
    target: RouteModuleSummary,
    recommendation: Option<RouteModuleSummary>,
    candidates: Vec<RouteCandidate>,
    warnings: Vec<String>,
    next_commands: Vec<String>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
enum RouteResult {
    Routed,
    Ambiguous,
    TargetOnly,
}

#[derive(Clone, Debug, Serialize)]
struct RouteModuleSummary {
    name: String,
    path: String,
    kind: String,
    shape: String,
    visibility: Option<String>,
}

#[derive(Clone, Debug, Serialize)]
struct RouteCandidate {
    module: RouteModuleSummary,
    score: i32,
    reasons: Vec<String>,
}

fn build_route_report(module: &Path, root: &Path, task: &str) -> Result<RouteReport> {
    let target_manifest = load_manifest(module)?;
    let target_name = get_str(&target_manifest.value, &["module", "name"])
        .unwrap_or("<unknown>")
        .to_string();
    let mut modules = discover_module_index(root)?;
    modules
        .entry(target_name.clone())
        .or_insert_with(|| ModuleIndexEntry {
            name: target_name.clone(),
            path: target_manifest.path.clone(),
            value: target_manifest.value.clone(),
        });

    let target_entry = modules
        .get(&target_name)
        .cloned()
        .unwrap_or(ModuleIndexEntry {
            name: target_name.clone(),
            path: target_manifest.path.clone(),
            value: target_manifest.value.clone(),
        });
    let target_summary = route_module_summary(&target_entry, None);
    let children = composition_children(&modules)
        .into_iter()
        .filter(|child| child.parent == target_name)
        .collect::<Vec<_>>();

    if children.is_empty() {
        let next_commands = vec![
            format!(
                "rms context {} --root {} --task {:?}",
                module.display(),
                root.display(),
                task
            ),
            format!(
                "rms implement {} --root {} --task {:?}",
                module.display(),
                root.display(),
                task
            ),
        ];
        return Ok(RouteReport {
            result: RouteResult::TargetOnly,
            task: task.to_string(),
            target: target_summary.clone(),
            recommendation: Some(target_summary.clone()),
            candidates: vec![RouteCandidate {
                module: target_summary,
                score: 0,
                reasons: vec![
                    "target module has no declared composition.contains children".to_string(),
                    "the target remains the owning boundary unless canonical manifests say otherwise"
                        .to_string(),
                ],
            }],
            warnings: Vec::new(),
            next_commands,
        });
    }

    let exports = composition_exports(&modules)
        .into_iter()
        .filter(|export| export.parent == target_name)
        .collect::<Vec<_>>();
    let mut candidates = Vec::new();
    let mut warnings = vec![format!(
        "`{target_name}` is a composite parent; route implementation work to a child unless the task changes parent composition, exported public surface, or parent evidence."
    )];
    if task_mentions_public_surface_change(task) {
        warnings.push(
            "public surface changes may require updating the parent contract and the exported child contract together".to_string(),
        );
    }

    for child in children {
        let Some(child_entry) = modules.get(&child.name) else {
            candidates.push(RouteCandidate {
                module: RouteModuleSummary {
                    name: child.name.clone(),
                    path: child.path.unwrap_or_else(|| "<missing>".to_string()),
                    kind: "<missing>".to_string(),
                    shape: "<unknown>".to_string(),
                    visibility: Some(child.visibility),
                },
                score: -10,
                reasons: vec![
                    "declared child module was not discovered under the route root".to_string(),
                ],
            });
            continue;
        };
        let mut reasons = Vec::new();
        let mut score = score_route_candidate(task, child_entry, &mut reasons);
        if task_mentions_module(task, &child.name) {
            score += 5;
            reasons.push(format!(
                "task mentions child module `{}` or one of its semantic name segments",
                child.name
            ));
        }
        for export in exports.iter().filter(|export| export.from == child.name) {
            if task_mentions_token(task, &export.name) || task_mentions_boundary_surface(task) {
                score += 3;
                reasons.push(format!(
                    "child backs parent exported {} `{}`",
                    export.group, export.name
                ));
            }
        }
        if reasons.is_empty() {
            reasons
                .push("no strong task-language match; kept as a possible child route".to_string());
        }
        candidates.push(RouteCandidate {
            module: route_module_summary(child_entry, Some(child.visibility)),
            score,
            reasons,
        });
    }

    candidates.sort_by(|left, right| {
        right
            .score
            .cmp(&left.score)
            .then_with(|| left.module.name.cmp(&right.module.name))
    });
    let recommendation = unique_top_route(&candidates).map(|candidate| candidate.module.clone());
    let result = if recommendation.is_some() {
        RouteResult::Routed
    } else {
        warnings.push(
            "route is ambiguous; inspect the child manifests and choose the owner before editing"
                .to_string(),
        );
        RouteResult::Ambiguous
    };
    let next_target = recommendation
        .as_ref()
        .map(|module| module.path.clone())
        .unwrap_or_else(|| module.display().to_string());
    let next_commands = vec![
        format!("rms explain {next_target}"),
        format!(
            "rms context {next_target} --root {} --task {:?}",
            root.display(),
            task
        ),
    ];

    Ok(RouteReport {
        result,
        task: task.to_string(),
        target: target_summary,
        recommendation,
        candidates,
        warnings,
        next_commands,
    })
}

fn discover_module_index(root: &Path) -> Result<BTreeMap<String, ModuleIndexEntry>> {
    let targets = discover_targets(root, vec![], vec![], vec![], vec![], vec![], vec![])?;
    let mut modules = BTreeMap::new();
    for target in targets {
        let manifest = load_manifest(&target)?;
        if get_str(&manifest.value, &["spec"]) != Some("rms/module/v0.1") {
            continue;
        }
        let name = get_str(&manifest.value, &["module", "name"])
            .unwrap_or("<unknown>")
            .to_string();
        modules.insert(
            name.clone(),
            ModuleIndexEntry {
                name,
                path: target,
                value: manifest.value,
            },
        );
    }
    Ok(modules)
}

fn route_module_summary(
    module: &ModuleIndexEntry,
    visibility: Option<String>,
) -> RouteModuleSummary {
    RouteModuleSummary {
        name: module.name.clone(),
        path: module.path.display().to_string(),
        kind: get_str(&module.value, &["module", "kind"])
            .unwrap_or("<missing>")
            .to_string(),
        shape: route_shape(&module.value),
        visibility,
    }
}

fn route_shape(value: &YamlValue) -> String {
    if let Some(shape) = get_str(value, &["x-scaffold", "shape"]) {
        return shape.to_string();
    }
    let kind = get_str(value, &["module", "kind"]).unwrap_or("");
    let profiles = get_string_array(value, &["profiles"]);
    if kind == "composite" || get_path(value, &["composition"]).is_some() {
        "composite".to_string()
    } else if profiles.iter().any(|profile| profile == "monitor") || kind == "monitor" {
        "runtime-monitor".to_string()
    } else if profiles.iter().any(|profile| profile == "workflow") {
        "workflow".to_string()
    } else if profiles.iter().any(|profile| profile == "stateful") && kind == "adapter" {
        "storage-adapter".to_string()
    } else if profiles.iter().any(|profile| profile == "boundary") || kind == "adapter" {
        "boundary-adapter".to_string()
    } else {
        "<unknown>".to_string()
    }
}

fn score_route_candidate(task: &str, module: &ModuleIndexEntry, reasons: &mut Vec<String>) -> i32 {
    let shape = route_shape(&module.value);
    let mut score = 0;
    match shape.as_str() {
        "domain-engine" => {
            score += score_keywords(
                task,
                &[
                    "rule",
                    "rules",
                    "invariant",
                    "valid",
                    "invalid",
                    "transition",
                    "state",
                    "decision",
                    "pure",
                    "engine",
                    "law",
                    "fuzz",
                    "property",
                    "adt",
                    "variant",
                    "constructor",
                ],
            );
            if score > 0 {
                reasons.push("task language points at pure decisions, invariants, representation, or transitions".to_string());
            }
        }
        "boundary-adapter" => {
            score += score_keywords(
                task,
                &[
                    "ui",
                    "web",
                    "browser",
                    "cli",
                    "screen",
                    "display",
                    "input",
                    "output",
                    "parse",
                    "parser",
                    "adapter",
                    "button",
                    "form",
                    "http",
                    "api",
                    "command-line",
                ],
            );
            if score > 0 {
                reasons.push(
                    "task language points at parsing, UI, IO, or boundary effects".to_string(),
                );
            }
        }
        "workflow" => {
            score += score_keywords(
                task,
                &[
                    "workflow",
                    "deadline",
                    "compensation",
                    "recover",
                    "recovery",
                    "step",
                    "orchestrate",
                    "saga",
                ],
            );
            if score > 0 {
                reasons.push(
                    "task language points at ordered workflow, deadlines, or recovery".to_string(),
                );
            }
        }
        "runtime-monitor" => {
            score += score_keywords(
                task,
                &[
                    "monitor",
                    "runtime",
                    "observe",
                    "observation",
                    "derived",
                    "stream",
                    "trigger",
                    "alarm",
                    "envelope",
                    "supervisory",
                    "guard",
                    "fallback",
                    "override",
                    "violation",
                ],
            );
            if score > 0 {
                reasons.push(
                    "task language points at runtime observation, derived facts, triggers, or supervisory behavior".to_string(),
                );
            }
        }
        "storage-adapter" => {
            score += score_keywords(
                task,
                &[
                    "store",
                    "storage",
                    "persist",
                    "persistence",
                    "database",
                    "migration",
                    "schema",
                    "read-model",
                    "cache",
                ],
            );
            if score > 0 {
                reasons.push(
                    "task language points at persistence, migrations, or stored state".to_string(),
                );
            }
        }
        "integration-adapter" => {
            score += score_keywords(
                task,
                &[
                    "external",
                    "service",
                    "retry",
                    "timeout",
                    "idempotency",
                    "reconcile",
                    "reconciliation",
                    "provider",
                    "webhook",
                ],
            );
            if score > 0 {
                reasons.push(
                    "task language points at external service integration or reconciliation"
                        .to_string(),
                );
            }
        }
        _ => {}
    }

    for (group, name) in public_surface_names(&module.value) {
        if task_mentions_token(task, &name) {
            score += 2;
            reasons.push(format!("task mentions public {group} `{name}`"));
        }
    }
    score
}

fn public_surface_names(value: &YamlValue) -> Vec<(String, String)> {
    let mut names = Vec::new();
    let Some(provides) = get_path(value, &["provides"]).and_then(YamlValue::as_mapping) else {
        return names;
    };
    for (group, entries) in provides {
        let Some(group) = group.as_str() else {
            continue;
        };
        let Some(entries) = entries.as_sequence() else {
            continue;
        };
        for entry in entries {
            if let Some((name, _)) = named_reference(entry) {
                names.push((group.to_string(), name));
            }
        }
    }
    names
}

fn unique_top_route(candidates: &[RouteCandidate]) -> Option<&RouteCandidate> {
    let top = candidates.first()?;
    if top.score <= 0 {
        return None;
    }
    if candidates
        .get(1)
        .is_some_and(|next| next.score == top.score)
    {
        return None;
    }
    Some(top)
}

fn score_keywords(task: &str, keywords: &[&str]) -> i32 {
    keywords
        .iter()
        .filter(|keyword| task_mentions_token(task, keyword))
        .count() as i32
}

fn task_mentions_module(task: &str, module_name: &str) -> bool {
    task_mentions_token(task, module_name)
        || module_name
            .split(['-', '_'])
            .filter(|segment| segment.len() > 2)
            .any(|segment| task_mentions_token(task, segment))
}

fn task_mentions_boundary_surface(task: &str) -> bool {
    score_keywords(
        task,
        &[
            "public", "surface", "command", "query", "event", "api", "cli", "ui", "web",
        ],
    ) > 0
}

fn task_mentions_public_surface_change(task: &str) -> bool {
    score_keywords(
        task,
        &[
            "contract",
            "public",
            "compatibility",
            "breaking",
            "command",
            "query",
            "event",
            "api",
        ],
    ) > 0
}

fn task_mentions_token(task: &str, token: &str) -> bool {
    let normalized_task = semantic_id_segment(task);
    let normalized_token = semantic_id_segment(token);
    if normalized_token.is_empty() {
        return false;
    }
    normalized_task
        .split('-')
        .collect::<Vec<_>>()
        .windows(normalized_token.split('-').count())
        .any(|window| window.join("-") == normalized_token)
        || normalized_task == normalized_token
}

fn print_route_report(report: &RouteReport) {
    println!("# RMS Route");
    println!();
    println!("Task: {}", report.task);
    println!(
        "Target: {} ({}, shape: {})",
        report.target.name, report.target.kind, report.target.shape
    );
    println!("Result: {}", route_result_label(report.result));
    if let Some(recommendation) = &report.recommendation {
        println!(
            "Recommended module: {} ({}, shape: {})",
            recommendation.name, recommendation.kind, recommendation.shape
        );
        println!("Path: {}", recommendation.path);
    }
    println!();
    println!("## Candidates");
    for candidate in &report.candidates {
        let visibility = candidate.module.visibility.as_deref().unwrap_or("<target>");
        println!(
            "- {} score={} visibility={} shape={} path={}",
            candidate.module.name,
            candidate.score,
            visibility,
            candidate.module.shape,
            candidate.module.path
        );
        for reason in &candidate.reasons {
            println!("  - {reason}");
        }
    }
    if !report.warnings.is_empty() {
        println!();
        println!("## Warnings");
        for warning in &report.warnings {
            println!("- {warning}");
        }
    }
    println!();
    print_string_list("Next Commands", &report.next_commands);
}

fn route_result_label(result: RouteResult) -> &'static str {
    match result {
        RouteResult::Routed => "routed",
        RouteResult::Ambiguous => "ambiguous",
        RouteResult::TargetOnly => "target-only",
    }
}

