fn render_js_transition_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"import {{
  initial{state},
  make{event}Accepted,
  make{event}Rejected,
  make{rejection}InvalidCommand,
  make{reply}Accepted,
  make{reply}Rejected,
}} from "./representation.mjs";

export function transition(command) {{
  return transitionRecord(command).output;
}}

export function transitionRecord(command) {{
  const stateBefore = initial{state}();
  let reply;
  let event;
  let branch;
  switch (command?.tag) {{
    case "{command}.Accept":
      reply = make{reply}Accepted();
      event = make{event}Accepted();
      branch = "Accept";
      break;
    case "{command}.Reject":
      {{
        const rejection = make{rejection}InvalidCommand(command.reason);
        reply = make{reply}Rejected(rejection);
        event = make{event}Rejected(rejection);
        branch = "Reject";
      }}
      break;
    default:
      {{
        const rejection = make{rejection}InvalidCommand("unknown-command");
        reply = make{reply}Rejected(rejection);
        event = make{event}Rejected(rejection);
        branch = "Unknown";
      }}
  }}
  const nextState = initial{state}();
  const output = Object.freeze({{
    tag: "{transition}",
    next_state: nextState,
    events: Object.freeze([event]),
    commands: Object.freeze([]),
    effects: Object.freeze([]),
    reply,
  }});
  return Object.freeze({{
    tag: "{transition_record}",
    state_before: stateBefore,
    state_after: nextState,
    input: command,
    output,
    source: Object.freeze({{
      tag: "{source_provenance}",
      file: "src/transition.mjs",
      function: "transitionRecord",
      branch,
    }}),
  }});
}}

export function replayTrace(commands) {{
  return commands.map(transitionRecord);
}}

export const {machine} = Object.freeze({{
  transition,
  transitionRecord,
  replayTrace,
}});
"#,
        command = names.command,
        event = names.event,
        machine = names.machine,
        rejection = names.rejection,
        reply = names.reply,
        source_provenance = names.source_provenance,
        state = names.state,
        transition = names.transition,
        transition_record = names.transition_record,
    )
}

fn render_js_parser_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"import {{
  make{command}Accept,
  make{command_envelope},
  make{command}Reject,
  make{label},
  make{rejection}MalformedInput,
}} from "./representation.mjs";

export function parseCommand(input) {{
  const label = make{label}(input?.label ?? input);
  if (!label) {{
    return Object.freeze({{
      tag: "{prefix}ParseRejected",
      rejection: make{rejection}MalformedInput("missing-label"),
    }});
  }}

  const command = input?.reject === true
    ? make{command}Reject(label)
    : make{command}Accept(label);
  return Object.freeze({{
    tag: "{prefix}ParsedCommand",
    command_envelope: make{command_envelope}(command),
  }});
}}
"#,
        command = names.command,
        command_envelope = names.command_envelope,
        label = names.label,
        prefix = names.prefix,
        rejection = names.rejection,
    )
}

fn render_js_adapter_mjs(names: &InnerStructureNames, shape: ScaffoldShape) -> String {
    let states = starter_states_for_shape(shape);
    let state_before = states.first().map(String::as_str).unwrap_or("Ready");
    let accepted_state = states
        .iter()
        .find(|state| state.as_str() == "Completed")
        .or_else(|| states.iter().find(|state| state.as_str() == "Ready"))
        .map(String::as_str)
        .unwrap_or(state_before);
    let rejected_state = states
        .iter()
        .find(|state| state.as_str() == "Rejected")
        .or_else(|| states.iter().find(|state| state.as_str() == "Failed"))
        .map(String::as_str)
        .unwrap_or(state_before);
    let mut state_imports = Vec::<&str>::new();
    for state in [state_before, accepted_state, rejected_state] {
        if !state_imports.contains(&state) {
            state_imports.push(state);
        }
    }
    let state_imports = state_imports.join(",\n  ");
    format!(
        r#"import {{
  {state_imports},
  make{event}Accepted,
  make{event}Rejected,
  make{reply}Accepted,
  make{reply}Rejected,
}} from "./representation.mjs";
import {{ parseCommand }} from "./parser.mjs";

function boundaryOutput(nextState, event, reply) {{
  return Object.freeze({{
    tag: "{transition}",
    next_state: nextState,
    events: Object.freeze([event]),
    commands: Object.freeze([]),
    effects: Object.freeze([]),
    reply,
  }});
}}

export function handleBoundaryTransition(input, ports) {{
  const stateBefore = {state_before};
  const parsed = parseCommand(input);
  if (parsed.tag === "{prefix}ParseRejected") {{
    const reply = make{reply}Rejected(parsed.rejection);
    const event = make{event}Rejected(parsed.rejection);
    const output = boundaryOutput({rejected_state}, event, reply);
    return Object.freeze({{
      tag: "{transition_record}",
      state_before: stateBefore,
      state_after: {rejected_state},
      input,
      output,
      source: Object.freeze({{
        tag: "{source_provenance}",
        file: "src/adapter.mjs",
        function: "handleBoundaryTransition",
        branch: "ParseRejected",
      }}),
    }});
  }}

  ports?.write?.(parsed.command_envelope);
  const reply = make{reply}Accepted();
  const event = make{event}Accepted();
  const output = boundaryOutput({accepted_state}, event, reply);
  return Object.freeze({{
    tag: "{transition_record}",
    state_before: stateBefore,
    state_after: {accepted_state},
    input: parsed.command_envelope,
    output,
    source: Object.freeze({{
      tag: "{source_provenance}",
      file: "src/adapter.mjs",
      function: "handleBoundaryTransition",
      branch: "ParsedCommand",
    }}),
  }});
}}

export function handleBoundaryInput(input, ports) {{
  return handleBoundaryTransition(input, ports).output.reply;
}}

export const {machine} = Object.freeze({{
  handleBoundaryTransition,
  handleBoundaryInput,
}});
"#,
        accepted_state = accepted_state,
        event = names.event,
        machine = names.machine,
        prefix = names.prefix,
        rejected_state = rejected_state,
        reply = names.reply,
        source_provenance = names.source_provenance,
        state_before = state_before,
        state_imports = state_imports,
        transition = names.transition,
        transition_record = names.transition_record,
    )
}

fn render_js_trace_test_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"import assert from "node:assert/strict";
import test from "node:test";
import {{
  make{command}Accept,
  make{label},
}} from "../src/representation.mjs";
import {{ replayTrace, {machine} }} from "../src/transition.mjs";

test("{machine} rejects invalid representation", () => {{
  assert.equal(make{label}(""), null);
}});

test("{machine} replays accepted commands", () => {{
  const label = make{label}("example");
  assert.deepEqual(replayTrace([make{command}Accept(label)]).map((item) => item.output.reply.tag), [
    "{reply}.Accepted",
  ]);
  assert.equal(replayTrace([make{command}Accept(label)])[0].source.branch, "Accept");
  assert.equal({machine}.transition(make{command}Accept(label)).reply.tag, "{reply}.Accepted");
}});
"#,
        command = names.command,
        label = names.label,
        machine = names.machine,
        reply = names.reply,
    )
}

fn render_js_boundary_test_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"import assert from "node:assert/strict";
import test from "node:test";
import {{ handleBoundaryInput }} from "../src/adapter.mjs";
import {{ createPorts }} from "../src/ports.mjs";

test("{machine} boundary adapter rejects malformed input", () => {{
  const ports = createPorts();
  assert.equal(handleBoundaryInput("", ports).tag, "{reply}.Rejected");
}});

test("{machine} boundary adapter writes parsed commands", () => {{
  const written = [];
  const ports = createPorts({{ write: (command) => written.push(command) }});
  assert.equal(handleBoundaryInput("example", ports).tag, "{reply}.Accepted");
  assert.equal(written.length, 1);
  assert.equal(written[0].tag, "{command_envelope}");
  assert.equal(written[0].command.tag, "{command}.Accept");
}});
"#,
        command = names.command,
        command_envelope = names.command_envelope,
        machine = names.machine,
        reply = names.reply,
    )
}

fn render_js_browser_controller_mjs(public_command: &str) -> String {
    format!(
        r#"import {{ handleBoundaryInput }} from "../src/adapter.mjs";

export async function runRmsSurface(input, ports) {{
  return await handleBoundaryInput(input, ports);
}}

export function declaredRmsSurface() {{
  return Object.freeze({{
    kind: "runnable-boundary",
    surface: "browser",
    command: "{public_command}",
    delegatesTo: "src/adapter.mjs#handleBoundaryInput",
  }});
}}

export function mountRmsSurface(root = document, ports) {{
  const form = root.querySelector("[data-rms-surface-form]");
  const output = root.querySelector("[data-rms-surface-output]");
  const run = async () => {{
    const formData = new FormData(form);
    const input = Object.fromEntries(formData.entries());
    const reply = await runRmsSurface(input, ports);
    if (output) {{
      output.textContent = JSON.stringify(reply, null, 2);
    }}
    return reply;
  }};
  form?.addEventListener("submit", async (event) => {{
    event.preventDefault();
    await run();
  }});
  return Object.freeze({{ run }});
}}
"#
    )
}

fn render_js_browser_app_mjs(controller_import: &str) -> String {
    format!(
        r#"import {{ mountRmsSurface }} from "{controller_import}";

mountRmsSurface(document);
"#
    )
}

